/** What ModBuild.cyrus.assets records about the request (lib/cyrus/meta.ts). */
export type CyrusAssetMeta = { requested: BuildAssetKind[]; allowed: BuildAssetKind[]; notices: string[]; projectId?: string; namespace?: string; datapack?: { route: boolean; matched: string[]; limits: string[] } };

