// Cyrus R3 gameplay designers: the DESIGN IR. A typed Custom Item Designer spec (ItemDesign) with an ability/event
// graph (AbilityGraph = trigger -> conditions -> actions, with branches) that the compiler (./compile.ts) turns into
// straight Java calling the verified component library (./components). Nothing here is free-form code: every node is a
// fixed kind, every number has a hard min/max (CAPS below; the JSON Schema carries them too), every activation has a
// static worst-case resource budget that must fit BUDGET, loops are bounded (query_* `max`, delayed `delayTicks` and
// nesting depth) and there is no way to run a command or arbitrary code. Numbers, texts and sound keys become config.yml
// parameters (editable without regenerating the mod, see ./params.ts); structure (kinds, effects, particles, targets)
// is code.
//
// Files: the build model writes one ItemDesign per file at assets/designs/<id>.json; a mod has at most
// DESIGN_LIMITS.maxItems of them. Identifiers live in the project's reserved namespace (engine-core identifiers):
// an item's full id is `nx_<8>:<id>`. Validation never throws: { ok, design | errors, warnings, checks, budgets }.
// The JSON Schema (designer.v1.schema.json) is generated from these Zod types (scripts/cyrus/build-designer-artifacts.ts;
// a test fails while it is stale).
import { z } from "zod";
import { NAMESPACE_RE, buildIdentifier } from "../engine-core/identifiers";
import { IngredientSchema, TEXT_COLORS, canonicalJson } from "../datapack/spec";
import { compareMc, isVanilla, missingIdReason, vanillaIds } from "../datapack/versions";
import { getVersion } from "../versions/registry";

export const DESIGN_SPEC_VERSION = 1;
export { canonicalJson };

/** Per-mod limits. */
export const DESIGN_LIMITS = { maxItems: 6, maxSpecBytes: 64 * 1024, maxAbilities: 6, maxNodes: 48, maxDepth: 3, maxConditions: 8, maxActions: 16, maxMarks: 4, maxPassives: 4, maxLore: 6, maxPermissions: 8 } as const;

/**
 * Hard caps on every number (inclusive). The config loader clamps to the SAME caps at runtime, so a hand-edited
 * config.yml can never exceed them. Ticks: 20 = 1 second.
 */
export const CAPS = {
  cooldownTicks: [0, 72000], // up to 1 hour
  chargesMax: [1, 20],
  chargeRegenTicks: [20, 72000],
  targetRange: [1, 32], // blocks the click triggers look for a target / point
  periodTicks: [10, 1200], // held_interval: never faster than twice a second
  minChargeTicks: [5, 200],
  maxChargeTicks: [10, 400],
  damage: [0, 40], // health points (2 = one heart)
  heal: [0, 20],
  potionTicks: [1, 1200], // up to 60 s
  amplifier: [0, 4], // level I..V
  strength: [0, 3], // knockback / pull / push horizontal velocity (blocks per tick)
  vertical: [0, 1.5],
  teleportRange: [1, 16],
  projectileSpeed: [0.2, 3],
  projectileLifetime: [20, 200],
  particleCount: [1, 64],
  particleSpread: [0, 4],
  particleSpeed: [0, 1],
  volume: [0, 2],
  pitch: [0.5, 2],
  giveCount: [1, 64],
  chargeCost: [1, 5],
  markTicks: [20, 1200],
  marksPerOwner: [1, 32],
  queryMarkedRadius: [1, 32],
  queryNearbyRadius: [1, 12],
  queryMax: [1, 16],
  delayTicks: [1, 100],
  chance: [0, 1],
  healthFraction: [0, 1],
  timeOfDay: [0, 23999],
  titleFadeTicks: [0, 40],
  titleStayTicks: [10, 200],
  passiveAmplifier: [0, 2],
  lootChance: [0, 1],
  statDamage: [1, 40], // shown attack damage (player base 1 + modifier)
  statAttackSpeed: [0.25, 4], // attacks per second
  durability: [1, 10000],
} as const satisfies Record<string, readonly [number, number]>;
export type CapName = keyof typeof CAPS;

/** Per-activation budget (static worst case must fit; the runtime Budget component enforces the same numbers). */
export const BUDGET = { actions: 64, entities: 32, tasks: 8, particles: 512, projectiles: 3 } as const;
/** Plugin-wide runtime caps (component constants). */
export const RUNTIME_CAPS = { liveTasks: 128, marksTotal: 2048, textChars: 120, titleChars: 40, subtitleChars: 60 } as const;

const capNum = (c: CapName) => z.number().min(CAPS[c][0]).max(CAPS[c][1]);
const capInt = (c: CapName) => z.number().int().min(CAPS[c][0]).max(CAPS[c][1]);

const KEY = /^[a-z][a-z0-9_]{1,31}$/;
const Key = z.string().regex(KEY, "2-32 chars: lowercase letters, digits, _; starts with a letter");
const VanillaRef = z.string().max(80).regex(/^minecraft:[a-z0-9_./]+$/, "a vanilla id like minecraft:diamond");
const NsRef = z.string().max(100).regex(/^[a-z0-9_.-]+:[a-z0-9_./-]+$/, "a namespaced id like nx_abcd1234:void_reaper");
const SoundKey = z.string().max(100).regex(/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/, "a namespaced sound key like nx_abcd1234:void_reaper.pull or minecraft:entity.enderman.teleport");
export const COLORS = TEXT_COLORS;
const Color = z.union([z.enum(TEXT_COLORS), z.string().regex(/^#[0-9a-fA-F]{6}$/)]);
const Text = (max: number) => z.string().min(1).max(max).regex(/^[^\u0000-\u001f§]*$/, "plain text (no control characters or § codes)");
const StyledText = z.strictObject({ text: Text(60), color: Color.optional() });

// ------------------------------------------------------------------------------------------------ catalogs (curated)
/** Data-free particles that exist with the same Bukkit name on every registry version (catalog-compiled on 1.21.11 + 26.2). */
export const PARTICLES = ["flame", "soul_fire_flame", "portal", "reverse_portal", "end_rod", "crit", "enchanted_hit", "witch", "smoke", "large_smoke", "cloud", "heart", "happy_villager", "angry_villager", "enchant", "firework", "totem_of_undying", "sweep_attack", "electric_spark", "glow", "snowflake", "soul", "poof", "note", "damage_indicator", "squid_ink", "explosion", "sonic_boom"] as const;
/** Potion effects (vanilla ids; Java constant = UPPER_SNAKE, the post-1.20.5 names). */
export const EFFECTS = ["speed", "slowness", "haste", "mining_fatigue", "strength", "instant_health", "instant_damage", "jump_boost", "nausea", "regeneration", "resistance", "fire_resistance", "water_breathing", "invisibility", "blindness", "night_vision", "hunger", "weakness", "poison", "wither", "health_boost", "absorption", "saturation", "glowing", "levitation", "luck", "unluck", "slow_falling", "conduit_power", "dolphins_grace", "darkness"] as const;
/** Harmful effects: a passive may not grant them to the holder. */
export const HARMFUL_EFFECTS = ["slowness", "mining_fatigue", "instant_damage", "nausea", "blindness", "hunger", "weakness", "poison", "wither", "levitation", "unluck", "darkness"] as const;
export const PROJECTILES = ["snowball", "arrow", "small_fireball", "wind_charge"] as const;
export const TARGET_KINDS = ["player", "hostile", "animal", "living"] as const;
/** Base items that may carry item_consume (eaten/drunk normally; chorus fruit and milk excluded: they teleport / clear effects). */
export const CONSUMABLE_BASES = ["apple", "golden_apple", "bread", "carrot", "golden_carrot", "baked_potato", "cookie", "melon_slice", "sweet_berries", "glow_berries", "honey_bottle", "potion", "dried_kelp", "pumpkin_pie", "cooked_beef", "cooked_chicken", "cooked_porkchop", "cooked_mutton", "cooked_cod", "cooked_salmon", "beetroot", "mushroom_stew", "rabbit_stew", "beetroot_soup", "suspicious_stew"] as const;
/** Base items never allowed (operator/creative items, items whose own right-click does something drastic). */
export const BANNED_BASES = /^(air|command_block.*|chain_command_block|repeating_command_block|structure_block|structure_void|jigsaw|barrier|light|debug_stick|knowledge_book|.*_spawn_egg|ender_pearl|ender_eye|chorus_fruit|milk_bucket|written_book|bundle|.*_bundle|test_block|test_instance_block)$/;

// ---------------------------------------------------------------------------------------------------------- triggers
export const TRIGGER_TYPES = ["right_click", "left_click_hit_entity", "sneak_right_click", "kill_entity", "projectile_hit", "held_interval", "join", "death", "item_consume", "charge_release"] as const;
export type TriggerType = (typeof TRIGGER_TYPES)[number];
const Range = { targetRange: capNum("targetRange").optional() };
export const TriggerSchema = z.discriminatedUnion("type", [
  /** Right-click with the item in the main hand (not sneaking, unless the item has no sneak right-click ability). targetRange: look for a target entity / point. */
  z.strictObject({ type: z.literal("right_click"), ...Range }),
  z.strictObject({ type: z.literal("left_click_hit_entity") }),
  z.strictObject({ type: z.literal("sneak_right_click"), ...Range }),
  z.strictObject({ type: z.literal("kill_entity") }),
  /** A projectile launched by this item's launch_projectile with the same tag hits something. */
  z.strictObject({ type: z.literal("projectile_hit"), tag: Key }),
  /** Every periodTicks while the item is held (main hand) or carried (inventory). */
  z.strictObject({ type: z.literal("held_interval"), periodTicks: capInt("periodTicks"), slot: z.enum(["main_hand", "inventory"]).optional() }),
  /** On join / on death while the item is in the inventory. */
  z.strictObject({ type: z.literal("join") }),
  z.strictObject({ type: z.literal("death") }),
  z.strictObject({ type: z.literal("item_consume") }),
  /** Hold sneak (with the item in the main hand) to charge, then release: right-click while still sneaking, or stop sneaking. */
  z.strictObject({ type: z.literal("charge_release"), minChargeTicks: capInt("minChargeTicks"), maxChargeTicks: capInt("maxChargeTicks"), release: z.enum(["right_click", "unsneak"]), ...Range }),
]);
export type Trigger = z.infer<typeof TriggerSchema>;

// -------------------------------------------------------------------------------------------------------- conditions
const Neg = { negate: z.boolean().optional() };
const ConditionSchema = z.discriminatedUnion("type", [
  /** Another ability's cooldown (own ability: automatic when cooldownTicks is set). */
  z.strictObject({ type: z.literal("cooldown_ready"), ability: Key.optional(), ...Neg }),
  /** Permission `<namespace>.<node>`, declared in the item's permissions. */
  z.strictObject({ type: z.literal("has_permission"), node: z.string().regex(/^[a-z0-9_]+(\.[a-z0-9_]+){0,3}$/), ...Neg }),
  z.strictObject({ type: z.literal("target_is"), kinds: z.array(z.enum(TARGET_KINDS)).max(4).optional(), types: z.array(VanillaRef).min(1).max(16).optional(), ...Neg }),
  z.strictObject({ type: z.literal("world_in"), worlds: z.array(z.string().regex(/^[A-Za-z0-9_./-]{1,64}$/)).min(1).max(8), ...Neg }),
  z.strictObject({ type: z.literal("health_below"), subject: z.enum(["self", "target"]), fraction: capNum("healthFraction"), ...Neg }),
  z.strictObject({ type: z.literal("health_above"), subject: z.enum(["self", "target"]), fraction: capNum("healthFraction"), ...Neg }),
  /** The given design item (this mod) is in that slot. */
  z.strictObject({ type: z.literal("item_identity"), slot: z.enum(["main_hand", "off_hand"]), item: Key, ...Neg }),
  z.strictObject({ type: z.literal("sneaking"), ...Neg }),
  z.strictObject({ type: z.literal("charges_available"), ability: Key.optional(), amount: capInt("chargeCost"), ...Neg }),
  /** Seeded random (java.util.Random with general.random_seed): the TS simulator draws the same sequence. */
  z.strictObject({ type: z.literal("random_chance"), chance: capNum("chance"), ...Neg }),
  /** World time in ticks (0 = sunrise, 6000 noon, 13000 night, 18000 midnight); from > to wraps over midnight. */
  z.strictObject({ type: z.literal("time_of_day"), from: capInt("timeOfDay"), to: capInt("timeOfDay"), ...Neg }),
]);
export type Condition = z.infer<typeof ConditionSchema>;
export type ConditionType = Condition["type"];
export const CONDITION_TYPES = ConditionSchema.options.map((o) => o.shape.type.value) as ConditionType[];

// ----------------------------------------------------------------------------------------------------------- actions
const Who = z.enum(["self", "target"]);
const At = z.enum(["self", "target", "point"]);
const Charge = { scaleWithCharge: z.boolean().optional() };
export type Action =
  | { type: "damage"; amount: number; target?: "self" | "target"; scaleWithCharge?: boolean }
  | { type: "heal"; amount: number; target?: "self" | "target"; scaleWithCharge?: boolean }
  | { type: "potion_effect"; effect: (typeof EFFECTS)[number]; durationTicks: number; amplifier?: number; target?: "self" | "target" }
  | { type: "knockback"; strength: number; vertical?: number; target?: "self" | "target"; scaleWithCharge?: boolean }
  | { type: "pull_to"; to: "self" | "point"; strength: number; vertical?: number; target?: "self" | "target"; scaleWithCharge?: boolean }
  | { type: "push_from"; from: "self" | "point"; strength: number; vertical?: number; target?: "self" | "target"; scaleWithCharge?: boolean }
  | { type: "teleport_short"; range: number }
  | { type: "launch_projectile"; kind: (typeof PROJECTILES)[number]; speed: number; tag?: string; lifetimeTicks?: number }
  | { type: "spawn_particles"; particle: (typeof PARTICLES)[number]; count: number; spread?: number; speed?: number; at?: "self" | "target" | "point" }
  | { type: "play_sound"; sound: string; volume?: number; pitch?: number; at?: "self" | "target" | "point" }
  | { type: "send_message"; text: string; color?: string; to?: "self" | "target" }
  | { type: "title"; title: string; subtitle?: string; color?: string; fadeInTicks?: number; stayTicks?: number; fadeOutTicks?: number; to?: "self" | "target" }
  | { type: "actionbar"; text: string; color?: string; to?: "self" | "target" }
  | { type: "give_item"; item: string; count?: number }
  | { type: "set_cooldown"; ability?: string; ticks?: number }
  | { type: "consume_charge"; ability?: string; amount?: number }
  | { type: "apply_mark"; mark: string; target?: "target" }
  | { type: "query_marked"; mark: string; radius: number; max: number; around?: "self" | "point"; actions: Action[] }
  | { type: "query_nearby"; radius: number; max: number; around?: "self" | "point"; kinds?: (typeof TARGET_KINDS)[number][]; types?: string[]; includePlayers?: boolean; actions: Action[] }
  | { type: "delayed"; delayTicks: number; actions: Action[] }
  | { type: "branch"; if: Condition[]; then: Action[]; else?: Action[] };
export type ActionType = Action["type"];

const Actions: z.ZodType<Action[]> = z.lazy(() => z.array(ActionSchema).min(1).max(DESIGN_LIMITS.maxActions));
export const ActionSchema: z.ZodType<Action> = z.lazy(() => z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("damage"), amount: capNum("damage"), target: Who.optional(), ...Charge }),
  z.strictObject({ type: z.literal("heal"), amount: capNum("heal"), target: Who.optional(), ...Charge }),
  z.strictObject({ type: z.literal("potion_effect"), effect: z.enum(EFFECTS), durationTicks: capInt("potionTicks"), amplifier: capInt("amplifier").optional(), target: Who.optional() }),
  z.strictObject({ type: z.literal("knockback"), strength: capNum("strength"), vertical: capNum("vertical").optional(), target: Who.optional(), ...Charge }),
  z.strictObject({ type: z.literal("pull_to"), to: z.enum(["self", "point"]), strength: capNum("strength"), vertical: capNum("vertical").optional(), target: Who.optional(), ...Charge }),
  z.strictObject({ type: z.literal("push_from"), from: z.enum(["self", "point"]), strength: capNum("strength"), vertical: capNum("vertical").optional(), target: Who.optional(), ...Charge }),
  /** Self only, along the look direction, to the farthest SAFE spot within range (feet + head free, solid ground, loaded chunk). */
  z.strictObject({ type: z.literal("teleport_short"), range: capNum("teleportRange") }),
  z.strictObject({ type: z.literal("launch_projectile"), kind: z.enum(PROJECTILES), speed: capNum("projectileSpeed"), tag: Key.optional(), lifetimeTicks: capInt("projectileLifetime").optional() }),
  z.strictObject({ type: z.literal("spawn_particles"), particle: z.enum(PARTICLES), count: capInt("particleCount"), spread: capNum("particleSpread").optional(), speed: capNum("particleSpeed").optional(), at: At.optional() }),
  z.strictObject({ type: z.literal("play_sound"), sound: SoundKey, volume: capNum("volume").optional(), pitch: capNum("pitch").optional(), at: At.optional() }),
  z.strictObject({ type: z.literal("send_message"), text: Text(RUNTIME_CAPS.textChars), color: Color.optional(), to: Who.optional() }),
  z.strictObject({ type: z.literal("title"), title: Text(RUNTIME_CAPS.titleChars), subtitle: Text(RUNTIME_CAPS.subtitleChars).optional(), color: Color.optional(), fadeInTicks: capInt("titleFadeTicks").optional(), stayTicks: capInt("titleStayTicks").optional(), fadeOutTicks: capInt("titleFadeTicks").optional(), to: Who.optional() }),
  z.strictObject({ type: z.literal("actionbar"), text: Text(RUNTIME_CAPS.textChars), color: Color.optional(), to: Who.optional() }),
  /** A vanilla item (minecraft:...) or one of this mod's design items (its key). */
  z.strictObject({ type: z.literal("give_item"), item: z.union([VanillaRef, Key]), count: capInt("giveCount").optional() }),
  z.strictObject({ type: z.literal("set_cooldown"), ability: Key.optional(), ticks: capInt("cooldownTicks").optional() }),
  z.strictObject({ type: z.literal("consume_charge"), ability: Key.optional(), amount: capInt("chargeCost").optional() }),
  z.strictObject({ type: z.literal("apply_mark"), mark: Key, target: z.literal("target").optional() }),
  /** For each living entity that carries this player's mark within radius (nearest first, at most max): `target` = that entity. */
  z.strictObject({ type: z.literal("query_marked"), mark: Key, radius: capNum("queryMarkedRadius"), max: capInt("queryMax"), around: z.enum(["self", "point"]).optional(), actions: Actions }),
  /** For each living entity within radius matching kinds/types (never the player; other players only with includePlayers; nearest first, at most max). */
  z.strictObject({ type: z.literal("query_nearby"), radius: capNum("queryNearbyRadius"), max: capInt("queryMax"), around: z.enum(["self", "point"]).optional(), kinds: z.array(z.enum(TARGET_KINDS)).max(4).optional(), types: z.array(VanillaRef).min(1).max(16).optional(), includePlayers: z.boolean().optional(), actions: Actions }),
  /** Run later (one scheduled task; re-checks that the player is still online). */
  z.strictObject({ type: z.literal("delayed"), delayTicks: capInt("delayTicks"), actions: Actions }),
  z.strictObject({ type: z.literal("branch"), if: z.array(ConditionSchema).min(1).max(DESIGN_LIMITS.maxConditions), then: Actions, else: Actions.optional() }),
]));

// ---------------------------------------------------------------------------------------------------------- abilities
export const AbilitySchema = z.strictObject({
  id: Key,
  name: Text(40),
  trigger: TriggerSchema,
  conditions: z.array(ConditionSchema).max(DESIGN_LIMITS.maxConditions).optional(),
  actions: z.array(ActionSchema).min(1).max(DESIGN_LIMITS.maxActions),
  /** Own cooldown: checked before the conditions and started when the ability fires (unless manualCooldown). */
  cooldownTicks: capInt("cooldownTicks").optional(),
  manualCooldown: z.boolean().optional(),
  /** Own charges: one is needed and spent per activation (unless manualCharges); they come back one per regenTicks. */
  charges: z.strictObject({ max: capInt("chargesMax"), regenTicks: capInt("chargeRegenTicks") }).optional(),
  manualCharges: z.boolean().optional(),
  /** Shown on the actionbar when the ability is blocked by its cooldown / missing charges. */
  feedback: z.boolean().optional(),
});
export type Ability = z.infer<typeof AbilitySchema>;

export const MarkSchema = z.strictObject({ name: Key, durationTicks: capInt("markTicks"), maxPerOwner: capInt("marksPerOwner"), glow: z.boolean().optional() });
export const PassiveSchema = z.strictObject({ effect: z.enum(EFFECTS), amplifier: capInt("passiveAmplifier").optional(), slot: z.enum(["main_hand", "off_hand", "either"]) });
export const PermissionSchema = z.strictObject({ node: z.string().regex(/^[a-z0-9_]+(\.[a-z0-9_]+){0,3}$/), description: Text(80), default: z.enum(["true", "op", "false"]) });

/** The datapack recipe spec's shaped/shapeless shapes, with the design item as the result (plugin-registered: the result carries the PDC identity). */
const CraftCategory = z.enum(["building", "redstone", "equipment", "misc"]);
export const DesignRecipeSchema = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("shaped"), pattern: z.array(z.string().min(1).max(3)).min(1).max(3), key: z.record(z.string().regex(/^[^ ]$/, "one character (not space)"), z.union([IngredientSchema, Key])), count: capInt("giveCount").optional(), category: CraftCategory.optional() }),
  z.strictObject({ kind: z.literal("shapeless"), ingredients: z.array(z.union([IngredientSchema, Key])).min(1).max(9), count: capInt("giveCount").optional(), category: CraftCategory.optional() }),
]);
export type DesignRecipe = z.infer<typeof DesignRecipeSchema>;

export const ItemDesignSchema = z.strictObject({
  schemaVersion: z.literal(DESIGN_SPEC_VERSION),
  /** Item key: file name (assets/designs/<id>.json) and the id in the project namespace (`nx_<8>:<id>`). */
  id: Key,
  base: VanillaRef,
  name: StyledText,
  lore: z.array(StyledText).max(DESIGN_LIMITS.maxLore).optional(),
  rarity: z.enum(["common", "uncommon", "rare", "epic"]).optional(),
  glint: z.boolean().optional(),
  /** Asset references by key (the texture / sound / model slices make them; the asset gates apply there). */
  assets: z.strictObject({ model: NsRef.optional(), sounds: z.array(SoundKey).max(16).optional() }).optional(),
  stats: z.strictObject({ damage: capNum("statDamage").optional(), attackSpeed: capNum("statAttackSpeed").optional(), durability: capInt("durability").optional(), unbreakable: z.boolean().optional() }).optional(),
  passives: z.array(PassiveSchema).max(DESIGN_LIMITS.maxPassives).optional(),
  marks: z.array(MarkSchema).max(DESIGN_LIMITS.maxMarks).optional(),
  abilities: z.array(AbilitySchema).max(DESIGN_LIMITS.maxAbilities),
  permissions: z.array(PermissionSchema).max(DESIGN_LIMITS.maxPermissions).optional(),
  recipe: DesignRecipeSchema.optional(),
  acquisition: z.strictObject({
    /** Extra loot in these loot tables (vanilla or this mod's data pack), chance per generated chest/drop. */
    loot: z.array(z.strictObject({ table: NsRef, chance: capNum("lootChance") })).max(8).optional(),
    /** Dropped by these mobs when a player kills them. */
    drops: z.array(z.strictObject({ entity: VanillaRef, chance: capNum("lootChance") })).max(8).optional(),
  }).optional(),
});
export type ItemDesign = z.infer<typeof ItemDesignSchema>;

export function designJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(ItemDesignSchema, { io: "input", reused: "ref" }) as Record<string, unknown>;
}

// ---------------------------------------------------------------------------------------------- version features
export type DesignFeatures = {
  version: string;
  /** item_model component (ItemMeta#setItemModel) exists: 1.21.4+ in the registry (capability itemModelDefinitions). */
  itemModel: boolean;
  /** Attribute constants: GENERIC_* (1.21.1, enum) vs unprefixed (1.21.3+, registry interface). */
  attributeNames: "generic-prefix" | "plain";
  javaRelease: 21 | 25;
  /** Scheduling lane: always the Paper/Bukkit main-thread scheduler (no Folia regions; plugin.yml has no folia-supported). */
  scheduling: "paper";
};
export type FeaturesResult = { ok: true; features: DesignFeatures } | { ok: false; error: string };

/** Fails closed: unknown version, blocked version, or no generated vanilla ids for it (ids are needed to check the design). */
export function designFeatures(version: string): FeaturesResult {
  const row = getVersion(version);
  if (!row) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
  if (row.status === "blocked") return { ok: false, error: `Minecraft ${version} is blocked in the version registry` };
  if (!vanillaIds("item", version).size) return { ok: false, error: `Cyrus has no vanilla id list for Minecraft ${version} yet (needs a pinned server jar on the build host)` };
  return { ok: true, features: { version, itemModel: row.capabilities.includes("itemModelDefinitions"), attributeNames: compareMc(version, "1.21.3") >= 0 ? "plain" : "generic-prefix", javaRelease: row.javaRelease, scheduling: "paper" } };
}

// ----------------------------------------------------------------------------------------------------- validation
export type DzIssue = { path: string; code: string; message: string };
export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
export type DzCheck = { id: string; status: CheckStatus; items: string[] };
export type AbilityBudget = { ability: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number };
export type DesignValidation =
  | { ok: true; design: ItemDesign; errors: []; warnings: DzIssue[]; checks: DzCheck[]; budgets: AbilityBudget[]; features: DesignFeatures }
  | { ok: false; errors: DzIssue[]; warnings: DzIssue[]; checks: DzCheck[]; budgets: AbilityBudget[] };

export type DesignContext = {
  version: string;
  namespace: string;
  /** Keys of the other design items of the same mod (give_item / item_identity / recipe ingredients may use them). */
  items?: string[];
  /** Asset keys the mod has: item model keys (`nx_x:name`) and sound keys (`nx_x:set.event`). Undefined = not checked. */
  assets?: { models?: string[]; sounds?: string[] };
};

export const DESIGN_CHECKS = ["schema", "namespace", "vanilla_ids", "references", "context", "budget", "version_features", "limits"] as const;
const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");

/** Which triggers give the activation a target entity (possibly absent at runtime) / a point other than the player. */
export const TRIGGER_HAS_TARGET: Record<TriggerType, "always" | "maybe" | "never"> = {
  right_click: "maybe", sneak_right_click: "maybe", charge_release: "maybe", left_click_hit_entity: "always", kill_entity: "always", projectile_hit: "maybe",
  held_interval: "never", join: "never", death: "never", item_consume: "never",
};
const isBlockItem = (id: string, v: string) => vanillaIds("block", v).has(id);

/** Static worst case of one action list (multiplicity = how many times the list runs per activation). */
export function budgetOf(list: Action[], mult = 1, depth = 1): { actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number } {
  const t = { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, nodes: 0, depth };
  for (const a of list) {
    t.actions += mult; t.nodes += 1;
    const add = (b: ReturnType<typeof budgetOf>) => { t.actions += b.actions; t.entities += b.entities; t.tasks += b.tasks; t.particles += b.particles; t.projectiles += b.projectiles; t.nodes += b.nodes; t.depth = Math.max(t.depth, b.depth); };
    switch (a.type) {
      case "damage": case "heal": case "potion_effect": case "knockback": case "pull_to": case "push_from": case "apply_mark": t.entities += mult; break;
      case "spawn_particles": t.particles += a.count * mult; break;
      case "launch_projectile": t.projectiles += mult; t.tasks += mult; break; // the lifetime task
      case "query_marked": case "query_nearby": add(budgetOf(a.actions, mult * a.max, depth + 1)); break;
      case "delayed": t.tasks += mult; add(budgetOf(a.actions, mult, depth + 1)); break;
      case "branch": { const th = budgetOf(a.then, mult, depth + 1), el = a.else ? budgetOf(a.else, mult, depth + 1) : null; t.nodes += th.nodes + (el?.nodes ?? 0) + a.if.length;
        // worst case = the heavier branch for each counter
        for (const k of ["actions", "entities", "tasks", "particles", "projectiles"] as const) t[k] += Math.max(th[k], el?.[k] ?? 0);
        t.depth = Math.max(t.depth, th.depth, el?.depth ?? 0); break; }
      default: break;
    }
  }
  return t;
}

/** Walk every action (pre-order) with its path ("a0", "a1.n0", "a2.then0", "a2.else1"). */
export function walkActions(list: Action[], fn: (a: Action, path: string, inLoop: boolean) => void, prefix = "", inLoop = false): void {
  list.forEach((a, i) => {
    const p = `${prefix}${prefix && !prefix.endsWith(".") ? "" : ""}${prefix ? "" : ""}`;
    void p;
    const here = prefix ? `${prefix}${i}` : `a${i}`;
    fn(a, here, inLoop);
    if (a.type === "query_marked" || a.type === "query_nearby") walkActions(a.actions, fn, `${here}.n`, true);
    else if (a.type === "delayed") walkActions(a.actions, fn, `${here}.n`, inLoop);
    else if (a.type === "branch") { walkActions(a.then, fn, `${here}.then`, inLoop); if (a.else) walkActions(a.else, fn, `${here}.else`, inLoop); }
  });
}
/** Every condition of an ability with its path ("c0", "a2.if0"). */
export function walkConditions(ab: Ability, fn: (c: Condition, path: string, inLoop: boolean) => void): void {
  (ab.conditions ?? []).forEach((c, i) => fn(c, `c${i}`, false));
  walkActions(ab.actions, (a, p, inLoop) => { if (a.type === "branch") a.if.forEach((c, i) => fn(c, `${p}.if${i}`, inLoop)); });
}

export function validateDesign(input: unknown, ctx: DesignContext): DesignValidation {
  const errors: DzIssue[] = [];
  const warnings: DzIssue[] = [];
  const bucket = new Map<string, string[]>(DESIGN_CHECKS.map((c) => [c, []]));
  const failed = new Set<string>();
  const ran = new Set<string>(["schema"]);
  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); failed.add(check); bucket.get(check)!.push(`${path}: ${message}`); };
  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
  const budgets: AbilityBudget[] = [];
  const checksOf = (): DzCheck[] => DESIGN_CHECKS.map((id) => {
    const items = bucket.get(id)!;
    return { id, status: !ran.has(id) ? "not_run" : failed.has(id) ? "fail" : items.length ? "warn" : "pass", items: items.slice(0, 20) };
  });
  const bad = (): DesignValidation => ({ ok: false, errors, warnings, checks: checksOf(), budgets });

  ran.add("namespace");
  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); return bad(); }
  ran.add("version_features");
  const fe = designFeatures(ctx.version);
  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return bad(); }
  const v = ctx.version;
  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DESIGN_SPEC_VERSION) {
    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DESIGN_SPEC_VERSION}`); return bad();
  }
  const bytes = (() => { try { return new TextEncoder().encode(JSON.stringify(input)).length; } catch { return Infinity; } })();
  ran.add("limits");
  if (bytes > DESIGN_LIMITS.maxSpecBytes) { fail("limits", "(root)", "spec_size", `the design is ${bytes} bytes; the limit is ${DESIGN_LIMITS.maxSpecBytes}`); return bad(); }
  const parsed = ItemDesignSchema.safeParse(input);
  if (!parsed.success) {
    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
    return bad();
  }
  const d = parsed.data;
  for (const c of ["vanilla_ids", "references", "context", "budget"]) ran.add(c);
  const ns = ctx.namespace;
  const id = buildIdentifier(ns, "item", d.id);
  if (!id.ok) fail("namespace", "id", "bad_id", id.error);

  // base item
  const base = d.base.slice("minecraft:".length);
  if (!isVanilla("item", d.base, v)) fail("vanilla_ids", "base", "unknown_vanilla_id", missingIdReason("item", d.base, v));
  if (BANNED_BASES.test(base)) fail("context", "base", "banned_base", `${d.base} cannot be a design item's base (operator item, or its own right-click teleports/places/spawns)`);
  const clicks = d.abilities.some((a) => ["right_click", "sneak_right_click", "charge_release"].includes(a.trigger.type));
  if (clicks && isBlockItem(base, v)) fail("context", "base", "block_base", `${d.base} is a block: right-clicking would place it. Pick a non-block base item for click abilities`);
  const consume = d.abilities.some((a) => a.trigger.type === "item_consume");
  if (consume && !(CONSUMABLE_BASES as readonly string[]).includes(base)) fail("context", "base", "not_consumable", `item_consume needs an edible/drinkable base item (${CONSUMABLE_BASES.slice(0, 8).join(", ")}, ...); ${d.base} is not one`);
  if (d.stats && (d.stats.damage !== undefined) !== (d.stats.attackSpeed !== undefined)) fail("context", "stats", "stats_pair", "set damage and attackSpeed together: a custom attack modifier replaces the base item's default damage AND speed");
  if (d.stats?.durability !== undefined && d.stats.unbreakable) warn("context", "stats.durability", "unbreakable", "durability has no effect on an unbreakable item");

  // assets
  if (d.assets?.model) {
    if (!d.assets.model.startsWith(`${ns}:`)) fail("namespace", "assets.model", "foreign_namespace", `the item model must be in this mod's namespace ${ns}`);
    else if (ctx.assets?.models && !ctx.assets.models.includes(d.assets.model)) warn("references", "assets.model", "asset_unresolved", `${d.assets.model}: this mod has no such item model (no custom texture for it, or your plan does not include custom textures), so the item keeps the ${d.base} look`);
    if (!fe.features.itemModel) warn("version_features", "assets.model", "item_model_unsupported", `custom item models need Minecraft 1.21.4 or newer; on ${v} the item keeps the ${d.base} look (a legacy custom_model_data emitter is not built)`);
  }
  const declaredSounds = new Set(d.assets?.sounds ?? []);
  const soundRef = (at: string, key: string) => {
    const kns = key.split(":")[0];
    if (kns === "minecraft") { warn("references", at, "vanilla_sound_unchecked", `${key}: vanilla sound keys are not checked against the game (a wrong key plays nothing)`); return; }
    if (kns !== ns) { fail("namespace", at, "foreign_namespace", `${key} uses the namespace ${kns}; sounds must be minecraft: or this mod's ${ns}`); return; }
    if (ctx.assets?.sounds && !ctx.assets.sounds.includes(key)) warn("references", at, "asset_unresolved", `${key}: this mod has no such custom sound (no sound set for it, or your plan does not include custom sounds), so it plays nothing`);
    else if (!ctx.assets?.sounds && declaredSounds.size && !declaredSounds.has(key)) warn("references", at, "sound_undeclared", `${key} is not listed in assets.sounds`);
  };
  (d.assets?.sounds ?? []).forEach((s, i) => { if (!s.startsWith(`${ns}:`) && !s.startsWith("minecraft:")) fail("namespace", `assets.sounds[${i}]`, "foreign_namespace", `${s} must be minecraft: or ${ns}:`); });

  // uniqueness + local tables
  const abilityIds = new Set<string>();
  d.abilities.forEach((a, i) => { if (abilityIds.has(a.id)) fail("references", `abilities[${i}].id`, "duplicate_id", `ability ${a.id} is defined twice`); abilityIds.add(a.id); });
  const marks = new Map<string, z.infer<typeof MarkSchema>>();
  (d.marks ?? []).forEach((m, i) => { if (marks.has(m.name)) fail("references", `marks[${i}].name`, "duplicate_id", `mark ${m.name} is defined twice`); marks.set(m.name, m); });
  const perms = new Set<string>();
  (d.permissions ?? []).forEach((p, i) => { if (perms.has(p.node)) fail("references", `permissions[${i}].node`, "duplicate_id", `permission ${p.node} is declared twice`); if (["give", "reload", "command", "list", "params"].includes(p.node)) fail("references", `permissions[${i}].node`, "reserved_node", `${ns}.${p.node} is reserved for the mod's own command`); perms.add(p.node); });
  const otherItems = new Set([...(ctx.items ?? []), d.id]);
  const launchTags = new Set<string>();
  for (const ab of d.abilities) walkActions(ab.actions, (a) => { if (a.type === "launch_projectile" && a.tag) launchTags.add(a.tag); });
  const passives = new Set<string>();
  (d.passives ?? []).forEach((p, i) => {
    if ((HARMFUL_EFFECTS as readonly string[]).includes(p.effect)) fail("context", `passives[${i}].effect`, "harmful_passive", `${p.effect} is harmful: a passive may only give the holder a helpful effect`);
    if (["instant_health", "instant_damage", "saturation"].includes(p.effect)) fail("context", `passives[${i}].effect`, "instant_passive", `${p.effect} is instant and would apply every 2 seconds; use an ability instead`);
    if (passives.has(p.effect)) fail("references", `passives[${i}]`, "duplicate_id", `passive ${p.effect} is listed twice`); passives.add(p.effect);
  });
  const sneakRight = d.abilities.some((a) => a.trigger.type === "sneak_right_click");
  const chargeRight = d.abilities.some((a) => a.trigger.type === "charge_release" && a.trigger.release === "right_click");
  if (sneakRight && chargeRight) fail("context", "abilities", "ambiguous_trigger", "an item cannot have both sneak_right_click and a charge_release released by right-click (both fire on a sneaking right-click)");

  // abilities
  d.abilities.forEach((ab, i) => {
    const at = `abilities[${i}]`;
    const tr = ab.trigger;
    if (tr.type === "charge_release" && tr.maxChargeTicks < tr.minChargeTicks) fail("context", `${at}.trigger.maxChargeTicks`, "charge_order", "maxChargeTicks must be at least minChargeTicks");
    if (tr.type === "projectile_hit" && !launchTags.has(tr.tag)) fail("references", `${at}.trigger.tag`, "unresolved_ref", `no launch_projectile of this item has tag "${tr.tag}"`);
    if (ab.manualCooldown && !ab.cooldownTicks) warn("context", `${at}.manualCooldown`, "no_cooldown", "manualCooldown without cooldownTicks does nothing");
    if (ab.manualCharges && !ab.charges) warn("context", `${at}.manualCharges`, "no_charges", "manualCharges without charges does nothing");
    if (tr.type === "held_interval" && ab.cooldownTicks && ab.cooldownTicks < tr.periodTicks) warn("context", `${at}.cooldownTicks`, "cooldown_below_period", "the cooldown is shorter than the interval, so it never blocks");
    const hasTarget = TRIGGER_HAS_TARGET[tr.type];
    const hasPoint = hasTarget !== "never" || ("targetRange" in tr && tr.targetRange !== undefined);
    if (["right_click", "sneak_right_click", "charge_release"].includes(tr.type) && !("targetRange" in tr && tr.targetRange !== undefined)) {
      // no ray trace: no target, point = the player
    }
    const targetAvail = (inLoop: boolean) => inLoop || (hasTarget === "always" || hasTarget === "maybe") && (hasTarget === "always" || tr.type === "projectile_hit" || ("targetRange" in tr && tr.targetRange !== undefined));
    const abilityRef = (path: string, ref: string | undefined, need: "cooldown" | "charges") => {
      const id2 = ref ?? ab.id;
      const target = d.abilities.find((x) => x.id === id2);
      if (!target) { fail("references", path, "unresolved_ref", `no ability "${id2}" on this item`); return; }
      if (need === "charges" && !target.charges) fail("references", path, "no_charges", `ability "${id2}" has no charges`);
      if (need === "cooldown" && !target.cooldownTicks && ref !== undefined) warn("references", path, "no_cooldown", `ability "${id2}" has no cooldownTicks; set_cooldown/cooldown_ready use the ticks given here`);
    };
    walkConditions(ab, (c, p, inLoop) => {
      const cp = `${at}.${p.startsWith("c") ? `conditions[${p.slice(1)}]` : p}`;
      switch (c.type) {
        case "cooldown_ready": abilityRef(cp, c.ability, "cooldown"); break;
        case "charges_available": abilityRef(cp, c.ability, "charges"); break;
        case "has_permission": if (!perms.has(c.node)) fail("references", cp, "undeclared_permission", `permission ${ns}.${c.node} is not declared in "permissions"`); break;
        case "target_is":
          if (!c.kinds?.length && !c.types?.length) fail("schema", cp, "empty_filter", "target_is needs kinds or types");
          c.types?.forEach((t, j) => { if (!isVanilla("entity_type", t, v)) fail("vanilla_ids", `${cp}.types[${j}]`, "unknown_vanilla_id", missingIdReason("entity_type", t, v)); });
          if (!targetAvail(inLoop)) fail("context", cp, "no_target", `${tr.type} has no target entity${["right_click", "sneak_right_click", "charge_release"].includes(tr.type) ? " (set trigger.targetRange to look for one)" : ""}`);
          break;
        case "health_below": case "health_above":
          if (c.subject === "target" && !targetAvail(inLoop)) fail("context", cp, "no_target", `${tr.type} has no target entity`); break;
        case "item_identity": if (!otherItems.has(c.item)) fail("references", cp, "unresolved_ref", `no design item "${c.item}" in this mod`); break;
        case "time_of_day": if (c.from === c.to) warn("context", cp, "empty_window", "from == to: the window is a single tick"); break;
        default: break;
      }
    });
    walkActions(ab.actions, (a, p, inLoop) => {
      const ap = `${at}.actions.${p}`;
      const usesTarget = ("target" in a && a.target === "target") || ("to" in a && a.to === "target") || ("at" in a && a.at === "target") || a.type === "apply_mark";
      const defaultTarget = ["damage", "knockback", "pull_to", "push_from", "potion_effect", "heal"].includes(a.type) && !("target" in a && a.target);
      // default subject: damage/knockback/pull/push hit the target; heal/potion apply to self
      const implicitTarget = defaultTarget && ["damage", "knockback", "pull_to", "push_from"].includes(a.type);
      if ((usesTarget || implicitTarget) && !targetAvail(inLoop)) fail("context", ap, "no_target", `${a.type} needs a target entity, which ${tr.type} does not have${["right_click", "sneak_right_click", "charge_release"].includes(tr.type) ? " (set trigger.targetRange, or put it inside query_nearby / query_marked)" : " (put it inside query_nearby / query_marked)"}`);
      if ((("at" in a && a.at === "point") || (a.type === "pull_to" && a.to === "point") || (a.type === "push_from" && a.from === "point") || (("around" in a) && a.around === "point")) && !hasPoint) warn("context", ap, "point_is_self", `${tr.type} has no aim point here, so "point" is the player's own position`);
      if ("scaleWithCharge" in a && a.scaleWithCharge && tr.type !== "charge_release") warn("context", ap, "no_charge", "scaleWithCharge only matters for charge_release");
      switch (a.type) {
        case "pull_to": if (a.to === "self" && (a.target ?? "target") === "self") fail("context", ap, "self_pull", "pulling yourself to yourself does nothing"); break;
        case "push_from": if (a.from === "self" && (a.target ?? "target") === "self") fail("context", ap, "self_push", "pushing yourself from yourself does nothing"); break;
        case "play_sound": soundRef(`${ap}.sound`, a.sound); break;
        case "give_item":
          if (a.item.startsWith("minecraft:")) { if (!isVanilla("item", a.item, v)) fail("vanilla_ids", `${ap}.item`, "unknown_vanilla_id", missingIdReason("item", a.item, v)); else if (BANNED_BASES.test(a.item.slice(10))) fail("context", `${ap}.item`, "banned_item", `${a.item} cannot be given by an ability`); }
          else if (!otherItems.has(a.item)) fail("references", `${ap}.item`, "unresolved_ref", `no design item "${a.item}" in this mod`);
          break;
        case "set_cooldown": abilityRef(ap, a.ability, "cooldown"); if (a.ticks === undefined && !(d.abilities.find((x) => x.id === (a.ability ?? ab.id))?.cooldownTicks)) fail("references", ap, "no_ticks", "set_cooldown needs ticks when the ability has no cooldownTicks"); break;
        case "consume_charge": abilityRef(ap, a.ability, "charges"); break;
        case "apply_mark": case "query_marked": if (!marks.has(a.mark)) fail("references", `${ap}.mark`, "unresolved_ref", `no mark "${a.mark}" in this item's "marks"`); break;
        case "query_nearby":
          a.types?.forEach((t, j) => { if (!isVanilla("entity_type", t, v)) fail("vanilla_ids", `${ap}.types[${j}]`, "unknown_vanilla_id", missingIdReason("entity_type", t, v)); });
          if (a.includePlayers && !(a.kinds?.includes("player") || a.kinds?.includes("living") || !a.kinds?.length)) warn("context", ap, "players_filtered", "includePlayers has no effect: kinds excludes players");
          break;
        case "delayed": if (inLoop) fail("budget", ap, "delayed_in_loop", "delayed inside a query loop would schedule one task per entity; put the query inside the delayed step instead"); break;
        case "teleport_short": if (inLoop) fail("context", ap, "teleport_in_loop", "teleport_short moves the player: not inside a query loop"); break;
        case "launch_projectile": if (inLoop) fail("budget", ap, "projectile_in_loop", "launch_projectile inside a query loop is not allowed"); break;
        default: break;
      }
      if ((a.type === "query_marked" || a.type === "query_nearby") && inLoop) fail("budget", ap, "nested_query", "a query inside a query is not allowed (unbounded fan-out)");
    });
    const b = budgetOf(ab.actions);
    const nodes = b.nodes + (ab.conditions?.length ?? 0);
    budgets.push({ ability: ab.id, actions: b.actions, entities: b.entities, tasks: b.tasks, particles: b.particles, projectiles: b.projectiles, nodes, depth: b.depth });
    for (const k of ["actions", "entities", "tasks", "particles", "projectiles"] as const) if (b[k] > BUDGET[k]) fail("budget", `${at}.actions`, `budget_${k}`, `worst case ${b[k]} ${k} per activation; the limit is ${BUDGET[k]} (lower a query's max or the counts)`);
    if (nodes > DESIGN_LIMITS.maxNodes) fail("budget", `${at}`, "too_many_nodes", `${nodes} nodes; the limit is ${DESIGN_LIMITS.maxNodes}`);
    if (b.depth > DESIGN_LIMITS.maxDepth) fail("budget", `${at}`, "too_deep", `nesting depth ${b.depth}; the limit is ${DESIGN_LIMITS.maxDepth}`);
  });
  if (!d.abilities.length && !d.passives?.length) warn("context", "abilities", "plain_item", "the item has no abilities or passives (a plain custom item)");

  // recipe (the datapack recipe shapes; ingredients are vanilla items, #tags or this mod's design items)
  if (d.recipe) {
    const r = d.recipe;
    const ing = (at: string, x: unknown) => {
      const list = Array.isArray(x) ? x as string[] : [x as string];
      list.forEach((ref, j) => {
        const p = Array.isArray(x) ? `${at}[${j}]` : at;
        if (KEY.test(ref)) { if (!otherItems.has(ref)) fail("references", p, "unresolved_ref", `no design item "${ref}" in this mod`); else if (ref === d.id) fail("references", p, "self_ingredient", "an item cannot be an ingredient of its own recipe"); return; }
        if (ref.startsWith("#")) { if (Array.isArray(x)) fail("version_features", p, "tag_in_alternatives", "a list of alternatives may only hold item ids; use one #tag on its own"); if (!isVanilla("tag/item", ref, v)) fail("vanilla_ids", p, "unknown_vanilla_id", missingIdReason("tag/item", ref, v)); return; }
        if (!ref.startsWith("minecraft:")) { fail("namespace", p, "foreign_namespace", `${ref}: ingredients are minecraft: items/tags or this mod's design item keys`); return; }
        if (!isVanilla("item", ref, v)) fail("vanilla_ids", p, "unknown_vanilla_id", missingIdReason("item", ref, v));
        else if (ref === "minecraft:air") fail("vanilla_ids", p, "air", "air is not an ingredient");
      });
    };
    if (r.kind === "shaped") {
      const width = r.pattern[0].length;
      if (r.pattern.some((row) => row.length !== width)) fail("schema", "recipe.pattern", "pattern_rows", "every pattern row must have the same length");
      const used = new Set(r.pattern.join("").replace(/ /g, "").split(""));
      if (!used.size) fail("schema", "recipe.pattern", "empty_pattern", "the pattern has no ingredients");
      for (const ch of used) if (!(ch in r.key)) fail("references", "recipe.pattern", "pattern_key", `pattern uses "${ch}" but key has no "${ch}"`);
      for (const k of Object.keys(r.key)) { if (!used.has(k)) warn("references", `recipe.key.${k}`, "unused_key", `key "${k}" is not used in the pattern`); ing(`recipe.key.${k}`, r.key[k]); }
    } else r.ingredients.forEach((x, j) => ing(`recipe.ingredients[${j}]`, x));
  }
  (d.acquisition?.loot ?? []).forEach((l, i) => {
    const tns = l.table.split(":")[0];
    if (tns === "minecraft") { if (!isVanilla("loot_table", l.table, v)) fail("vanilla_ids", `acquisition.loot[${i}].table`, "unknown_vanilla_id", missingIdReason("loot_table", l.table, v)); }
    else if (tns !== ns) fail("namespace", `acquisition.loot[${i}].table`, "foreign_namespace", `${l.table}: loot tables are minecraft: or this mod's ${ns}`);
  });
  (d.acquisition?.drops ?? []).forEach((l, i) => { if (!isVanilla("entity_type", l.entity, v)) fail("vanilla_ids", `acquisition.drops[${i}].entity`, "unknown_vanilla_id", missingIdReason("entity_type", l.entity, v)); });

  if (errors.length) return bad();
  return { ok: true, design: d, errors: [], warnings, checks: checksOf(), budgets, features: fe.features };
}

/** Validate a whole mod (all its design files): each file + cross-file duplicates. */
export function validateDesigns(inputs: unknown[], ctx: Omit<DesignContext, "items">): { ok: boolean; results: DesignValidation[]; errors: DzIssue[] } {
  const keys = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : "")).filter(Boolean);
  const errors: DzIssue[] = [];
  if (inputs.length > DESIGN_LIMITS.maxItems) errors.push({ path: "(mod)", code: "too_many_items", message: `${inputs.length} design items; the limit is ${DESIGN_LIMITS.maxItems}` });
  const dup = keys.find((k, i) => keys.indexOf(k) !== i);
  if (dup) errors.push({ path: "(mod)", code: "duplicate_item", message: `design item ${dup} is defined twice` });
  const results = inputs.slice(0, DESIGN_LIMITS.maxItems).map((x) => validateDesign(x, { ...ctx, items: keys }));
  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
}

