input.content:
// Cyrus R3 verified component library: the Java sources every designer mod is built from. They are FIXED code
// (reviewed once, compiled with javac against the real Paper classpaths, scanned with the strict profile and booted in
// Test Flight); generated code only calls them. `__PKG__` is replaced by the mod's package. Only Compat.java differs
// per Minecraft version (./index.ts renders it). No reflection, no threads, no network, no command dispatch, no files
// outside the plugin folder: the strict scan must pass on every component (test/cyrus-designer.test.ts + node-2 runs).
/* eslint-disable no-useless-escape */

export const TRIGGER_JAVA = String.raw`package __PKG__.designer;

/** Component designer-trigger v1: the ten trigger kinds of the ability graph. */
public enum Trigger {
    RIGHT_CLICK, LEFT_CLICK_HIT_ENTITY, SNEAK_RIGHT_CLICK, KILL_ENTITY, PROJECTILE_HIT, HELD_INTERVAL, JOIN, DEATH, ITEM_CONSUME, CHARGE_RELEASE
}
`;

export const BUDGET_JAVA = String.raw`package __PKG__.designer;

/**
 * Component designer-budget v1: the per-activation resource budget. The design validator proves the static worst case
 * fits these numbers; this class enforces them again at runtime (a hand-edited config can raise counts only up to the
 * caps, and nested delayed steps share the activation's budget). When a counter is exhausted the activation stops.
 */
public final class Budget {
    public static final int ACTIONS = 64;
    public static final int ENTITIES = 32;
    public static final int TASKS = 8;
    public static final int PARTICLES = 512;
    public static final int PROJECTILES = 3;
    private int actions;
    private int entities;
    private int tasks;
    private int particles;
    private int projectiles;
    private boolean exhausted;

    public boolean action() { if (actions >= ACTIONS) { exhausted = true; return false; } actions++; return true; }
    public boolean entity() { if (entities >= ENTITIES) { exhausted = true; return false; } entities++; return true; }
    public boolean task() { if (tasks >= TASKS) { exhausted = true; return false; } tasks++; return true; }
    public boolean projectile() { if (projectiles >= PROJECTILES) { exhausted = true; return false; } projectiles++; return true; }
    /** How many of n particles may still be spawned (0 when the budget is used up). */
    public int particles(int n) {
        int use = Math.max(0, Math.min(n, PARTICLES - particles));
        particles += use;
        if (use < n) exhausted = true;
        return use;
    }
    public boolean exhausted() { return exhausted; }
}
`;

export const ACTIVATION_JAVA = String.raw`package __PKG__.designer;

import org.bukkit.Location;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;

/** Component designer-activation v1: one firing of an ability (player, optional target, aim point, charge, shared budget). */
public final class Activation {
    private final Ability ability;
    private final Player player;
    private final Entity target;
    private final Location point;
    private final double charge;
    private final Budget budget;

    private Activation(Ability ability, Player player, Entity target, Location point, double charge, Budget budget) {
        this.ability = ability;
        this.player = player;
        this.target = target;
        this.point = point;
        this.charge = charge;
        this.budget = budget;
    }

    public static Activation of(Ability ability, Player player, Entity target, Location point, double charge) {
        return new Activation(ability, player, target, point == null ? player.getLocation() : point.clone(), Math.max(0.0, Math.min(1.0, charge)), new Budget());
    }

    /** The same activation (same budget) aimed at another entity: used by query_marked / query_nearby. */
    public Activation withTarget(Entity next) { return new Activation(ability, player, next, point, charge, budget); }

    public Ability ability() { return ability; }
    public Player player() { return player; }
    public Entity target() { return target; }
    public LivingEntity livingTarget() { return target instanceof LivingEntity le && le.isValid() && !le.isDead() ? le : null; }
    public Location point() { return point; }
    public double charge() { return charge; }
    public Budget budget() { return budget; }
    public boolean valid() { return player.isOnline() && !player.isDead(); }
}
`;

export const IDENTITY_JAVA = String.raw`package __PKG__.designer;

import org.bukkit.NamespacedKey;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;

/**
 * Component designer-identity v1: an item IS a design item only when its PersistentDataContainer carries
 * <namespace>:item = <item key>. Never by name, lore, material or model (renaming in an anvil or another plugin's lore
 * cannot fake or break it). The namespace is the project's reserved nx_ namespace, so two mods never collide.
 */
public final class ItemIdentity {
    private final NamespacedKey key;

    public ItemIdentity(String namespace) { this.key = new NamespacedKey(namespace, "item"); }

    public NamespacedKey key() { return key; }

    public void tag(ItemMeta meta, String id) { meta.getPersistentDataContainer().set(key, PersistentDataType.STRING, id); }

    public String idOf(ItemStack stack) {
        if (stack == null || stack.getType().isAir() || !stack.hasItemMeta()) return null;
        ItemMeta meta = stack.getItemMeta();
        return meta == null ? null : meta.getPersistentDataContainer().get(key, PersistentDataType.STRING);
    }

    public boolean is(ItemStack stack, String id) { return id.equals(idOf(stack)); }

    public boolean carries(Player player, String id) {
        for (ItemStack s : player.getInventory().getContents()) if (is(s, id)) return true;
        return false;
    }
}
`;

export const COOLDOWNS_JAVA = String.raw`package __PKG__.designer;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Component designer-cooldowns v1: per player + ability cooldowns in server ticks (Bukkit.getCurrentTick), so lag and
 * clock changes cannot shorten them. No shared state between players; entries are dropped on quit, on death and when
 * the plugin is disabled (Designer.forget / disable).
 */
public final class Cooldowns {
    private final Map<UUID, Map<String, Long>> until = new HashMap<>();

    public boolean ready(UUID player, String key, long now) { return remaining(player, key, now) <= 0; }

    public long remaining(UUID player, String key, long now) {
        Map<String, Long> m = until.get(player);
        Long t = m == null ? null : m.get(key);
        return t == null ? 0L : Math.max(0L, t - now);
    }

    public void set(UUID player, String key, long untilTick) { until.computeIfAbsent(player, k -> new HashMap<>()).put(key, untilTick); }
    public void clear(UUID player) { until.remove(player); }
    public void clearAll() { until.clear(); }
    public int players() { return until.size(); }
}
`;

export const CHARGES_JAVA = String.raw`package __PKG__.designer;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Component designer-charges v1: per player + ability charges that come back one per regen period, computed lazily
 * when read (no repeating task). A player starts full. Dropped on quit / death / disable like cooldowns.
 * Semantics (the TS simulator implements exactly this): while full the regen clock does not run; after a spend from
 * full it starts at that tick; each full period adds one charge.
 */
public final class Charges {
    private static final class State { int count; long last; }
    private final Map<UUID, Map<String, State>> states = new HashMap<>();

    private State state(UUID player, String key, long now, int max) {
        Map<String, State> m = states.computeIfAbsent(player, k -> new HashMap<>());
        State s = m.get(key);
        if (s == null) { s = new State(); s.count = max; s.last = now; m.put(key, s); }
        return s;
    }

    private static void regen(State s, long now, int max, long period) {
        if (s.count >= max) { s.count = max; s.last = now; return; }
        long gained = period <= 0 ? 0 : (now - s.last) / period;
        if (gained > 0) {
            s.count = (int) Math.min(max, s.count + gained);
            s.last = s.count >= max ? now : s.last + gained * period;
        }
    }

    public int available(UUID player, String key, long now, int max, long period) {
        State s = state(player, key, now, max);
        regen(s, now, max, period);
        return s.count;
    }

    public boolean consume(UUID player, String key, long now, int max, long period, int n) {
        State s = state(player, key, now, max);
        regen(s, now, max, period);
        if (s.count < n) return false;
        s.count -= n;
        return true;
    }

    public void clear(UUID player) { states.remove(player); }
    public void clearAll() { states.clear(); }
}
`;

export const MARKS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;

/**
 * Component designer-marks v1: apply_mark tags a target for one player (owner) for a while; query_marked finds that
 * owner's marked entities near a point. Bounded: per owner + mark at most maxPerOwner (the oldest is replaced) and at
 * most TOTAL marks plugin-wide. Marks vanish when they expire, when the target dies, when the owner quits or dies, and
 * on disable. Nothing is stored on the entity itself.
 */
public final class Marks {
    public static final int TOTAL = 2048;
    private final Map<String, LinkedHashMap<UUID, Long>> marks = new HashMap<>();
    private int total;

    private static String k(UUID owner, String mark) { return owner + "|" + mark; }

    private void prune(LinkedHashMap<UUID, Long> m, long now) {
        Iterator<Map.Entry<UUID, Long>> it = m.entrySet().iterator();
        while (it.hasNext()) if (it.next().getValue() <= now) { it.remove(); total--; }
    }

    private void pruneAll(long now) { for (LinkedHashMap<UUID, Long> m : marks.values()) prune(m, now); marks.values().removeIf(Map::isEmpty); }

    public boolean apply(UUID owner, UUID target, String mark, long now, long duration, int maxPerOwner) {
        LinkedHashMap<UUID, Long> m = marks.computeIfAbsent(k(owner, mark), x -> new LinkedHashMap<>());
        prune(m, now);
        if (m.remove(target) != null) total--;
        while (m.size() >= Math.max(1, maxPerOwner)) { Iterator<UUID> it = m.keySet().iterator(); it.next(); it.remove(); total--; }
        if (total >= TOTAL) { pruneAll(now); if (total >= TOTAL) return false; }
        m.put(target, now + duration);
        total++;
        return true;
    }

    public boolean has(UUID owner, String mark, UUID target, long now) {
        LinkedHashMap<UUID, Long> m = marks.get(k(owner, mark));
        Long t = m == null ? null : m.get(target);
        return t != null && t > now;
    }

    /** The owner's marked living entities within radius of center, nearest first, at most max. */
    public List<LivingEntity> marked(UUID owner, String mark, Location center, double radius, int max, long now) {
        LinkedHashMap<UUID, Long> m = marks.get(k(owner, mark));
        List<LivingEntity> out = new ArrayList<>();
        if (m == null || center == null || center.getWorld() == null) return out;
        prune(m, now);
