    private final List<String> notes = new ArrayList<>();
    private String migrated;

    public DesignConfig(JavaPlugin plugin) { this.plugin = plugin; }

    public void load() {
        plugin.saveDefaultConfig();
        plugin.reloadConfig();
        cfg = plugin.getConfig();
        defaults = cfg.getDefaults();
        notes.clear();
        migrated = null;
        if (defaults == null) return;
        int jarVersion = defaults.getInt("config_version", 1);
        Object raw = cfg.get("config_version", null);
