public final class DesignListener implements Listener {
    private final Designer d;

    DesignListener(Designer d) { this.d = d; }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onInteract(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        if (e.getAction() != Action.RIGHT_CLICK_AIR && e.getAction() != Action.RIGHT_CLICK_BLOCK) return;
        if (e.useItemInHand() == Event.Result.DENY) return;
        click(e.getPlayer(), null);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onInteractEntity(PlayerInteractEntityEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        click(e.getPlayer(), e.getRightClicked());
    }

    private void click(Player p, Entity clicked) {
        if (d.busy(p)) return;
        DesignItem item = d.held(p);
        if (item == null || !d.firstClickThisTick(p)) return;
        if (p.isSneaking()) {
            boolean sneakAbility = false;
            Long start = d.chargeStart(p.getUniqueId());
            for (Ability a : item.abilities(Trigger.CHARGE_RELEASE)) {
                if (!a.releaseOnRightClick()) continue;
                sneakAbility = true;
                if (start == null) continue;
                long held = d.now() - start;
                if (held < a.minChargeTicks()) continue;
                d.clearCharge(p.getUniqueId());
                aim(a, p, clicked, a.chargeFraction(held));
            }
            List<Ability> sneak = item.abilities(Trigger.SNEAK_RIGHT_CLICK);
            for (Ability a : sneak) aim(a, p, clicked, 0);
            if (sneakAbility || !sneak.isEmpty()) return;
        }
        for (Ability a : item.abilities(Trigger.RIGHT_CLICK)) aim(a, p, clicked, 0);
    }

    /** Target + point for click triggers: the right-clicked entity, else a ray trace within the ability's targetRange. */
    private void aim(Ability a, Player p, Entity clicked, double charge) {
        Entity target = null;
        Location point = null;
        if (a.targetRange() > 0) {
            if (clicked instanceof LivingEntity && clicked.getLocation().distance(p.getLocation()) <= a.targetRange() + 1) { target = clicked; point = clicked.getLocation(); }
            else { RayTraceResult r = Targets.look(p, a.targetRange()); target = Targets.lookEntity(r); point = Targets.lookPoint(p, r, a.targetRange()); }
        }
        a.fire(Activation.of(a, p, target, point, charge));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent e) {
        if (!(e.getDamager() instanceof Player p) || !(e.getEntity() instanceof LivingEntity t)) return;
        if (e.getCause() != EntityDamageEvent.DamageCause.ENTITY_ATTACK || d.busy(p)) return;
        DesignItem item = d.held(p);
        if (item == null) return;
        for (Ability a : item.abilities(Trigger.LEFT_CLICK_HIT_ENTITY)) a.fire(Activation.of(a, p, t, t.getLocation(), 0));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDeath(EntityDeathEvent e) {
        LivingEntity dead = e.getEntity();
        Player killer = dead.getKiller();
        if (killer != null && killer != dead && !d.busy(killer)) {
            DesignItem item = d.held(killer);
            if (item != null) for (Ability a : item.abilities(Trigger.KILL_ENTITY)) a.fire(Activation.of(a, killer, dead, dead.getLocation(), 0));
        }
        d.marks().removeTarget(dead.getUniqueId());
        if (dead instanceof Player p) {
            for (DesignItem i : d.items()) {
                List<Ability> list = i.abilities(Trigger.DEATH);
                if (!list.isEmpty() && d.identity().carries(p, i.id())) for (Ability a : list) a.fire(Activation.of(a, p, null, null, 0));
            }
            d.forget(p.getUniqueId());
        }
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onDrops(EntityDeathEvent e) {
        if (e.getEntity() instanceof Player || e.getEntity().getKiller() == null) return;
        String type = e.getEntity().getType().getKey().getKey();
        for (DesignItem i : d.items()) i.drops(type, e.getDrops(), d.random());
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onLoot(LootGenerateEvent e) {
        String table = e.getLootTable().getKey().toString();
        for (DesignItem i : d.items()) i.loot(table, e.getLoot(), d.random());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onProjectile(ProjectileHitEvent e) {
        Projectile pr = e.getEntity();
        String tagged = pr.getPersistentDataContainer().get(d.projectileKey(), PersistentDataType.STRING);
        if (tagged == null) return;
        int bar = tagged.indexOf('|');
        if (bar > 0 && pr.getShooter() instanceof Player p && p.isOnline() && !d.busy(p)) {
            DesignItem item = d.item(tagged.substring(0, bar));
            String tag = tagged.substring(bar + 1);
            if (item != null) {
                Entity hit = e.getHitEntity();
                Location point = hit != null ? hit.getLocation() : e.getHitBlock() != null ? e.getHitBlock().getLocation().add(0.5, 1.0, 0.5) : pr.getLocation();
                LivingEntity t = hit instanceof LivingEntity le && hit != p ? le : null;
                for (Ability a : item.abilities(Trigger.PROJECTILE_HIT)) if (tag.equals(a.projectileTag())) a.fire(Activation.of(a, p, t, point, 0));
            }
        }
        if (pr instanceof AbstractArrow) pr.remove();
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onSneak(PlayerToggleSneakEvent e) {
        Player p = e.getPlayer();
        DesignItem item = d.held(p);
        if (e.isSneaking()) {
            if (item != null && !item.abilities(Trigger.CHARGE_RELEASE).isEmpty()) d.startCharge(p.getUniqueId());
