        }
        Long start = d.chargeStart(p.getUniqueId());
        d.clearCharge(p.getUniqueId());
        if (item == null || start == null || d.busy(p)) return;
        long held = d.now() - start;
        for (Ability a : item.abilities(Trigger.CHARGE_RELEASE)) if (!a.releaseOnRightClick() && held >= a.minChargeTicks()) aim(a, p, null, a.chargeFraction(held));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHeld(PlayerItemHeldEvent e) { d.clearCharge(e.getPlayer().getUniqueId()); }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onConsume(PlayerItemConsumeEvent e) {
        Player p = e.getPlayer();
        if (d.busy(p)) return;
        String id = d.identity().idOf(e.getItem());
        DesignItem item = id == null ? null : d.item(id);
        if (item == null) return;
        for (Ability a : item.abilities(Trigger.ITEM_CONSUME)) a.fire(Activation.of(a, p, null, null, 0));
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();
        if (!d.recipeKeys().isEmpty()) p.discoverRecipes(d.recipeKeys());
        for (DesignItem i : d.items()) {
            List<Ability> list = i.abilities(Trigger.JOIN);
            if (!list.isEmpty() && d.identity().carries(p, i.id())) for (Ability a : list) a.fire(Activation.of(a, p, null, null, 0));
        }
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onQuit(PlayerQuitEvent e) { d.forget(e.getPlayer().getUniqueId()); }
}
