import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;

/**
 * Component designer-marks v1: apply_mark tags a target for one player (owner) for a while; query_marked finds that
 * owner's marked entities near a point. Bounded: per owner + mark at most maxPerOwner (the oldest is replaced) and at
 * most TOTAL marks plugin-wide. Marks vanish when they expire, when the target dies, when the owner quits or dies, and
 * on disable. Nothing is stored on the entity itself.
 */
public final class Marks {
    public static final int TOTAL = 2048;
    private final Map<String, LinkedHashMap<UUID, Long>> marks = new HashMap<>();
    private int total;

    private static String k(UUID owner, String mark) { return owner + "|" + mark; }

    private void prune(LinkedHashMap<UUID, Long> m, long now) {
        Iterator<Map.Entry<UUID, Long>> it = m.entrySet().iterator();
        while (it.hasNext()) if (it.next().getValue() <= now) { it.remove(); total--; }
    }

    private void pruneAll(long now) { for (LinkedHashMap<UUID, Long> m : marks.values()) prune(m, now); marks.values().removeIf(Map::isEmpty); }

    public boolean apply(UUID owner, UUID target, String mark, long now, long duration, int maxPerOwner) {
        LinkedHashMap<UUID, Long> m = marks.computeIfAbsent(k(owner, mark), x -> new LinkedHashMap<>());
        prune(m, now);
        if (m.remove(target) != null) total--;
        while (m.size() >= Math.max(1, maxPerOwner)) { Iterator<UUID> it = m.keySet().iterator(); it.next(); it.remove(); total--; }
        if (total >= TOTAL) { pruneAll(now); if (total >= TOTAL) return false; }
        m.put(target, now + duration);
        total++;
        return true;
    }

    public boolean has(UUID owner, String mark, UUID target, long now) {
        LinkedHashMap<UUID, Long> m = marks.get(k(owner, mark));
        Long t = m == null ? null : m.get(target);
        return t != null && t > now;
    }

    /** The owner's marked living entities within radius of center, nearest first, at most max. */
    public List<LivingEntity> marked(UUID owner, String mark, Location center, double radius, int max, long now) {
        LinkedHashMap<UUID, Long> m = marks.get(k(owner, mark));
        List<LivingEntity> out = new ArrayList<>();
        if (m == null || center == null || center.getWorld() == null) return out;
        prune(m, now);
        double r2 = radius * radius;
        for (UUID id : m.keySet()) {
            Entity e = Bukkit.getEntity(id);
            if (e instanceof LivingEntity le && le.isValid() && !le.isDead() && center.getWorld().equals(le.getWorld()) && le.getLocation().distanceSquared(center) <= r2) out.add(le);
        }
        out.sort(Comparator.comparingDouble((LivingEntity e) -> e.getLocation().distanceSquared(center)).thenComparing(Entity::getUniqueId));
        return out.size() > max ? new ArrayList<>(out.subList(0, Math.max(0, max))) : out;
    }

    public void removeTarget(UUID target) { for (LinkedHashMap<UUID, Long> m : marks.values()) if (m.remove(target) != null) total--; }

    public void removeOwner(UUID owner) {
        String prefix = owner + "|";
        Iterator<Map.Entry<String, LinkedHashMap<UUID, Long>>> it = marks.entrySet().iterator();
        while (it.hasNext()) { Map.Entry<String, LinkedHashMap<UUID, Long>> e = it.next(); if (e.getKey().startsWith(prefix)) { total -= e.getValue().size(); it.remove(); } }
    }

    public void clear() { marks.clear(); total = 0; }
    public int total() { return total; }
}
`;

