        if (s != null && s.matches("[a-z0-9_.-]+:[a-z0-9_./-]+") && s.length() <= 100) return s;
        String d = defaults == null ? "minecraft:ui.button.click" : defaults.getString(path, "minecraft:ui.button.click");
        notes.add(path + " is not a sound key, using " + d);
        return d;
    }

    public long seed() { return cfg.getLong("general.random_seed", 0L); }
    public List<String> notes() { return notes; }
    public String migrated() { return migrated; }
}
