public final class Checks {
    public static final int PLAYER = 1;
    public static final int HOSTILE = 2;
    public static final int ANIMAL = 4;
    public static final int LIVING = 8;

    private Checks() {}

    public static boolean kinds(Entity e, int mask) {
        if (!(e instanceof LivingEntity) || e instanceof ArmorStand) return false;
        if ((mask & LIVING) != 0) return true;
        if ((mask & PLAYER) != 0 && e instanceof Player) return true;
        if ((mask & HOSTILE) != 0 && e instanceof Enemy) return true;
        return (mask & ANIMAL) != 0 && e instanceof Animals;
    }

    /** Matches when the entity is one of the kinds OR one of the entity types (keys without "minecraft:"). */
    public static boolean targetIs(Entity e, int mask, Set<String> types) {
        if (e == null || !e.isValid()) return false;
        if (mask != 0 && kinds(e, mask)) return true;
        return types != null && !types.isEmpty() && types.contains(e.getType().getKey().getKey());
    }

    public static double healthFraction(LivingEntity e) {
        AttributeInstance a = e.getAttribute(Compat.MAX_HEALTH);
        double max = a == null ? 20.0 : a.getValue();
        return max <= 0 ? 0 : e.getHealth() / max;
    }

    /** below == true: health fraction < threshold; false: > threshold. A missing subject is always false. */
    public static boolean health(LivingEntity e, double threshold, boolean below, boolean negate) {
        if (e == null || !e.isValid()) return false;
        boolean r = below ? healthFraction(e) < threshold : healthFraction(e) > threshold;
        return negate != r;
    }

