/**
 * Component designer-listener v1 (the safe listener base): every trigger in one place. Observation handlers run at
 * MONITOR and never change or cancel the event; they skip events another plugin cancelled (ignoreCancelled), except
 * PlayerInteractEvent, which Bukkit delivers already "cancelled" for right-clicks in the air: there the item-use
 * result is checked instead (DENY = another plugin blocked it). The two handlers that ADD items (loot, mob drops) run at
 * NORMAL. Nothing here cancels another plugin's event.
 */
public final class DesignListener implements Listener {
    private final Designer d;

    DesignListener(Designer d) { this.d = d; }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onInteract(PlayerInteractEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        if (e.getAction() != Action.RIGHT_CLICK_AIR && e.getAction() != Action.RIGHT_CLICK_BLOCK) return;
        if (e.useItemInHand() == Event.Result.DENY) return;
        click(e.getPlayer(), null);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onInteractEntity(PlayerInteractEntityEvent e) {
        if (e.getHand() != EquipmentSlot.HAND) return;
        click(e.getPlayer(), e.getRightClicked());
    }

    private void click(Player p, Entity clicked) {
        if (d.busy(p)) return;
        DesignItem item = d.held(p);
        if (item == null || !d.firstClickThisTick(p)) return;
        if (p.isSneaking()) {
            boolean sneakAbility = false;
            Long start = d.chargeStart(p.getUniqueId());
            for (Ability a : item.abilities(Trigger.CHARGE_RELEASE)) {
                if (!a.releaseOnRightClick()) continue;
                sneakAbility = true;
                if (start == null) continue;
                long held = d.now() - start;
                if (held < a.minChargeTicks()) continue;
                d.clearCharge(p.getUniqueId());
                aim(a, p, clicked, a.chargeFraction(held));
            }
            List<Ability> sneak = item.abilities(Trigger.SNEAK_RIGHT_CLICK);
            for (Ability a : sneak) aim(a, p, clicked, 0);
            if (sneakAbility || !sneak.isEmpty()) return;
        }
        for (Ability a : item.abilities(Trigger.RIGHT_CLICK)) aim(a, p, clicked, 0);
    }

    /** Target + point for click triggers: the right-clicked entity, else a ray trace within the ability's targetRange. */
    private void aim(Ability a, Player p, Entity clicked, double charge) {
        Entity target = null;
        Location point = null;
        if (a.targetRange() > 0) {
            if (clicked instanceof LivingEntity && clicked.getLocation().distance(p.getLocation()) <= a.targetRange() + 1) { target = clicked; point = clicked.getLocation(); }
            else { RayTraceResult r = Targets.look(p, a.targetRange()); target = Targets.lookEntity(r); point = Targets.lookPoint(p, r, a.targetRange()); }
        }
        a.fire(Activation.of(a, p, target, point, charge));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent e) {
        if (!(e.getDamager() instanceof Player p) || !(e.getEntity() instanceof LivingEntity t)) return;
        if (e.getCause() != EntityDamageEvent.DamageCause.ENTITY_ATTACK || d.busy(p)) return;
        DesignItem item = d.held(p);
        if (item == null) return;
        for (Ability a : item.abilities(Trigger.LEFT_CLICK_HIT_ENTITY)) a.fire(Activation.of(a, p, t, t.getLocation(), 0));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDeath(EntityDeathEvent e) {
        LivingEntity dead = e.getEntity();
        Player killer = dead.getKiller();
        if (killer != null && killer != dead && !d.busy(killer)) {
            DesignItem item = d.held(killer);
            if (item != null) for (Ability a : item.abilities(Trigger.KILL_ENTITY)) a.fire(Activation.of(a, killer, dead, dead.getLocation(), 0));
        }
        d.marks().removeTarget(dead.getUniqueId());
        if (dead instanceof Player p) {
            for (DesignItem i : d.items()) {
                List<Ability> list = i.abilities(Trigger.DEATH);
                if (!list.isEmpty() && d.identity().carries(p, i.id())) for (Ability a : list) a.fire(Activation.of(a, p, null, null, 0));
            }
            d.forget(p.getUniqueId());
        }
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onDrops(EntityDeathEvent e) {
        if (e.getEntity() instanceof Player || e.getEntity().getKiller() == null) return;
        String type = e.getEntity().getType().getKey().getKey();
        for (DesignItem i : d.items()) i.drops(type, e.getDrops(), d.random());
    }

    @EventHandler(priority = EventPriority.NORMAL, ignoreCancelled = true)
    public void onLoot(LootGenerateEvent e) {
        String table = e.getLootTable().getKey().toString();
        for (DesignItem i : d.items()) i.loot(table, e.getLoot(), d.random());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onProjectile(ProjectileHitEvent e) {
        Projectile pr = e.getEntity();
        String tagged = pr.getPersistentDataContainer().get(d.projectileKey(), PersistentDataType.STRING);
        if (tagged == null) return;
        int bar = tagged.indexOf('|');
        if (bar > 0 && pr.getShooter() instanceof Player p && p.isOnline() && !d.busy(p)) {
            DesignItem item = d.item(tagged.substring(0, bar));
            String tag = tagged.substring(bar + 1);
            if (item != null) {
                Entity hit = e.getHitEntity();
                Location point = hit != null ? hit.getLocation() : e.getHitBlock() != null ? e.getHitBlock().getLocation().add(0.5, 1.0, 0.5) : pr.getLocation();
                LivingEntity t = hit instanceof LivingEntity le && hit != p ? le : null;
                for (Ability a : item.abilities(Trigger.PROJECTILE_HIT)) if (tag.equals(a.projectileTag())) a.fire(Activation.of(a, p, t, point, 0));
            }
        }
        if (pr instanceof AbstractArrow) pr.remove();
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onSneak(PlayerToggleSneakEvent e) {
        Player p = e.getPlayer();
        DesignItem item = d.held(p);
        if (e.isSneaking()) {
            if (item != null && !item.abilities(Trigger.CHARGE_RELEASE).isEmpty()) d.startCharge(p.getUniqueId());
            else d.clearCharge(p.getUniqueId());
            return;
        }
        Long start = d.chargeStart(p.getUniqueId());
        d.clearCharge(p.getUniqueId());
        if (item == null || start == null || d.busy(p)) return;
        long held = d.now() - start;
        for (Ability a : item.abilities(Trigger.CHARGE_RELEASE)) if (!a.releaseOnRightClick() && held >= a.minChargeTicks()) aim(a, p, null, a.chargeFraction(held));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onHeld(PlayerItemHeldEvent e) { d.clearCharge(e.getPlayer().getUniqueId()); }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onConsume(PlayerItemConsumeEvent e) {
        Player p = e.getPlayer();
        if (d.busy(p)) return;
        String id = d.identity().idOf(e.getItem());
        DesignItem item = id == null ? null : d.item(id);
        if (item == null) return;
        for (Ability a : item.abilities(Trigger.ITEM_CONSUME)) a.fire(Activation.of(a, p, null, null, 0));
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onJoin(PlayerJoinEvent e) {
        Player p = e.getPlayer();
        if (!d.recipeKeys().isEmpty()) p.discoverRecipes(d.recipeKeys());
        for (DesignItem i : d.items()) {
            List<Ability> list = i.abilities(Trigger.JOIN);
            if (!list.isEmpty() && d.identity().carries(p, i.id())) for (Ability a : list) a.fire(Activation.of(a, p, null, null, 0));
        }
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onQuit(PlayerQuitEvent e) { d.forget(e.getPlayer().getUniqueId()); }
}
`;

export const COMMAND_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;

/**
 * Component designer-command v1: the one command of a designer mod, declared in plugin.yml (no Brigadier):
 *   /<mod> give <item> [player] [count]   (permission <ns>.give, operators by default)
 *   /<mod> list | params [item]            (permission <ns>.command)
 *   /<mod> reload                          (permission <ns>.reload): config.yml with migration + clamping
 * Console can use every subcommand (give needs a player name there).
 */
public final class DesignCommand implements CommandExecutor, TabCompleter {
    private static final List<String> SUBS = List.of("give", "list", "params", "reload");
    private final Designer d;
    private final String label;

    DesignCommand(Designer d, String label) { this.d = d; this.label = label; }

    private static void say(CommandSender s, String text, NamedTextColor color) { s.sendMessage(Component.text(text, color)); }

    private boolean allowed(CommandSender s, String node) {
        if (s.hasPermission(d.namespace() + "." + node)) return true;
        say(s, "You don't have permission for that.", NamedTextColor.RED);
        return false;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String used, String[] args) {
        if (args.length == 0) {
            List<String> ids = new ArrayList<>();
            for (DesignItem i : d.items()) ids.add(i.id());
            say(sender, d.plugin().getName() + " items: " + String.join(", ", ids) + ". Use /" + label + " give <item> [player] [count], /" + label + " list, /" + label + " params, /" + label + " reload", NamedTextColor.GOLD);
            return true;
        }
        switch (args[0].toLowerCase(Locale.ROOT)) {
            case "give" -> give(sender, args);
            case "list" -> list(sender);
            case "params" -> params(sender, args);
            case "reload" -> {
                if (!allowed(sender, "reload")) return true;
                List<String> notes = d.reload();
                say(sender, d.plugin().getName() + " config reloaded" + (notes.isEmpty() ? "" : " (" + notes.size() + " note" + (notes.size() == 1 ? "" : "s") + ")"), NamedTextColor.GREEN);
                for (String n : notes) say(sender, "- " + n, NamedTextColor.YELLOW);
            }
            default -> say(sender, "Unknown subcommand. Use /" + label + " give, list, params or reload.", NamedTextColor.RED);
        }
        return true;
    }

    private void give(CommandSender sender, String[] args) {
        if (!allowed(sender, "give")) return;
        if (args.length < 2) { say(sender, "Usage: /" + label + " give <item> [player] [count]", NamedTextColor.RED); return; }
        DesignItem item = d.item(args[1].toLowerCase(Locale.ROOT));
        if (item == null) { say(sender, "Unknown item " + args[1] + ".", NamedTextColor.RED); return; }
        Player target;
        if (args.length >= 3) {
            target = Bukkit.getPlayerExact(args[2]);
            if (target == null) { say(sender, "Player " + args[2] + " is not online.", NamedTextColor.RED); return; }
        } else if (sender instanceof Player p) target = p;
        else { say(sender, "Usage from the console: /" + label + " give <item> <player> [count]", NamedTextColor.RED); return; }
        int count = 1;
        if (args.length >= 4) {
            try { count = Math.max(1, Math.min(64, Integer.parseInt(args[3]))); }
            catch (NumberFormatException e) { say(sender, "Count must be a number from 1 to 64.", NamedTextColor.RED); return; }
        }
        for (int i = 0; i < count; i++) for (ItemStack left : target.getInventory().addItem(item.create()).values()) target.getWorld().dropItemNaturally(target.getLocation(), left);
        say(sender, "Gave " + count + " x " + item.id() + " to " + target.getName() + ".", NamedTextColor.GREEN);
    }

    private void list(CommandSender sender) {
        if (!allowed(sender, "command")) return;
        for (DesignItem i : d.items()) {
            ItemStack s = i.create();
            boolean identity = d.identity().is(s, i.id());
            boolean recipe = Bukkit.getRecipe(new NamespacedKey(d.namespace(), i.id())) != null;
            say(sender, i.id() + ": identity=" + (identity ? "ok" : "MISSING") + " material=" + s.getType().getKey().getKey() + " abilities=" + i.abilities().size() + " recipe=" + (recipe ? "registered" : "none"), identity ? NamedTextColor.AQUA : NamedTextColor.RED);
        }
    }

    private void params(CommandSender sender, String[] args) {
        if (!allowed(sender, "command")) return;
        List<String> out = new ArrayList<>();
        for (DesignItem i : d.items()) if (args.length < 2 || i.id().equals(args[1].toLowerCase(Locale.ROOT))) i.describe(out);
        if (out.isEmpty()) say(sender, "No parameters.", NamedTextColor.GRAY);
        for (String line : out) say(sender, line, NamedTextColor.AQUA);
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String used, String[] args) {
        List<String> out = new ArrayList<>();
        String last = args.length == 0 ? "" : args[args.length - 1].toLowerCase(Locale.ROOT);
        if (args.length <= 1) { for (String s : SUBS) if (s.startsWith(last)) out.add(s); }
        else if (args.length == 2 && (args[0].equalsIgnoreCase("give") || args[0].equalsIgnoreCase("params"))) { for (DesignItem i : d.items()) if (i.id().startsWith(last)) out.add(i.id()); }
        else if (args.length == 3 && args[0].equalsIgnoreCase("give")) { for (Player p : Bukkit.getOnlinePlayers()) if (p.getName().toLowerCase(Locale.ROOT).startsWith(last)) out.add(p.getName()); }
        return out;
    }
}
`;

