  { id: "designer-checks", file: "designer/Checks.java", purpose: "condition helpers (kinds/types, health, time of day)", families: ALL, limits: ["a condition about a missing target is false"], tests: [UNIT, REAL, "simulator condition tests"], source: J.CHECKS_JAVA },
  { id: "designer-targets", file: "designer/Targets.java", purpose: "target selection helpers with caps (ray trace, nearby sphere, nearest first)", families: ALL, limits: ["ray trace 1..32 blocks", "nearby radius 1..12, max 1..16", "never the player, no armor stands, players only on request"], tests: [UNIT, REAL], source: J.TARGETS_JAVA },
  { id: "designer-effects", file: "designer/Effects.java", purpose: "every action: damage/heal/potion/knockback/pull/push/safe teleport/projectiles/particles/sound/text/give", families: ALL, limits: ["velocity <= 4 blocks/tick", "teleport self only, safe-location search", "projectiles removed after their lifetime, arrows not pickable", "fireballs non-incendiary, yield 0", "sounds by namespaced key only"], tests: [UNIT, REAL], source: J.EFFECTS_JAVA },
  { id: "designer-ability", file: "designer/Ability.java", purpose: "fixed activation protocol (guard, cooldown, charges, conditions, actions)", families: ALL, limits: ["no re-entry: effects of an activation never trigger abilities"], tests: [UNIT, REAL, "simulator protocol tests"], source: J.ABILITY_JAVA },
  { id: "designer-item", file: "designer/DesignItem.java", purpose: "base of every design item", families: ALL, limits: [], tests: [UNIT, REAL], source: J.ITEM_JAVA },
  { id: "designer-runtime", file: "designer/Designer.java", purpose: "the hub: state ownership, reload, timers, cleanup", families: ALL, limits: ["held_interval >= 10 ticks", "passives every 40 ticks"], tests: [UNIT, REAL], source: J.DESIGNER_JAVA },
  { id: "designer-listener", file: "designer/DesignListener.java", purpose: "safe listener base: all triggers, MONITOR observation, never cancels", families: ALL, limits: ["one click activation per player per tick", "main hand only"], tests: [UNIT, REAL], source: J.LISTENER_JAVA },
  { id: "designer-command", file: "designer/DesignCommand.java", purpose: "plugin.yml command: give / list / params / reload with permissions", families: ALL, limits: ["give count 1..64"], tests: [UNIT, REAL, "Test Flight: RCON give/list/params/reload"], source: J.COMMAND_JAVA },
];

/** The only per-version Java: attribute constants and the item_model call. */
export function compatSource(fe: DesignFeatures): string {
  const p = fe.attributeNames === "generic-prefix" ? "GENERIC_" : "";
  const model = fe.itemModel
    ? "meta.setItemModel(new NamespacedKey(namespace, key));"
    : `// item_model needs Minecraft 1.21.4+; on ${fe.version} the item keeps its base look (no legacy custom_model_data emitter yet)`;
  return `package __PKG__.designer;

${fe.itemModel ? "import org.bukkit.NamespacedKey;\n" : ""}import org.bukkit.attribute.Attribute;
import org.bukkit.inventory.meta.ItemMeta;

/** Component designer-compat v1: the per-version adapter (Minecraft ${fe.version}, Java ${fe.javaRelease}, attributes ${fe.attributeNames}, item models ${fe.itemModel ? "yes" : "no"}). */
public final class Compat {
    public static final String MINECRAFT = "${fe.version}";
    public static final boolean ITEM_MODELS = ${fe.itemModel};
    public static final Attribute ATTACK_DAMAGE = Attribute.${p}ATTACK_DAMAGE;
    public static final Attribute ATTACK_SPEED = Attribute.${p}ATTACK_SPEED;
    public static final Attribute MAX_HEALTH = Attribute.${p}MAX_HEALTH;

    private Compat() {}

    public static void itemModel(ItemMeta meta, String namespace, String key) {
        ${model}
    }
}
`;
}

export const COMPAT_META: Omit<ComponentMeta, "source"> = { id: "designer-compat", file: "designer/Compat.java", purpose: "per-version adapter: GENERIC_ attribute names on 1.21.1, item_model on 1.21.4+", families: ALL, limits: ["1.21.1: no item model"], tests: [UNIT, REAL] };

export const renderComponent = (source: string, pkg: string) => source.replace(/__PKG__/g, pkg);

/** Hash of the whole library (sources + metadata), recorded in every compile result as part of the engine release. */
export function libraryHash(): string {
  const h = createHash("sha256");
  h.update(COMPONENT_LIBRARY_VERSION);
  for (const c of COMPONENTS) { h.update(c.id); h.update(c.source); }
  h.update(compatSource({ version: "x", itemModel: true, attributeNames: "plain", javaRelease: 21, scheduling: "paper" }));
  return h.digest("hex");
}

