// Cyrus R3 gameplay designers: the COMPILER. Validated item designs -> a complete Paper plugin source tree (Java,
// plugin.yml, config.yml) + README text for the mod page, deterministically (same designs + context = same bytes;
// golden-hash tested). The ability graph is compiled to straight Java that calls the verified component library
// (./components): no interpreter, no reflection, no free-form code. Every number, text and sound key of the graph is a
// config.yml PARAMETER (Java reads it through the clamping config loader), so editing a parameter changes config.yml
// (+ the README) and never a Java file (./params.ts proves it with a diff). Structure (kinds, effects, particles,
// targets, stats, recipe) is Java.
import { createHash } from "node:crypto";
import { COMPAT_META, COMPONENTS, COMPONENT_LIBRARY_VERSION, compatSource, libraryHash, renderComponent } from "./components";
import {
  CAPS, CONSUMABLE_BASES, DESIGN_SPEC_VERSION, RUNTIME_CAPS, TRIGGER_HAS_TARGET, validateDesigns, walkActions,
  type Ability, type Action, type CapName, type Condition, type DesignContext, type DesignFeatures, type DzIssue, type ItemDesign,
} from "./spec";

export const COMPILER_VERSION = "cyrus-designer-compile-1";
/** Lanes where the generated sources were compiled with javac against the real Paper classpath (test/cyrus-designer-real.ts). */
export const JAVAC_VERIFIED_VERSIONS = ["1.21.11", "26.2"] as const;

export type ParamKind = "num" | "ticks" | "int" | "text" | "sound";
export type Param = {
  /** Full config.yml path. */
  path: string;
  /** Java field (in the ability or item class). */
  field: string;
  kind: ParamKind;
  min: number;
  max: number;
  value: number | string;
  label: string;
  item: string;
  ability?: string;
  /** What the parameter is, for edit matching: cooldown / range / strength / sound / damage / heal / duration / chance / count / radius / text / other. */
  role: string;
};

export type CompileContext = {
  version: string;
  namespace: string;
  pluginName: string;
  pluginVersion?: string;
  description?: string;
  /** Free-form extension code exists at src/main/java/<pkg>/custom/CustomHooks.java (enable(JavaPlugin) / disable()). */
  customHooks?: boolean;
  /** The previous build's config.yml text: config_version is kept when the designer values did not change, else bumped. */
  previousConfig?: string;
  assets?: DesignContext["assets"];
};

export type CompiledFile = { path: string; content: string; sha256: string; role: "component" | "compat" | "generated" | "resource" };
export type CompileOk = {
  ok: true; files: CompiledFile[]; readme: string; readmeSha256: string; hash: string; params: Param[]; warnings: DzIssue[]; notes: string[];
  pkg: string; mainClass: string; command: string; configVersion: number; designerValuesHash: string; features: DesignFeatures;
  javacVerified: boolean; compiler: string; library: string; libraryHash: string; designs: ItemDesign[];
};
export type CompileResult = CompileOk | { ok: false; errors: DzIssue[]; warnings: DzIssue[] };

const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
const camel = (s: string) => s.split("_").filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join("");
const jstr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
const ystr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
const fmtNum = (v: number, kind: ParamKind) => (kind === "num" ? (Number.isInteger(v) ? v.toFixed(1) : String(v)) : String(Math.round(v)));
const jnum = (v: number) => (Number.isInteger(v) ? `${v}.0` : String(v));
const fieldOf = (rel: string) => "p_" + rel.replace(/[.]/g, "_");
const COLOR_NAMES: Record<string, string> = { black: "BLACK", dark_blue: "DARK_BLUE", dark_green: "DARK_GREEN", dark_aqua: "DARK_AQUA", dark_red: "DARK_RED", dark_purple: "DARK_PURPLE", gold: "GOLD", gray: "GRAY", dark_gray: "DARK_GRAY", blue: "BLUE", green: "GREEN", aqua: "AQUA", red: "RED", light_purple: "LIGHT_PURPLE", yellow: "YELLOW", white: "WHITE" };
const colorExpr = (c?: string) => (!c ? "null" : c.startsWith("#") ? `TextColor.color(0x${c.slice(1).toUpperCase()})` : `NamedTextColor.${COLOR_NAMES[c]}`);
const KIND_BITS: Record<string, number> = { player: 1, hostile: 2, animal: 4, living: 8 };
const maskOf = (k?: string[]) => (k ?? []).reduce((m, x) => m | (KIND_BITS[x] ?? 0), 0);
const bare = (id: string) => id.replace(/^minecraft:/, "");
const MATERIAL = (id: string) => `Material.${bare(id).toUpperCase()}`;

/** Optional-field defaults (documented in docs "Cyrus gameplay designers (R3)"). */
export const DEFAULTS = {
  knockbackVertical: 0.35, pullVertical: 0.25, pushVertical: 0.35, amplifier: 0, lifetimeTicks: 100, spread: 0.3, particleSpeed: 0.02,
  volume: 1, pitch: 1, fadeInTicks: 10, stayTicks: 40, fadeOutTicks: 10, giveCount: 1, chargeCost: 1, passiveAmplifier: 0,
} as const;

// ------------------------------------------------------------------------------------------------------- parameters
type ParamSink = { params: Param[]; base: string; item: string; ability?: string; abilityName?: string };
function addParam(s: ParamSink, rel: string, kind: ParamKind, cap: CapName | [number, number], value: number | string, label: string, role: string): Param {
  const [min, max] = Array.isArray(cap) ? cap : CAPS[cap as CapName];
  const p: Param = { path: s.base + rel, field: fieldOf(rel), kind, min, max, value, label: s.abilityName ? `${s.abilityName}: ${label}` : label, item: s.item, ...(s.ability ? { ability: s.ability } : {}), role };
  s.params.push(p);
  return p;
}

/** The parameters of one ability, in config order (also the Java field order). */
export function abilityParams(item: ItemDesign, ab: Ability): Param[] {
  const s: ParamSink = { params: [], base: `items.${item.id}.abilities.${ab.id}.`, item: item.id, ability: ab.id, abilityName: ab.name };
  if (ab.cooldownTicks !== undefined) addParam(s, "cooldown_ticks", "ticks", "cooldownTicks", ab.cooldownTicks, "cooldown (ticks, 20 = 1 s)", "cooldown");
  if (ab.charges) { addParam(s, "charges.max", "int", "chargesMax", ab.charges.max, "charges", "charges"); addParam(s, "charges.regen_ticks", "ticks", "chargeRegenTicks", ab.charges.regenTicks, "ticks per charge regained", "cooldown"); }
  const t = ab.trigger;
  if ("targetRange" in t && t.targetRange !== undefined) addParam(s, "trigger.target_range", "num", "targetRange", t.targetRange, "target range (blocks)", "range");
  if (t.type === "held_interval") addParam(s, "trigger.period_ticks", "ticks", "periodTicks", t.periodTicks, "interval (ticks)", "cooldown");
  if (t.type === "charge_release") { addParam(s, "trigger.min_charge_ticks", "ticks", "minChargeTicks", t.minChargeTicks, "minimum charge (ticks)", "duration"); addParam(s, "trigger.max_charge_ticks", "ticks", "maxChargeTicks", t.maxChargeTicks, "full charge (ticks)", "duration"); }
  const cond = (c: Condition, rel: string) => {
    switch (c.type) {
      case "health_below": case "health_above": addParam(s, `${rel}.fraction`, "num", "healthFraction", c.fraction, `${c.type.replace("_", " ")} (fraction of max health)`, "other"); break;
      case "random_chance": addParam(s, `${rel}.chance`, "num", "chance", c.chance, "chance (0-1)", "chance"); break;
      case "time_of_day": addParam(s, `${rel}.from`, "int", "timeOfDay", c.from, "time window start (ticks)", "other"); addParam(s, `${rel}.to`, "int", "timeOfDay", c.to, "time window end (ticks)", "other"); break;
      case "charges_available": addParam(s, `${rel}.amount`, "int", "chargeCost", c.amount, "charges needed", "count"); break;
      default: break;
    }
  };
  (ab.conditions ?? []).forEach((c, i) => cond(c, `c${i}`));
  walkActions(ab.actions, (a, p) => {
    switch (a.type) {
      case "damage": addParam(s, `${p}.amount`, "num", "damage", a.amount, "damage (health points)", "damage"); break;
      case "heal": addParam(s, `${p}.amount`, "num", "heal", a.amount, "heal (health points)", "heal"); break;
      case "potion_effect": addParam(s, `${p}.duration_ticks`, "ticks", "potionTicks", a.durationTicks, `${a.effect} duration (ticks)`, "duration"); addParam(s, `${p}.amplifier`, "int", "amplifier", a.amplifier ?? DEFAULTS.amplifier, `${a.effect} level - 1`, "strength"); break;
      case "knockback": case "pull_to": case "push_from": {
        const dv = a.type === "knockback" ? DEFAULTS.knockbackVertical : a.type === "pull_to" ? DEFAULTS.pullVertical : DEFAULTS.pushVertical;
        addParam(s, `${p}.strength`, "num", "strength", a.strength, `${a.type.replace("_", " ")} strength`, "strength"); addParam(s, `${p}.vertical`, "num", "vertical", a.vertical ?? dv, `${a.type.replace("_", " ")} lift`, "strength"); break;
      }
      case "teleport_short": addParam(s, `${p}.range`, "num", "teleportRange", a.range, "teleport range (blocks)", "range"); break;
      case "launch_projectile": addParam(s, `${p}.speed`, "num", "projectileSpeed", a.speed, `${a.kind} speed`, "strength"); addParam(s, `${p}.lifetime_ticks`, "ticks", "projectileLifetime", a.lifetimeTicks ?? DEFAULTS.lifetimeTicks, `${a.kind} lifetime (ticks)`, "duration"); break;
      case "spawn_particles": addParam(s, `${p}.count`, "int", "particleCount", a.count, `${a.particle} particles`, "count"); addParam(s, `${p}.spread`, "num", "particleSpread", a.spread ?? DEFAULTS.spread, `${a.particle} spread`, "other"); addParam(s, `${p}.speed`, "num", "particleSpeed", a.speed ?? DEFAULTS.particleSpeed, `${a.particle} speed`, "other"); break;
      case "play_sound": addParam(s, `${p}.sound`, "sound", [0, 100], a.sound, "sound key", "sound"); addParam(s, `${p}.volume`, "num", "volume", a.volume ?? DEFAULTS.volume, "sound volume", "other"); addParam(s, `${p}.pitch`, "num", "pitch", a.pitch ?? DEFAULTS.pitch, "sound pitch", "other"); break;
      case "send_message": case "actionbar": addParam(s, `${p}.text`, "text", [0, RUNTIME_CAPS.textChars], a.text, a.type === "actionbar" ? "actionbar text" : "message text", "text"); break;
      case "title":
        addParam(s, `${p}.title`, "text", [0, RUNTIME_CAPS.titleChars], a.title, "title text", "text");
        if (a.subtitle !== undefined) addParam(s, `${p}.subtitle`, "text", [0, RUNTIME_CAPS.subtitleChars], a.subtitle, "subtitle text", "text");
        addParam(s, `${p}.fade_in_ticks`, "ticks", "titleFadeTicks", a.fadeInTicks ?? DEFAULTS.fadeInTicks, "title fade in", "duration");
        addParam(s, `${p}.stay_ticks`, "ticks", "titleStayTicks", a.stayTicks ?? DEFAULTS.stayTicks, "title stay", "duration");
        addParam(s, `${p}.fade_out_ticks`, "ticks", "titleFadeTicks", a.fadeOutTicks ?? DEFAULTS.fadeOutTicks, "title fade out", "duration");
        break;
      case "give_item": addParam(s, `${p}.count`, "int", "giveCount", a.count ?? DEFAULTS.giveCount, `${a.item} count`, "count"); break;
      case "set_cooldown": {
        const ref = item.abilities.find((x) => x.id === (a.ability ?? ab.id));
        addParam(s, `${p}.ticks`, "ticks", "cooldownTicks", a.ticks ?? ref?.cooldownTicks ?? 0, `cooldown set on ${a.ability ?? ab.id} (ticks)`, "cooldown"); break;
      }
      case "consume_charge": addParam(s, `${p}.amount`, "int", "chargeCost", a.amount ?? DEFAULTS.chargeCost, "charges spent", "count"); break;
      case "query_marked": addParam(s, `${p}.radius`, "num", "queryMarkedRadius", a.radius, `marked "${a.mark}" search radius`, "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
      case "query_nearby": addParam(s, `${p}.radius`, "num", "queryNearbyRadius", a.radius, "nearby search radius", "range"); addParam(s, `${p}.max`, "int", "queryMax", a.max, "max targets", "count"); break;
      case "delayed": addParam(s, `${p}.delay_ticks`, "ticks", "delayTicks", a.delayTicks, "delay (ticks)", "duration"); break;
      case "branch": a.if.forEach((c, i) => cond(c, `${p}.if${i}`)); break;
      default: break;
    }
  });
  return s.params;
}

export function itemParams(item: ItemDesign): Param[] {
  const s: ParamSink = { params: [], base: `items.${item.id}.`, item: item.id };
  for (const m of item.marks ?? []) { addParam(s, `marks.${m.name}.duration_ticks`, "ticks", "markTicks", m.durationTicks, `mark "${m.name}" duration (ticks)`, "duration"); addParam(s, `marks.${m.name}.max_per_owner`, "int", "marksPerOwner", m.maxPerOwner, `mark "${m.name}" max per player`, "count"); }
  (item.passives ?? []).forEach((p, i) => addParam(s, `passives.p${i}.amplifier`, "int", "passiveAmplifier", p.amplifier ?? DEFAULTS.passiveAmplifier, `passive ${p.effect} level - 1`, "strength"));
  (item.acquisition?.loot ?? []).forEach((l, i) => addParam(s, `loot.l${i}.chance`, "num", "lootChance", l.chance, `chance in ${l.table}`, "chance"));
  (item.acquisition?.drops ?? []).forEach((l, i) => addParam(s, `drops.d${i}.chance`, "num", "lootChance", l.chance, `drop chance from ${l.entity}`, "chance"));
  return s.params;
}

export function designParams(designs: ItemDesign[]): Param[] {
  return [...designs].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)).flatMap((d) => [...itemParams(d), ...d.abilities.flatMap((ab) => abilityParams(d, ab))]);
}

// ---------------------------------------------------------------------------------------------------- Java codegen
class Out {
  lines: string[] = [];
  push(ind: number, s: string) { this.lines.push("    ".repeat(ind) + s); }
}
const JTYPE: Record<ParamKind, string> = { num: "double", ticks: "long", int: "int", text: "String", sound: "String" };
function loadLine(p: Param, rel: string): string {
  switch (p.kind) {
    case "num": return `${p.field} = c.num(B + ${jstr(rel)}, ${jnum(p.min)}, ${jnum(p.max)});`;
    case "ticks": return `${p.field} = c.ticks(B + ${jstr(rel)}, ${p.min}L, ${p.max}L);`;
    case "int": return `${p.field} = c.integer(B + ${jstr(rel)}, ${p.min}, ${p.max});`;
    case "text": return `${p.field} = c.text(B + ${jstr(rel)}, ${p.max});`;
    case "sound": return `${p.field} = c.soundKey(B + ${jstr(rel)});`;
  }
}

type AbGen = { item: ItemDesign; ab: Ability; params: Map<string, Param>; statics: string[]; ns: string; loopN: number };
const P = (g: AbGen, rel: string) => { const p = g.params.get(rel); if (!p) throw new Error(`internal: no parameter ${rel}`); return p.field; };

function condExpr(g: AbGen, c: Condition, rel: string, A: string): string {
  const neg = (e: string) => (c.negate ? `!(${e})` : e);
  const own = (ref?: string) => !ref || ref === g.ab.id;
  const other = (ref: string) => `d.ability(${jstr(g.item.id)}, ${jstr(ref)})`;
  switch (c.type) {
    case "cooldown_ready": return neg(own(c.ability) ? `cooldownReady(${A}.player())` : `(${other(c.ability!)} == null || ${other(c.ability!)}.cooldownReady(${A}.player()))`);
    case "has_permission": return neg(`${A}.player().hasPermission(${jstr(`${g.ns}.${c.node}`)})`);
    case "target_is": {
      const set = c.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
      if (c.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${c.types.map((t) => jstr(bare(t))).join(", ")});`);
      const e = `Checks.targetIs(${A}.target(), ${maskOf(c.kinds)}, ${set})`;
      return c.negate ? `(${A}.target() != null && ${A}.target().isValid() && !${e})` : e;
    }
    case "world_in": {
      const set = `W_${rel.replace(/\./g, "_")}`;
      g.statics.push(`private static final Set<String> ${set} = Set.of(${c.worlds.map(jstr).join(", ")});`);
      return neg(`${set}.contains(${A}.player().getWorld().getName())`);
    }
    case "health_below": case "health_above":
      return `Checks.health(${c.subject === "self" ? `${A}.player()` : `${A}.livingTarget()`}, ${P(g, `${rel}.fraction`)}, ${c.type === "health_below"}, ${!!c.negate})`;
    case "item_identity": return neg(`d.identity().is(${A}.player().getInventory().${c.slot === "main_hand" ? "getItemInMainHand" : "getItemInOffHand"}(), ${jstr(c.item)})`);
    case "sneaking": return neg(`${A}.player().isSneaking()`);
    case "charges_available": return neg(own(c.ability) ? `chargesLeft(${A}.player()) >= ${P(g, `${rel}.amount`)}` : `(${other(c.ability!)} != null && ${other(c.ability!)}.chargesLeft(${A}.player()) >= ${P(g, `${rel}.amount`)})`);
    case "random_chance": return neg(`d.random().nextDouble() < ${P(g, `${rel}.chance`)}`);
    case "time_of_day": return neg(`Checks.timeIn(${A}.player().getWorld(), ${P(g, `${rel}.from`)}, ${P(g, `${rel}.to`)})`);
  }
}

function actions(g: AbGen, o: Out, list: Action[], prefix: string, A: string, ind: number): void {
  list.forEach((a, i) => {
    const rel = prefix ? `${prefix}${i}` : `a${i}`;
    o.push(ind, `// ${rel}: ${a.type}`);
    o.push(ind, `if (!${A}.budget().action()) return;`);
    const subj = (t: string | undefined, dflt: "self" | "target") => ((t ?? dflt) === "self" ? `${A}.player()` : `${A}.livingTarget()`);
    const ent = (t: string | undefined) => ((t ?? "self") === "self" ? `${A}.player()` : `${A}.target()`);
    const at = (w: string | undefined) => (w === "target" ? `d.effects().target(${A})` : w === "point" ? `d.effects().point(${A})` : `d.effects().self(${A})`);
    const scale = (b?: boolean) => (b ? ` * ${A}.charge()` : "");
    switch (a.type) {
      case "damage": o.push(ind, `d.effects().damage(${A}, ${subj(a.target, "target")}, ${P(g, `${rel}.amount`)}${scale(a.scaleWithCharge)});`); break;
      case "heal": o.push(ind, `d.effects().heal(${A}, ${subj(a.target, "self")}, ${P(g, `${rel}.amount`)}${scale(a.scaleWithCharge)});`); break;
      case "potion_effect": o.push(ind, `d.effects().potion(${A}, ${subj(a.target, "self")}, PotionEffectType.${a.effect.toUpperCase()}, (int) ${P(g, `${rel}.duration_ticks`)}, ${P(g, `${rel}.amplifier`)});`); break;
      case "knockback": o.push(ind, `d.effects().knockback(${A}, ${subj(a.target, "target")}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
      case "pull_to": o.push(ind, `d.effects().pullTo(${A}, ${subj(a.target, "target")}, ${a.to === "self" ? `${A}.player().getLocation()` : `${A}.point()`}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
      case "push_from": o.push(ind, `d.effects().pushFrom(${A}, ${subj(a.target, "target")}, ${a.from === "self" ? `${A}.player().getLocation()` : `${A}.point()`}, ${P(g, `${rel}.strength`)}${scale(a.scaleWithCharge)}, ${P(g, `${rel}.vertical`)});`); break;
      case "teleport_short": o.push(ind, `d.effects().teleportShort(${A}, ${P(g, `${rel}.range`)});`); break;
      case "launch_projectile": o.push(ind, `d.effects().launch(${A}, ${jstr(a.kind)}, ${P(g, `${rel}.speed`)}, ${a.tag ? jstr(a.tag) : "null"}, ${P(g, `${rel}.lifetime_ticks`)});`); break;
      case "spawn_particles": o.push(ind, `d.effects().particles(${A}, ${at(a.at)}, Particle.${a.particle.toUpperCase()}, ${P(g, `${rel}.count`)}, ${P(g, `${rel}.spread`)}, ${P(g, `${rel}.speed`)});`); break;
      case "play_sound": o.push(ind, `d.effects().sound(${A}, ${at(a.at)}, ${P(g, `${rel}.sound`)}, (float) ${P(g, `${rel}.volume`)}, (float) ${P(g, `${rel}.pitch`)});`); break;
      case "send_message": o.push(ind, `d.effects().message(${A}, ${ent(a.to)}, ${P(g, `${rel}.text`)}, ${colorExpr(a.color)});`); break;
      case "actionbar": o.push(ind, `d.effects().actionbar(${A}, ${ent(a.to)}, ${P(g, `${rel}.text`)}, ${colorExpr(a.color)});`); break;
      case "title": o.push(ind, `d.effects().title(${A}, ${ent(a.to)}, ${P(g, `${rel}.title`)}, ${a.subtitle !== undefined ? P(g, `${rel}.subtitle`) : "null"}, ${colorExpr(a.color)}, ${P(g, `${rel}.fade_in_ticks`)}, ${P(g, `${rel}.stay_ticks`)}, ${P(g, `${rel}.fade_out_ticks`)});`); break;
      case "give_item":
        if (a.item.startsWith("minecraft:")) o.push(ind, `d.effects().give(${A}, new ItemStack(${MATERIAL(a.item)}), ${P(g, `${rel}.count`)});`);
        else { o.push(ind, `{`); o.push(ind + 1, `DesignItem gi = d.item(${jstr(a.item)});`); o.push(ind + 1, `d.effects().give(${A}, gi == null ? null : gi.create(), ${P(g, `${rel}.count`)});`); o.push(ind, `}`); }
        break;
      case "set_cooldown":
        if (!a.ability || a.ability === g.ab.id) o.push(ind, `startCooldown(${A}.player(), ${P(g, `${rel}.ticks`)});`);
        else { o.push(ind, `{`); o.push(ind + 1, `Ability o = d.ability(${jstr(g.item.id)}, ${jstr(a.ability)});`); o.push(ind + 1, `if (o != null) o.startCooldown(${A}.player(), ${P(g, `${rel}.ticks`)});`); o.push(ind, `}`); }
        break;
      case "consume_charge":
        if (!a.ability || a.ability === g.ab.id) o.push(ind, `spendCharges(${A}.player(), ${P(g, `${rel}.amount`)});`);
        else { o.push(ind, `{`); o.push(ind + 1, `Ability o = d.ability(${jstr(g.item.id)}, ${jstr(a.ability)});`); o.push(ind + 1, `if (o != null) o.spendCharges(${A}.player(), ${P(g, `${rel}.amount`)});`); o.push(ind, `}`); }
        break;
      case "apply_mark":
        o.push(ind, `{`);
        o.push(ind + 1, `LivingEntity mt = ${A}.livingTarget();`);
        o.push(ind + 1, `DesignItem.Mark m = d.item(${jstr(g.item.id)}).mark(${jstr(a.mark)});`);
        o.push(ind + 1, `if (mt != null && mt != ${A}.player() && ${A}.budget().entity() && d.marks().apply(${A}.player().getUniqueId(), mt.getUniqueId(), ${jstr(`${g.item.id}.${a.mark}`)}, d.now(), m.ticks(), m.max()) && m.glow()) mt.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING, (int) m.ticks(), 0, false, false));`);
        o.push(ind, `}`);
        break;
      case "query_marked": case "query_nearby": {
        const n = ++g.loopN;
        const around = a.around === "point" ? `${A}.point()` : `${A}.player().getLocation()`;
        if (a.type === "query_marked") o.push(ind, `for (LivingEntity t${n} : d.marks().marked(${A}.player().getUniqueId(), ${jstr(`${g.item.id}.${a.mark}`)}, ${around}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.max`)}, d.now())) {`);
        else {
          const set = a.types?.length ? `T_${rel.replace(/\./g, "_")}` : "null";
          if (a.types?.length) g.statics.push(`private static final Set<String> ${set} = Set.of(${a.types.map((t) => jstr(bare(t))).join(", ")});`);
          o.push(ind, `for (LivingEntity t${n} : Targets.nearby(${A}.player(), ${around}, ${P(g, `${rel}.radius`)}, ${P(g, `${rel}.max`)}, ${maskOf(a.kinds)}, ${set}, ${!!a.includePlayers})) {`);
        }
        o.push(ind + 1, `Activation a${n} = ${A}.withTarget(t${n});`);
        actions(g, o, a.actions, `${rel}.n`, `a${n}`, ind + 1);
        o.push(ind, `}`);
        break;
      }
      case "delayed":
        o.push(ind, `d.later(${A}, ${P(g, `${rel}.delay_ticks`)}, () -> {`);
        actions(g, o, a.actions, `${rel}.n`, A, ind + 1);
        o.push(ind, `});`);
        break;
      case "branch":
        o.push(ind, `if (${a.if.map((c, j) => condExpr(g, c, `${rel}.if${j}`, A)).join(" && ")}) {`);
        actions(g, o, a.then, `${rel}.then`, A, ind + 1);
        if (a.else) { o.push(ind, `} else {`); actions(g, o, a.else, `${rel}.else`, A, ind + 1); }
        o.push(ind, `}`);
        break;
    }
  });
}

const TRIGGER_ENUM = (t: string) => t.toUpperCase();

function abilityClass(pkg: string, item: ItemDesign, ab: Ability, cls: string, ns: string): { source: string; params: Param[] } {
  const params = abilityParams(item, ab);
  const base = `items.${item.id}.abilities.${ab.id}.`;
  const g: AbGen = { item, ab, params: new Map(params.map((p) => [p.path.slice(base.length), p])), statics: [], ns, loopN: 0 };
  const check = new Out();
  (ab.conditions ?? []).forEach((c, i) => check.push(2, `if (!(${condExpr(g, c, `c${i}`, "a")})) return false;`));
  const run = new Out();
  actions(g, run, ab.actions, "", "a", 2);
  const t = ab.trigger;
  const ctor: string[] = [];
  if (ab.manualCooldown) ctor.push("manualCooldown = true;");
  if (ab.manualCharges) ctor.push("manualCharges = true;");
  if (ab.feedback) ctor.push("feedback = true;");
  if (t.type === "charge_release" && t.release === "right_click") ctor.push("releaseOnRightClick = true;");
  if (t.type === "held_interval" && t.slot === "inventory") ctor.push("inventorySlot = true;");
  if (t.type === "projectile_hit") ctor.push(`projectileTag = ${jstr(t.tag)};`);
  const load: string[] = [];
  for (const p of params) {
    const rel = p.path.slice(base.length);
    load.push(loadLine(p, rel));
  }
  if (ab.cooldownTicks !== undefined) load.push("cooldownTicks = p_cooldown_ticks;");
  if (ab.charges) { load.push("maxCharges = p_charges_max;"); load.push("chargeRegenTicks = p_charges_regen_ticks;"); }
  if ("targetRange" in t && t.targetRange !== undefined) load.push("targetRange = p_trigger_target_range;");
  if (t.type === "held_interval") load.push("periodTicks = p_trigger_period_ticks;");
  if (t.type === "charge_release") { load.push("minChargeTicks = p_trigger_min_charge_ticks;"); load.push("maxChargeTicks = Math.max(p_trigger_min_charge_ticks, p_trigger_max_charge_ticks);"); }
  const src = [
    `package ${pkg}.abilities;`,
    ``,
    `import java.util.List;`,
    `import java.util.Set;`,
    `import net.kyori.adventure.text.format.NamedTextColor;`,
    `import net.kyori.adventure.text.format.TextColor;`,
    `import org.bukkit.Material;`,
    `import org.bukkit.Particle;`,
    `import org.bukkit.entity.LivingEntity;`,
    `import org.bukkit.inventory.ItemStack;`,
    `import org.bukkit.potion.PotionEffect;`,
    `import org.bukkit.potion.PotionEffectType;`,
    `import ${pkg}.designer.Ability;`,
    `import ${pkg}.designer.Activation;`,
    `import ${pkg}.designer.Checks;`,
    `import ${pkg}.designer.DesignConfig;`,
    `import ${pkg}.designer.DesignItem;`,
    `import ${pkg}.designer.Designer;`,
    `import ${pkg}.designer.Targets;`,
    `import ${pkg}.designer.Trigger;`,
    ``,
    `/** Ability "${ab.name.replace(/\*\//g, "")}" of ${item.id}: ${t.type}. Generated by Cyrus from assets/designs/${item.id}.json (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends Ability {`,
    `    private static final String B = ${jstr(base)};`,
    ...[...new Set(g.statics)].map((s) => `    ${s}`),
    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
    ``,
    `    public ${cls}(Designer d) {`,
    `        super(d, ${jstr(item.id)}, ${jstr(ab.id)}, ${jstr(ab.name)}, Trigger.${TRIGGER_ENUM(t.type)});`,
    ...ctor.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    public void load(DesignConfig c) {`,
    ...load.map((l) => `        ${l}`),
    `    }`,
    ``,
    `    @Override`,
    `    protected boolean check(Activation a) {`,
    ...check.lines,
    `        return true;`,
    `    }`,
    ``,
    `    @Override`,
    `    protected void run(Activation a) {`,
    ...run.lines,
    `    }`,
    ``,
    `    @Override`,
    `    public void describe(List<String> out) {`,
    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
    `    }`,
    `}`,
    ``,
  ];
  void TRIGGER_HAS_TARGET;
  return { source: src.join("\n"), params };
}

function ingredientExpr(x: unknown, items: Map<string, string>): string {
  if (Array.isArray(x)) return `new RecipeChoice.MaterialChoice(${(x as string[]).map(MATERIAL).join(", ")})`;
  const s = x as string;
  if (/^[a-z][a-z0-9_]{1,31}$/.test(s)) return `designChoice(${jstr(s)})`;
  if (s.startsWith("#")) return `tagChoice(${jstr(bare(s.slice(1)))})`;
  void items;
  return `new RecipeChoice.MaterialChoice(${MATERIAL(s)})`;
}

function itemClass(pkg: string, d: ItemDesign, cls: string, abilityClasses: string[], ns: string, fe: DesignFeatures): { source: string; params: Param[] } {
  const params = itemParams(d);
  const base = `items.${d.id}.`;
  const body: string[] = [];
  const st = d.stats ?? {};
  body.push(`        ItemStack s = new ItemStack(${MATERIAL(d.base)});`);
  body.push(`        ItemMeta m = s.getItemMeta();`);
  body.push(`        if (m == null) return s;`);
  body.push(`        m.itemName(Component.text(${jstr(d.name.text)}, ${colorExpr(d.name.color)}));`);
  if (d.lore?.length) body.push(`        m.lore(List.of(${d.lore.map((l) => `Component.text(${jstr(l.text)}, ${l.color ? colorExpr(l.color) : "NamedTextColor.GRAY"}).decoration(TextDecoration.ITALIC, false)`).join(", ")}));`);
  if (d.rarity) body.push(`        m.setRarity(ItemRarity.${d.rarity.toUpperCase()});`);
  if (d.glint !== undefined) body.push(`        m.setEnchantmentGlintOverride(${d.glint});`);
  if (d.assets?.model) { const [mns, mkey] = d.assets.model.split(":"); body.push(`        Compat.itemModel(m, ${jstr(mns)}, ${jstr(mkey)});`); }
  if (st.damage !== undefined && st.attackSpeed !== undefined) {
    body.push(`        m.addAttributeModifier(Compat.ATTACK_DAMAGE, new AttributeModifier(new NamespacedKey(d.namespace(), ${jstr(`${d.id}_damage`)}), ${jnum(+(st.damage - 1).toFixed(4))}, AttributeModifier.Operation.ADD_NUMBER, EquipmentSlotGroup.MAINHAND));`);
    body.push(`        m.addAttributeModifier(Compat.ATTACK_SPEED, new AttributeModifier(new NamespacedKey(d.namespace(), ${jstr(`${d.id}_speed`)}), ${jnum(+(st.attackSpeed - 4).toFixed(4))}, AttributeModifier.Operation.ADD_NUMBER, EquipmentSlotGroup.MAINHAND));`);
  }
  if (st.unbreakable) body.push(`        m.setUnbreakable(true);`);
  if (st.durability !== undefined && !st.unbreakable) { body.push(`        m.setMaxStackSize(1);`); body.push(`        if (m instanceof Damageable dm) dm.setMaxDamage(${st.durability});`); }
  body.push(`        d.identity().tag(m, ID);`);
  body.push(`        s.setItemMeta(m);`);
  body.push(`        return s;`);

  const recipe: string[] = [];
  if (d.recipe) {
    const r = d.recipe;
    const count = r.count ?? 1;
    recipe.push(`    @Override`, `    public List<Recipe> recipes() {`, `        ItemStack result = create();`, `        result.setAmount(Math.max(1, Math.min(result.getMaxStackSize(), ${count})));`);
    if (r.kind === "shaped") {
      recipe.push(`        ShapedRecipe r = new ShapedRecipe(new NamespacedKey(d.namespace(), ID), result);`);
      recipe.push(`        r.shape(${r.pattern.map(jstr).join(", ")});`);
      for (const k of Object.keys(r.key).sort()) recipe.push(`        RecipeChoice c${k.charCodeAt(0)} = ${ingredientExpr(r.key[k], new Map())};`, `        if (c${k.charCodeAt(0)} == null) return List.of();`, `        r.setIngredient('${k === "'" ? "\\'" : k === "\\" ? "\\\\" : k}', c${k.charCodeAt(0)});`);
    } else {
      recipe.push(`        ShapelessRecipe r = new ShapelessRecipe(new NamespacedKey(d.namespace(), ID), result);`);
      r.ingredients.forEach((x, i) => recipe.push(`        RecipeChoice c${i} = ${ingredientExpr(x, new Map())};`, `        if (c${i} == null) return List.of();`, `        r.addIngredient(c${i});`));
    }
    if (r.category) recipe.push(`        r.setCategory(CraftingBookCategory.${r.category.toUpperCase()});`);
    recipe.push(`        return List.of(r);`, `    }`, ``,
      `    private RecipeChoice designChoice(String id) { DesignItem i = d.item(id); return i == null ? null : new RecipeChoice.ExactChoice(i.create()); }`, ``,
      `    private static RecipeChoice tagChoice(String key) { Tag<Material> t = Bukkit.getTag(Tag.REGISTRY_ITEMS, NamespacedKey.minecraft(key), Material.class); return t == null ? null : new RecipeChoice.MaterialChoice(t); }`, ``);
  }
  const load = params.map((p) => loadLine(p, p.path.slice(base.length)));
  for (const mk of d.marks ?? []) load.push(`mark(${jstr(mk.name)}, p_marks_${mk.name}_duration_ticks, p_marks_${mk.name}_max_per_owner, ${!!mk.glow});`);
  const passives: string[] = [];
  if (d.passives?.length) {
    passives.push(`    @Override`, `    public boolean hasPassives() { return true; }`, ``, `    @Override`, `    public void passives(Player p, boolean mainHand, boolean offHand) {`);
    d.passives.forEach((ps, i) => {
      const cond = ps.slot === "main_hand" ? "mainHand" : ps.slot === "off_hand" ? "offHand" : "mainHand || offHand";
      passives.push(`        if (${cond}) p.addPotionEffect(new PotionEffect(PotionEffectType.${ps.effect.toUpperCase()}, 60, p_passives_p${i}_amplifier, true, false, true));`);
    });
    passives.push(`    }`, ``);
  }
  const loot: string[] = [];
  if (d.acquisition?.loot?.length) {
    loot.push(`    @Override`, `    public void loot(String table, List<ItemStack> loot, Random random) {`);
    d.acquisition.loot.forEach((l, i) => loot.push(`        if (table.equals(${jstr(l.table)}) && random.nextDouble() < p_loot_l${i}_chance) loot.add(create());`));
    loot.push(`    }`, ``);
  }
  if (d.acquisition?.drops?.length) {
    loot.push(`    @Override`, `    public void drops(String entityType, List<ItemStack> drops, Random random) {`);
    d.acquisition.drops.forEach((l, i) => loot.push(`        if (entityType.equals(${jstr(bare(l.entity))}) && random.nextDouble() < p_drops_d${i}_chance) drops.add(create());`));
    loot.push(`    }`, ``);
  }
  const src = [
    `package ${pkg}.items;`,
    ``,
    `import java.util.List;`,
    `import java.util.Random;`,
    `import net.kyori.adventure.text.Component;`,
    `import net.kyori.adventure.text.format.NamedTextColor;`,
    `import net.kyori.adventure.text.format.TextColor;`,
    `import net.kyori.adventure.text.format.TextDecoration;`,
    `import org.bukkit.Bukkit;`,
    `import org.bukkit.Material;`,
    `import org.bukkit.NamespacedKey;`,
    `import org.bukkit.Tag;`,
    `import org.bukkit.attribute.AttributeModifier;`,
    `import org.bukkit.entity.Player;`,
    `import org.bukkit.inventory.EquipmentSlotGroup;`,
    `import org.bukkit.inventory.ItemRarity;`,
    `import org.bukkit.inventory.ItemStack;`,
    `import org.bukkit.inventory.Recipe;`,
    `import org.bukkit.inventory.RecipeChoice;`,
    `import org.bukkit.inventory.ShapedRecipe;`,
    `import org.bukkit.inventory.ShapelessRecipe;`,
    `import org.bukkit.inventory.recipe.CraftingBookCategory;`,
    `import org.bukkit.inventory.meta.Damageable;`,
    `import org.bukkit.inventory.meta.ItemMeta;`,
    `import org.bukkit.potion.PotionEffect;`,
    `import org.bukkit.potion.PotionEffectType;`,
    `import ${pkg}.abilities.*;`,
    `import ${pkg}.designer.Compat;`,
    `import ${pkg}.designer.DesignConfig;`,
    `import ${pkg}.designer.DesignItem;`,
    `import ${pkg}.designer.Designer;`,
    ``,
    `/** Design item ${ns}:${d.id} (${bare(d.base)}). Generated by Cyrus from assets/designs/${d.id}.json for Minecraft ${fe.version} (do not edit). Parameters: config.yml ${base.slice(0, -1)}. */`,
    `public final class ${cls} extends DesignItem {`,
    `    public static final String ID = ${jstr(d.id)};`,
    `    private static final String B = ${jstr(base)};`,
    ...params.map((p) => `    private ${JTYPE[p.kind]} ${p.field};`),
    ``,
    `    public ${cls}(Designer d) {`,
    `        super(d, ID);`,
    ...abilityClasses.map((c) => `        add(new ${c}(d));`),
    `    }`,
    ``,
    `    @Override`,
    `    public ItemStack create() {`,
    ...body,
    `    }`,
    ``,
    ...recipe,
    `    @Override`,
    `    protected void loadItem(DesignConfig c) {`,
    ...load.map((l) => `        ${l}`),
    `    }`,
    ``,
    ...passives,
    ...loot,
    `    @Override`,
    `    protected void describeItem(List<String> out) {`,
    ...params.map((p) => `        out.add(B + ${jstr(p.path.slice(base.length))} + "=" + ${p.field});`),
    `    }`,
    `}`,
    ``,
  ];
  return { source: src.join("\n"), params };
}

function mainClass(pkg: string, main: string, ns: string, command: string, itemClasses: string[], ids: string[], hooks: boolean): string {
  return [
    `package ${pkg};`,
    ``,
    `import java.util.List;`,
    `import org.bukkit.plugin.java.JavaPlugin;`,
    `import ${pkg}.designer.Designer;`,
    `import ${pkg}.items.*;`,
    ``,
    `/** Main class. Generated by Cyrus from the item designs (do not edit; custom code goes in the custom package). */`,
    `public class ${main} extends JavaPlugin {`,
    `    private Designer designer;`,
    ``,
    `    @Override`,
    `    public void onEnable() {`,
    `        designer = new Designer(this, ${jstr(ns)});`,
    `        designer.enable(getCommand(${jstr(command)}), List.of(${itemClasses.map((c) => `new ${c}(designer)`).join(", ")}));`,
    ...(hooks ? [`        ${pkg}.custom.CustomHooks.enable(this);`] : []),
    `        getLogger().info(${jstr(`Designer items ready: ${ids.join(", ")}`)});`,
    `    }`,
    ``,
    `    @Override`,
    `    public void onDisable() {`,
    ...(hooks ? [`        ${pkg}.custom.CustomHooks.disable();`] : []),
    `        if (designer != null) designer.disable();`,
    `        designer = null;`,
    `    }`,
    `}`,
    ``,
  ].join("\n");
}

// ----------------------------------------------------------------------------------------------- resources + README
function yamlTree(params: Param[]): string[] {
  type Node = { children: Map<string, Node>; param?: Param };
  const root: Node = { children: new Map() };
  for (const p of params) {
    let n = root;
    for (const seg of p.path.split(".")) { if (!n.children.has(seg)) n.children.set(seg, { children: new Map() }); n = n.children.get(seg)!; }
    n.param = p;
  }
  const out: string[] = [];
  const walk = (n: Node, ind: number) => {
    for (const [k, c] of n.children) {
      const pad = "  ".repeat(ind);
      if (c.param) {
        const p = c.param;
        const range = p.kind === "text" ? `text, max ${p.max} characters` : p.kind === "sound" ? "namespaced sound key" : `${fmtNum(p.min, p.kind)} to ${fmtNum(p.max, p.kind)}`;
        out.push(`${pad}# ${p.label} (${range})`);
        out.push(`${pad}${k}: ${p.kind === "text" || p.kind === "sound" ? ystr(String(p.value)) : fmtNum(Number(p.value), p.kind)}`);
      } else { out.push(`${pad}${k}:`); walk(c, ind + 1); }
    }
  };
  walk(root, 0);
  return out;
}

/** Hash of the designer values (the defaults Cyrus manages): config_version moves when it changes. */
export const designerValuesHash = (params: Param[]) => sha256(params.map((p) => `${p.path}=${p.kind === "text" || p.kind === "sound" ? String(p.value) : fmtNum(Number(p.value), p.kind)}`).join("\n")).slice(0, 16);

export function nextConfigVersion(previous: string | undefined, valuesHash: string): number {
  if (!previous) return 1;
  const v = /^config_version:\s*(\d+)\s*$/m.exec(previous);
  const h = /^# designer-values: ([0-9a-f]{16})\s*$/m.exec(previous);
  const prev = v ? Math.max(1, Math.min(1_000_000, Number(v[1]))) : 1;
  return h && h[1] === valuesHash ? prev : prev + 1;
}

function configYml(name: string, command: string, params: Param[], version: number, valuesHash: string, seed: number): string {
  return [
    `# ${name} configuration (generated by Cyrus from the item designs).`,
    `# Values under "items" are the designs' parameters: change them here and run /${command} reload.`,
    `# Every value is checked when it is loaded: numbers are clamped to the range in their comment.`,
    `# When the mod is updated with new designer values, config_version goes up and those values are re-applied`,
    `# (your previous file is kept as config.yml.bak-v<N>). The "general" section is never overwritten.`,
    `# designer-values: ${valuesHash}`,
    `config_version: ${version}`,
    `general:`,
    `  # Seed of the random_chance conditions (java.util.Random)`,
    `  random_seed: ${seed}`,
    ...yamlTree(params),
    ``,
  ].join("\n");
}

function pluginYml(name: string, main: string, version: string, mc: string, description: string, command: string, ns: string, designs: ItemDesign[]): string {
  const perms = designs.flatMap((d) => d.permissions ?? []).filter((p, i, a) => a.findIndex((x) => x.node === p.node) === i).sort((a, b) => (a.node < b.node ? -1 : 1));
  return [
    `name: ${name}`,
    `version: ${ystr(version)}`,
    `main: ${main}`,
    `api-version: ${ystr(mc)}`,
    `description: ${ystr(description)}`,
    `author: Nxeon Mod Builder`,
    `commands:`,
    `  ${command}:`,
    `    description: ${ystr(`${name} items: give, list, params, reload`)}`,
    `    usage: ${ystr(`/${command} <give|list|params|reload>`)}`,
    `    permission: ${ns}.command`,
    `permissions:`,
    `  ${ns}.command:`,
    `    description: ${ystr(`Use /${command} list and params`)}`,
    `    default: op`,
    `  ${ns}.give:`,
    `    description: ${ystr(`Give ${name} items with /${command} give`)}`,
    `    default: op`,
    `  ${ns}.reload:`,
    `    description: ${ystr(`Reload ${name}'s config.yml`)}`,
    `    default: op`,
    ...perms.flatMap((p) => [`  ${ns}.${p.node}:`, `    description: ${ystr(p.description)}`, `    default: ${p.default}`]),
    ``,
  ].join("\n");
}

const TRIGGER_WORDS: Record<string, string> = {
  right_click: "Right-click", left_click_hit_entity: "Hit a mob or player", sneak_right_click: "Sneak + right-click", kill_entity: "Kill a mob or player",
  projectile_hit: "When its projectile hits", held_interval: "While held", join: "When you join carrying it", death: "When you die carrying it", item_consume: "Eat/drink it", charge_release: "Hold sneak to charge, then release",
};
const secs = (t: number) => `${+(t / 20).toFixed(2)} s`;

function readme(name: string, command: string, ns: string, designs: ItemDesign[], params: Param[], fe: DesignFeatures, notes: string[]): string {
  const lines: string[] = [`# ${name}`, ``, `Custom items made with the Cyrus Item Designer for Minecraft ${fe.version}.`, ``];
  for (const d of designs) {
    lines.push(`## ${d.name.text}`, ``, `Based on ${bare(d.base).replace(/_/g, " ")}${d.rarity ? `, ${d.rarity}` : ""}. Get it with \`/${command} give ${d.id}\`${d.recipe ? " or craft it" : ""}.`);
    if (d.lore?.length) lines.push(``, ...d.lore.map((l) => `> ${l.text}`));
    if (d.stats?.damage !== undefined) lines.push(``, `Attack damage ${d.stats.damage}, attack speed ${d.stats.attackSpeed}.`);
    if (d.stats?.durability !== undefined && !d.stats.unbreakable) lines.push(`Durability ${d.stats.durability}.`);
    if (d.stats?.unbreakable) lines.push(`Unbreakable.`);
    for (const ab of d.abilities) {
      const p = params.filter((x) => x.item === d.id && x.ability === ab.id);
      const cd = p.find((x) => x.path.endsWith(".cooldown_ticks"));
      const ch = p.find((x) => x.path.endsWith(".charges.max"));
      const tr = ab.trigger.type === "charge_release" ? `${TRIGGER_WORDS.charge_release} (${ab.trigger.release === "right_click" ? "right-click while sneaking" : "stop sneaking"})` : TRIGGER_WORDS[ab.trigger.type];
      lines.push(``, `- **${ab.name}**: ${tr}.${cd && Number(cd.value) > 0 ? ` Cooldown ${secs(Number(cd.value))}.` : ""}${ch ? ` ${ch.value} charges.` : ""}`);
    }
    for (const ps of d.passives ?? []) lines.push(`- Passive: ${ps.effect.replace(/_/g, " ")} while held (${ps.slot.replace("_", " ")}).`);
    if (d.recipe) {
      const r = d.recipe;
      const show = (x: unknown) => (Array.isArray(x) ? (x as string[]).map(bare).join(" or ") : bare(String(x)));
      lines.push(``, r.kind === "shaped" ? `Recipe (crafting table): ${r.pattern.map((row) => `\`${row.replace(/ /g, "·")}\``).join(" / ")} with ${Object.keys(r.key).sort().map((k) => `${k} = ${show(r.key[k])}`).join(", ")}.` : `Recipe (shapeless): ${r.ingredients.map(show).join(" + ")}.`);
    }
    for (const l of d.acquisition?.loot ?? []) lines.push(`Found in ${l.table} loot (${Math.round(l.chance * 1000) / 10}% per roll).`);
    for (const l of d.acquisition?.drops ?? []) lines.push(`Dropped by ${bare(l.entity)} (${Math.round(l.chance * 1000) / 10}%).`);
    lines.push(``);
  }
  lines.push(`## Settings (config.yml)`, ``, `Change any of these in plugins/${name}/config.yml and run \`/${command} reload\` (values are clamped to the range shown):`, ``);
  for (const p of params) lines.push(`- \`${p.path}\` = ${p.kind === "text" || p.kind === "sound" ? `"${p.value}"` : fmtNum(Number(p.value), p.kind)}: ${p.label}${p.kind === "text" || p.kind === "sound" ? "" : ` (${fmtNum(p.min, p.kind)}-${fmtNum(p.max, p.kind)})`}`);
  lines.push(``, `## Commands and permissions`, ``, `- \`/${command} give <item> [player] [count]\` (${ns}.give, operators)`, `- \`/${command} list\`, \`/${command} params [item]\` (${ns}.command, operators)`, `- \`/${command} reload\` (${ns}.reload, operators)`);
  for (const d of designs) for (const p of d.permissions ?? []) lines.push(`- ${ns}.${p.node}: ${p.description} (default ${p.default})`);
  if (notes.length) lines.push(``, `## Good to know`, ``, ...notes.map((n) => `- ${n}`));
  lines.push(``);
  return lines.join("\n");
}

// ------------------------------------------------------------------------------------------------------------ main
export function compileDesigns(inputs: unknown[], ctx: CompileContext): CompileResult {
  const warnings: DzIssue[] = [];
  if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(ctx.pluginName)) return { ok: false, errors: [{ path: "pluginName", code: "bad_name", message: "the plugin name must be 2-40 letters, digits or _ starting with a letter" }], warnings };
  if (!inputs.length) return { ok: false, errors: [{ path: "(mod)", code: "no_designs", message: "no design items" }], warnings };
  const v = validateDesigns(inputs, { version: ctx.version, namespace: ctx.namespace, assets: ctx.assets });
  const errors: DzIssue[] = [...v.errors];
  v.results.forEach((r, i) => {
    const id = (inputs[i] as { id?: string })?.id ?? `#${i}`;
    for (const e of r.errors) errors.push({ ...e, path: `${id}: ${e.path}` });
    for (const w of r.warnings) warnings.push({ ...w, path: `${id}: ${w.path}` });
  });
  if (!v.ok || errors.length) return { ok: false, errors, warnings };
  const designs = v.results.map((r) => (r as Extract<typeof r, { ok: true }>).design).sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const fe = (v.results[0] as Extract<(typeof v.results)[number], { ok: true }>).features;
  const lower = ctx.pluginName.toLowerCase().replace(/_/g, "");
  const pkg = `dev.nxeon.plugins.${/^[a-z]/.test(lower) ? lower : `p${lower}`}`;
  const main = camel(ctx.pluginName.replace(/^[a-z]/, (c) => c.toUpperCase())) || "DesignerMod";
  const mainCls = /^[A-Z]/.test(main) ? main : `M${main}`;
  const command = ctx.pluginName.toLowerCase().slice(0, 32);
  // a vanilla command root would be shadowed (or shadow vanilla): refuse
  // (the vanilla command tree of this exact version, from the generated ids)
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { vanillaIds } = require("../datapack/versions") as typeof import("../datapack/versions");
  if (vanillaIds("command", ctx.version).has(command)) return { ok: false, errors: [{ path: "pluginName", code: "command_clash", message: `/${command} is a vanilla command in Minecraft ${ctx.version}; pick another plugin name` }], warnings };
  const classes = new Map<string, string>();
  const claim = (cls: string, what: string): string | null => { if (classes.has(cls)) return classes.get(cls)!; classes.set(cls, what); return null; };
  const files: CompiledFile[] = [];
  const dir = `src/main/java/${pkg.replace(/\./g, "/")}`;
  const add = (path: string, content: string, role: CompiledFile["role"]) => files.push({ path, content, sha256: sha256(content), role });
  for (const c of COMPONENTS) add(`${dir}/${c.file}`, renderComponent(c.source, pkg), "component");
  add(`${dir}/${COMPAT_META.file}`, renderComponent(compatSource(fe), pkg), "compat");
  const itemClasses: string[] = [];
  const params: Param[] = [];
  for (const d of designs) {
    const icls = `${camel(d.id)}Item`;
    const clash = claim(icls, d.id);
    if (clash) return { ok: false, errors: [{ path: d.id, code: "class_clash", message: `items ${clash} and ${d.id} map to the same Java class ${icls}; rename one` }], warnings };
    const abCls: string[] = [];
    for (const ab of d.abilities) {
      const acls = `${camel(d.id)}${camel(ab.id)}`;
      const c2 = claim(acls, `${d.id}.${ab.id}`);
      if (c2) return { ok: false, errors: [{ path: `${d.id}.${ab.id}`, code: "class_clash", message: `${c2} and ${d.id}.${ab.id} map to the same Java class ${acls}; rename one` }], warnings };
      const g = abilityClass(pkg, d, ab, acls, ctx.namespace);
      add(`${dir}/abilities/${acls}.java`, g.source, "generated");
      abCls.push(acls);
      params.push(...g.params);
    }
    const it = itemClass(pkg, d, icls, abCls, ctx.namespace, fe);
    add(`${dir}/items/${icls}.java`, it.source, "generated");
    itemClasses.push(icls);
    params.unshift(...[]);
    params.push(...it.params);
  }
  // config order = designParams order (item params first, then abilities), independent of the class emission order
  const ordered = designParams(designs);
  add(`${dir}/${mainCls}.java`, mainClass(pkg, mainCls, ctx.namespace, command, itemClasses, designs.map((d) => d.id), !!ctx.customHooks), "generated");
  const notes: string[] = [];
  if (!fe.itemModel && designs.some((d) => d.assets?.model)) notes.push(`Custom item models need Minecraft 1.21.4 or newer: on ${fe.version} the items keep their base look.`);
  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "charge_release")) notes.push(`${d.name.text}: charge by holding sneak with it in your main hand, then ${d.abilities.find((a) => a.trigger.type === "charge_release" && a.trigger.release === "unsneak") ? "let go of sneak" : "right-click while still sneaking"}.`);
  for (const d of designs) if (d.abilities.some((a) => a.trigger.type === "item_consume") && !(CONSUMABLE_BASES as readonly string[]).includes(bare(d.base))) notes.push(`${d.name.text} must be eaten to work.`);
  notes.push("Gameplay effects run on the server: protection plugins and PvP settings can block damage and teleports.");
  const valuesHash = designerValuesHash(ordered);
  const configVersion = nextConfigVersion(ctx.previousConfig, valuesHash);
  const seed = Number(BigInt.asUintN(31, BigInt("0x" + sha256(ctx.namespace).slice(0, 12))));
  add(`src/main/resources/config.yml`, configYml(ctx.pluginName, command, ordered, configVersion, valuesHash, seed), "resource");
  add(`src/main/resources/plugin.yml`, pluginYml(ctx.pluginName, `${pkg}.${mainCls}`, ctx.pluginVersion ?? "1.0.0", ctx.version, (ctx.description ?? `Custom items: ${designs.map((d) => d.name.text).join(", ")}`).slice(0, 200), command, ctx.namespace, designs), "resource");
  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  const rd = readme(ctx.pluginName, command, ctx.namespace, designs, ordered, fe, notes);
  const hash = sha256(files.map((f) => `${f.path}\n${f.sha256}`).join("\n") + `\nREADME\n${sha256(rd)}`);
  return {
    ok: true, files, readme: rd, readmeSha256: sha256(rd), hash, params: ordered, warnings, notes, pkg, mainClass: `${pkg}.${mainCls}`, command, configVersion, designerValuesHash: valuesHash,
    features: fe, javacVerified: (JAVAC_VERIFIED_VERSIONS as readonly string[]).includes(ctx.version), compiler: COMPILER_VERSION, library: COMPONENT_LIBRARY_VERSION, libraryHash: libraryHash(), designs,
  };
}

