// Cyrus R3 gameplay designers: the TS REFERENCE SIMULATOR of the ability graph semantics. It runs a design against a
// tiny world model and a scripted event list and logs every effect, so the logic (cooldowns, permissions, charges,
// branches, marks, budgets, the re-entry guard, delayed steps, seeded random) is tested without a game. It implements
// the SAME protocol as the Java components (Ability.fire, Charges, Marks, Budget, DesignListener dispatch, Targets) and
// reads parameter values through the same clamping rules as DesignConfig. It is a reference model, not the game:
// physics (velocity results), real collision/ray tracing, protection plugins and client behaviour are not simulated
// (velocities are logged, not integrated; ray-trace results come from the scenario).
import { BUDGET, CAPS, RUNTIME_CAPS, type Ability, type Action, type Condition, type ItemDesign } from "./spec";
import { designParams, DEFAULTS, randomSeedFor, type Param } from "./compile";

// ---------------------------------------------------------------------------------------- java.util.Random port
const MASK = (1n << 48n) - 1n;
export class JavaRandom {
  private seed: bigint;
  constructor(seed: number | bigint) { this.seed = (BigInt(seed) ^ 0x5deece66dn) & MASK; }
  private next(bits: number): number { this.seed = (this.seed * 0x5deece66dn + 0xbn) & MASK; return Number(this.seed >> BigInt(48 - bits)); }
  nextDouble(): number { return (this.next(26) * 2 ** 27 + this.next(27)) * 2 ** -53; }
}

// ------------------------------------------------------------------------------------------------------- world
export type Vec = [number, number, number];
export type SimEntity = {
  id: string; type: string; kind: "player" | "hostile" | "animal" | "other" | "armor_stand"; pos: Vec; health: number; maxHealth: number; world: string; alive: boolean;
  online?: boolean; permissions?: string[]; sneaking?: boolean; mainHand?: string | null; offHand?: string | null; inventory?: string[]; height?: number;
};
export type SimEvent =
  | { tick: number; type: "right_click"; player: string; clicked?: string; look?: { target?: string; point: Vec } }
  | { tick: number; type: "sneak_start" | "sneak_stop" | "switch_item" | "quit" | "join" | "consume" | "death"; player: string; look?: { target?: string; point: Vec } }
  | { tick: number; type: "hit" | "kill"; player: string; target: string }
  | { tick: number; type: "projectile_hit"; player: string; tag: string; item: string; target?: string; point: Vec }
  | { tick: number; type: "hold"; player: string; mainHand: string | null }
  | { tick: number; type: "advance" };
export type SimLog = { tick: number; ability: string; kind: string; subject?: string; detail?: Record<string, unknown> };
export type SimOptions = { namespace: string; config?: Record<string, number | string>; worldTime?: number; seed?: number };

type Budget = { actions: number; entities: number; tasks: number; particles: number; projectiles: number; exhausted: boolean };
type Act = { ab: SimAbility; player: SimEntity; target: SimEntity | null; point: Vec; charge: number; budget: Budget };
type SimAbility = { item: ItemDesign; ab: Ability; key: string; p: (rel: string) => number | string; cooldown: number; maxCharges: number; regen: number; range: number; minCharge: number; maxCharge: number };

const dist2 = (a: Vec, b: Vec) => (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2;

export class DesignSimulator {
  readonly log: SimLog[] = [];
  readonly entities = new Map<string, SimEntity>();
  tick = 0;
  worldTime: number;
  private readonly params: Map<string, Param>;
  private readonly config: Record<string, number | string>;
  private readonly abilities: SimAbility[] = [];
  private readonly cooldowns = new Map<string, Map<string, number>>();
  private readonly charges = new Map<string, Map<string, { count: number; last: number }>>();
  private readonly marks = new Map<string, Map<string, number>>(); // owner|mark -> target -> until
  private marksTotal = 0;
  private readonly active = new Set<string>();
  private readonly chargeStart = new Map<string, number>();
  private readonly lastClick = new Map<string, number>();
  private readonly tasks: { at: number; run: () => void }[] = [];
  private readonly projectiles: { owner: string; item: string; tag: string }[] = [];
  private random: JavaRandom;
  readonly notes: string[] = [];

  constructor(readonly designs: ItemDesign[], readonly opts: SimOptions) {
    this.params = new Map(designParams(designs).map((p) => [p.path, p]));
    this.config = opts.config ?? {};
    this.worldTime = opts.worldTime ?? 6000;
    this.random = new JavaRandom(opts.seed ?? randomSeedFor(opts.namespace));
    for (const item of designs) for (const ab of item.abilities) {
      const base = `items.${item.id}.abilities.${ab.id}.`;
      const p = (rel: string) => this.value(base + rel);
      const t = ab.trigger;
      this.abilities.push({
        item, ab, key: `${item.id}.${ab.id}`, p,
        cooldown: ab.cooldownTicks !== undefined ? Number(p("cooldown_ticks")) : 0,
        maxCharges: ab.charges ? Number(p("charges.max")) : 0,
        regen: ab.charges ? Number(p("charges.regen_ticks")) : 20,
        range: "targetRange" in t && t.targetRange !== undefined ? Number(p("trigger.target_range")) : 0,
        minCharge: t.type === "charge_release" ? Number(p("trigger.min_charge_ticks")) : 0,
        maxCharge: t.type === "charge_release" ? Math.max(Number(p("trigger.min_charge_ticks")), Number(p("trigger.max_charge_ticks"))) : 1,
      });
    }
  }

  /** A parameter value as DesignConfig would load it: the override (config) clamped to the caps, else the design default. */
  value(path: string): number | string {
    const p = this.params.get(path);
    if (!p) throw new Error(`no parameter ${path}`);
    const raw = this.config[path];
    if (p.kind === "text") { const s = String(raw ?? p.value).replace(/[\u0000-\u001f\u00a7]/g, ""); return s.slice(0, p.max); }
    if (p.kind === "sound") { const s = String(raw ?? ""); return /^[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(s) && s.length <= 100 ? s : String(p.value); }
    let v = typeof raw === "number" && Number.isFinite(raw) ? raw : Number(p.value);
    if (v < p.min || v > p.max) { const c = Math.max(p.min, Math.min(p.max, v)); this.notes.push(`clamped ${path} ${v} -> ${c}`); v = c; }
    return p.kind === "num" ? v : Math.round(v);
  }

  add(e: SimEntity): SimEntity { this.entities.set(e.id, { online: true, height: 1.8, ...e }); return this.entities.get(e.id)!; }
  private ent(id?: string | null) { return id ? this.entities.get(id) ?? null : null; }
  private say(ab: SimAbility | null, kind: string, subject?: string, detail?: Record<string, unknown>) { this.log.push({ tick: this.tick, ability: ab?.key ?? "-", kind, ...(subject ? { subject } : {}), ...(detail ? { detail } : {}) }); }
  private item(id: string) { return this.designs.find((d) => d.id === id) ?? null; }
  private abilitiesOf(itemId: string | null | undefined, trigger: string) { return this.abilities.filter((a) => a.item.id === itemId && a.ab.trigger.type === trigger); }

  // ------------------------------------------------------------------------------------------ components (twins)
  private cdReady(player: string, key: string) { const t = this.cooldowns.get(player)?.get(key); return t === undefined || t <= this.tick; }
  private cdRemaining(player: string, key: string) { const t = this.cooldowns.get(player)?.get(key); return t === undefined ? 0 : Math.max(0, t - this.tick); }
  private cdSet(player: string, key: string, ticks: number) { if (ticks > 0) { if (!this.cooldowns.has(player)) this.cooldowns.set(player, new Map()); this.cooldowns.get(player)!.set(key, this.tick + ticks); } }
  private chState(player: string, key: string, max: number) {
    if (!this.charges.has(player)) this.charges.set(player, new Map());
    const m = this.charges.get(player)!;
    if (!m.has(key)) m.set(key, { count: max, last: this.tick });
    return m.get(key)!;
  }
  private chRegen(s: { count: number; last: number }, max: number, period: number) {
    if (s.count >= max) { s.count = max; s.last = this.tick; return; }
    const gained = period <= 0 ? 0 : Math.floor((this.tick - s.last) / period);
    if (gained > 0) { s.count = Math.min(max, s.count + gained); s.last = s.count >= max ? this.tick : s.last + gained * period; }
  }
  chargesLeft(player: string, a: SimAbility) { if (a.maxCharges <= 0) return 0; const s = this.chState(player, a.key, a.maxCharges); this.chRegen(s, a.maxCharges, a.regen); return s.count; }
  private spend(player: string, a: SimAbility, n: number) { if (a.maxCharges <= 0) return false; const s = this.chState(player, a.key, a.maxCharges); this.chRegen(s, a.maxCharges, a.regen); if (s.count < n) return false; s.count -= n; return true; }
  private markApply(owner: string, target: string, mark: string, duration: number, maxPerOwner: number) {
    const k = `${owner}|${mark}`;
    if (!this.marks.has(k)) this.marks.set(k, new Map());
    const m = this.marks.get(k)!;
    this.prune(m);
    if (m.delete(target)) this.marksTotal--;
    while (m.size >= Math.max(1, maxPerOwner)) { const first = m.keys().next().value as string; m.delete(first); this.marksTotal--; }
    if (this.marksTotal >= RUNTIME_CAPS.marksTotal) return false;
    m.set(target, this.tick + duration); this.marksTotal++;
    return true;
  }
  private prune(m: Map<string, number>) { for (const [t, u] of [...m]) if (u <= this.tick) { m.delete(t); this.marksTotal--; } }
  marked(owner: string, mark: string, center: Vec, radius: number, max: number): SimEntity[] {
    const m = this.marks.get(`${owner}|${mark}`);
    if (!m) return [];
    this.prune(m);
    const out = [...m.keys()].map((id) => this.ent(id)).filter((e): e is SimEntity => !!e && e.alive && dist2(e.pos, center) <= radius * radius);
    out.sort((a, b) => dist2(a.pos, center) - dist2(b.pos, center) || (a.id < b.id ? -1 : 1));
    return out.slice(0, max);
  }
  hasMark(owner: string, mark: string, target: string) { const u = this.marks.get(`${owner}|${mark}`)?.get(target); return u !== undefined && u > this.tick; }
  private forget(id: string) { this.cooldowns.delete(id); this.charges.delete(id); for (const k of [...this.marks.keys()]) if (k.startsWith(`${id}|`)) { this.marksTotal -= this.marks.get(k)!.size; this.marks.delete(k); } this.chargeStart.delete(id); this.lastClick.delete(id); this.active.delete(id); }
  private removeTarget(id: string) { for (const m of this.marks.values()) if (m.delete(id)) this.marksTotal--; }
  private budget(): Budget { return { actions: 0, entities: 0, tasks: 0, particles: 0, projectiles: 0, exhausted: false }; }
  private take(b: Budget, k: "actions" | "entities" | "tasks" | "projectiles") { if (b[k] >= BUDGET[k]) { b.exhausted = true; return false; } b[k]++; return true; }

  // ------------------------------------------------------------------------------------------------- protocol
  private activation(ab: SimAbility, player: SimEntity, target: SimEntity | null, point: Vec | null, charge: number): Act {
    return { ab, player, target, point: point ?? [...player.pos], charge: Math.max(0, Math.min(1, charge)), budget: this.budget() };
  }
  /** Ability.fire */
  fire(a: Act): boolean {
    const p = a.player, ab = a.ab;
    if (!p.online || !p.alive || this.active.has(p.id)) return false;
    this.active.add(p.id);
    try {
      if (!ab.ab.manualCooldown && ab.cooldown > 0 && !this.cdReady(p.id, ab.key)) { if (ab.ab.feedback) this.say(ab, "feedback", p.id, { text: `${ab.ab.name}: ${(this.cdRemaining(p.id, ab.key) / 20).toFixed(1)}s` }); this.say(ab, "blocked", p.id, { by: "cooldown" }); return false; }
      if (!ab.ab.manualCharges && ab.maxCharges > 0 && this.chargesLeft(p.id, ab) < 1) { if (ab.ab.feedback) this.say(ab, "feedback", p.id, { text: `${ab.ab.name}: no charges` }); this.say(ab, "blocked", p.id, { by: "charges" }); return false; }
      for (const [i, c] of (ab.ab.conditions ?? []).entries()) if (!this.cond(a, c, `c${i}`)) { this.say(ab, "blocked", p.id, { by: `condition ${c.type}` }); return false; }
      if (!ab.ab.manualCooldown && ab.cooldown > 0) this.cdSet(p.id, ab.key, ab.cooldown);
      if (!ab.ab.manualCharges && ab.maxCharges > 0) this.spend(p.id, ab, 1);
      this.say(ab, "fired", p.id, { target: a.target?.id ?? null, charge: a.charge });
      this.run(a, ab.ab.actions, "");
      return true;
    } finally { this.active.delete(p.id); }
  }

  private other(a: Act, id?: string) { return !id || id === a.ab.ab.id ? a.ab : this.abilities.find((x) => x.item.id === a.ab.item.id && x.ab.id === id) ?? null; }
  private targetIs(e: SimEntity | null, kinds: string[] | undefined, types: string[] | undefined) {
    if (!e || !e.alive) return false;
    const living = e.kind !== "other" && e.kind !== "armor_stand";
    if (kinds?.length && living && (kinds.includes("living") || kinds.includes(e.kind))) return true;
    return !!types?.length && types.map((t) => t.replace(/^minecraft:/, "")).includes(e.type);
  }

  private cond(a: Act, c: Condition, rel: string): boolean {
    const P = (k: string) => Number(a.ab.p(`${rel}.${k}`));
    const neg = (x: boolean) => (c.negate ? !x : x);
    switch (c.type) {
      case "cooldown_ready": { const o = this.other(a, c.ability); return neg(!o || this.cdReady(a.player.id, o.key)); }
      case "has_permission": return neg((a.player.permissions ?? []).includes(`${this.opts.namespace}.${c.node}`));
      case "target_is": { const t = a.target && a.target.alive ? a.target : null; if (!t) return false; const r = this.targetIs(t, c.kinds, c.types); return c.negate ? !r : r; }
      case "world_in": return neg(c.worlds.includes(a.player.world));
      case "health_below": case "health_above": {
        const s = c.subject === "self" ? a.player : a.target && a.target.alive ? a.target : null;
        if (!s) return false;
        const f = s.maxHealth <= 0 ? 0 : s.health / s.maxHealth;
        return neg(c.type === "health_below" ? f < P("fraction") : f > P("fraction"));
      }
      case "item_identity": return neg((c.slot === "main_hand" ? a.player.mainHand : a.player.offHand) === c.item);
      case "sneaking": return neg(!!a.player.sneaking);
      case "charges_available": { const o = this.other(a, c.ability); return neg(!!o && this.chargesLeft(a.player.id, o) >= P("amount")); }
      case "random_chance": return neg(this.random.nextDouble() < P("chance"));
      case "time_of_day": { const t = ((this.worldTime % 24000) + 24000) % 24000, f = P("from"), to = P("to"); return neg(f <= to ? t >= f && t <= to : t >= f || t <= to); }
    }
  }

  private run(a: Act, list: Action[], prefix: string): boolean {
    for (const [i, x] of list.entries()) {
      const rel = prefix ? `${prefix}${i}` : `a${i}`;
      if (!this.take(a.budget, "actions")) { this.say(a.ab, "budget_exhausted", a.player.id, { at: rel }); return false; }
      if (!this.act(a, x, rel)) return false;
    }
    return true;
  }

  private act(a: Act, x: Action, rel: string): boolean {
    const P = (k: string) => a.ab.p(`${rel}.${k}`);
    const N = (k: string) => Number(P(k));
    const subj = (t: string | undefined, dflt: "self" | "target") => ((t ?? dflt) === "self" ? a.player : a.target && a.target.alive ? a.target : null);
    const where = (w?: string): Vec | null => (w === "target" ? (a.target && a.target.alive ? [a.target.pos[0], a.target.pos[1] + (a.target.height ?? 1.8) / 2, a.target.pos[2]] : null) : w === "point" ? a.point : [a.player.pos[0], a.player.pos[1] + 1, a.player.pos[2]]);
    const scale = (b?: boolean) => (b ? a.charge : 1);
    const ent = (e: SimEntity | null) => !!e && e.alive && this.take(a.budget, "entities");
    switch (x.type) {
      case "damage": { const t = subj(x.target, "target"); const amt = N("amount") * scale(x.scaleWithCharge); if (!t || !t.alive || amt <= 0 || !ent(t)) break; t.health -= amt; this.say(a.ab, "damage", t.id, { amount: amt }); if (t.health <= 0) { t.health = 0; t.alive = false; this.removeTarget(t.id); this.say(a.ab, "died", t.id); } break; }
      case "heal": { const t = subj(x.target, "self"); const amt = N("amount") * scale(x.scaleWithCharge); if (!t || amt <= 0 || !ent(t)) break; t.health = Math.min(t.maxHealth, t.health + amt); this.say(a.ab, "heal", t.id, { amount: amt }); break; }
      case "potion_effect": { const t = subj(x.target, "self"); if (!t || !ent(t)) break; this.say(a.ab, "potion", t.id, { effect: x.effect, ticks: N("duration_ticks"), amplifier: N("amplifier") }); break; }
      case "knockback": case "pull_to": case "push_from": {
        const t = subj(x.target, "target");
        if (!t || !t.alive) break;
        let dir: Vec;
        if (x.type === "knockback") { if (t === a.player) break; dir = [t.pos[0] - a.player.pos[0], 0, t.pos[2] - a.player.pos[2]]; }
        else if (x.type === "pull_to") { const to = x.to === "self" ? a.player.pos : a.point; if (Math.sqrt(dist2(to, t.pos)) < 1) break; dir = [to[0] - t.pos[0], 0, to[2] - t.pos[2]]; }
        else { const from = x.from === "self" ? a.player.pos : a.point; dir = [t.pos[0] - from[0], 0, t.pos[2] - from[2]]; }
        if (!this.take(a.budget, "entities")) break;
        const len = Math.hypot(dir[0], dir[2]); const s = N("strength") * scale(x.scaleWithCharge);
        let v: Vec = len < 1e-2 ? [0, N("vertical"), 0] : [dir[0] / len * s, N("vertical"), dir[2] / len * s];
        const vl = Math.hypot(...v); if (vl > 4) v = v.map((c) => (c / vl) * 4) as Vec;
        this.say(a.ab, x.type, t.id, { velocity: v.map((c) => +c.toFixed(4)) });
        break;
      }
      case "teleport_short": this.say(a.ab, "teleport", a.player.id, { range: N("range") }); break;
      case "launch_projectile": { if (!this.take(a.budget, "projectiles")) break; this.projectiles.push({ owner: a.player.id, item: a.ab.item.id, tag: x.tag ?? "" }); this.say(a.ab, "launch", a.player.id, { kind: x.kind, speed: N("speed"), tag: x.tag ?? "" }); if (this.take(a.budget, "tasks")) this.schedule(N("lifetime_ticks"), () => {}); break; }
      case "spawn_particles": { const at = where(x.at); if (!at) break; const want = N("count"); const n = Math.max(0, Math.min(want, BUDGET.particles - a.budget.particles)); a.budget.particles += n; if (n < want) a.budget.exhausted = true; if (n > 0) this.say(a.ab, "particles", undefined, { particle: x.particle, count: n }); break; }
      case "play_sound": { const at = where(x.at); if (!at) break; this.say(a.ab, "sound", undefined, { key: P("sound"), volume: N("volume"), pitch: N("pitch") }); break; }
      case "send_message": case "actionbar": case "title": {
        const to = (x.to ?? "self") === "self" ? a.player : a.target;
        if (!to || to.kind !== "player" || !to.online) break;
        const fill = (s: string) => s.replace(/\{player\}/g, a.player.id).replace(/\{target\}/g, a.target?.id ?? "");
        this.say(a.ab, x.type, to.id, { text: fill(String(P(x.type === "title" ? "title" : "text"))) });
        break;
      }
      case "give_item": this.say(a.ab, "give", a.player.id, { item: x.item, count: N("count") }); break;
      case "set_cooldown": { const o = this.other(a, x.ability); if (o) this.cdSet(a.player.id, o.key, N("ticks")); break; }
      case "consume_charge": { const o = this.other(a, x.ability); if (o) this.spend(a.player.id, o, N("amount")); break; }
      case "apply_mark": {
        const t = a.target && a.target.alive ? a.target : null;
        const def = (a.ab.item.marks ?? []).find((m) => m.name === x.mark)!;
        const base = `items.${a.ab.item.id}.marks.${def.name}.`;
        if (!t || t === a.player || !this.take(a.budget, "entities")) break;
        if (this.markApply(a.player.id, t.id, `${a.ab.item.id}.${x.mark}`, Number(this.value(base + "duration_ticks")), Number(this.value(base + "max_per_owner")))) this.say(a.ab, "mark", t.id, { mark: x.mark });
        break;
      }
      case "query_marked": case "query_nearby": {
        const center = x.around === "point" ? a.point : a.player.pos;
        const r = N("radius"), max = N("max");
        let list: SimEntity[];
        if (x.type === "query_marked") list = this.marked(a.player.id, `${a.ab.item.id}.${x.mark}`, center, r, max);
        else {
          list = [...this.entities.values()].filter((e) => e !== a.player && e.alive && e.kind !== "other" && e.kind !== "armor_stand" && (e.kind !== "player" || !!x.includePlayers)
            && (!(x.kinds?.length || x.types?.length) || this.targetIs(e, x.kinds, x.types)) && dist2(e.pos, center) <= r * r);
          list.sort((p, q) => dist2(p.pos, center) - dist2(q.pos, center) || (p.id < q.id ? -1 : 1));
          list = list.slice(0, max);
        }
        this.say(a.ab, x.type, undefined, { found: list.map((e) => e.id) });
        for (const e of list) if (!this.run({ ...a, target: e }, x.actions, `${rel}.n`)) return false;
        break;
      }
      case "delayed": {
        if (!this.take(a.budget, "tasks")) break;
        this.schedule(N("delay_ticks"), () => {
          if (!a.player.online || !a.player.alive || this.active.has(a.player.id)) return;
          this.active.add(a.player.id);
          try { this.say(a.ab, "delayed_run", a.player.id); this.run(a, x.actions, `${rel}.n`); } finally { this.active.delete(a.player.id); }
        });
        break;
      }
      case "branch": {
        const ok = x.if.every((c, j) => this.cond(a, c, `${rel}.if${j}`));
        this.say(a.ab, "branch", undefined, { taken: ok ? "then" : x.else ? "else" : "none" });
        if (ok) return this.run(a, x.then, `${rel}.then`);
        if (x.else) return this.run(a, x.else, `${rel}.else`);
        break;
      }
    }
    return true;
  }

  private schedule(delay: number, run: () => void) { if (this.tasks.length < RUNTIME_CAPS.liveTasks) this.tasks.push({ at: this.tick + Math.max(1, delay), run }); }

  /** Advance time: run due tasks and held_interval timers (first run after one period, like runTaskTimer(p, p)). */
  advanceTo(tick: number) {
    while (this.tick < tick) {
      this.tick++;
      this.worldTime = (this.worldTime + 1) % 24000;
      for (const t of this.tasks.filter((x) => x.at === this.tick)) { this.tasks.splice(this.tasks.indexOf(t), 1); t.run(); }
      for (const a of this.abilities) if (a.ab.trigger.type === "held_interval") {
        const period = Math.max(10, Number(a.p("trigger.period_ticks")));
        if (this.tick % period !== 0) continue;
        for (const p of this.entities.values()) if (p.kind === "player" && p.online && p.alive) {
          const has = a.ab.trigger.slot === "inventory" ? (p.inventory ?? []).includes(a.item.id) || p.mainHand === a.item.id || p.offHand === a.item.id : p.mainHand === a.item.id;
          if (has) this.fire(this.activation(a, p, null, null, 0));
        }
      }
    }
  }

  private aim(a: SimAbility, p: SimEntity, clicked: SimEntity | null, look: { target?: string; point: Vec } | undefined, charge: number) {
    let target: SimEntity | null = null, point: Vec | null = null;
    if (a.range > 0) {
      if (clicked && clicked.kind !== "other" && Math.sqrt(dist2(clicked.pos, p.pos)) <= a.range + 1) { target = clicked; point = clicked.pos; }
      else if (look) { const t = this.ent(look.target); target = t && t.alive && Math.sqrt(dist2(t.pos, p.pos)) <= a.range + 1 ? t : null; point = look.point; }
    }
    this.fire(this.activation(a, p, target, point, charge));
  }
  private frac(a: SimAbility, held: number) { return Math.max(0, Math.min(1, held / Math.max(1, a.maxCharge))); }

  /** Feed one event (advances time to its tick first). */
  event(e: SimEvent) {
    this.advanceTo(e.tick);
    if (e.type === "advance") return;
    const p = this.ent(e.player);
    if (!p) throw new Error(`no entity ${e.player}`);
    switch (e.type) {
      case "hold": p.mainHand = e.mainHand; this.chargeStart.delete(p.id); break;
      case "switch_item": this.chargeStart.delete(p.id); break;
      case "right_click": {
        if (this.active.has(p.id)) return;
        const item = p.mainHand ?? null;
        if (!item || !this.item(item)) return;
        if (this.lastClick.get(p.id) === this.tick) return;
        this.lastClick.set(p.id, this.tick);
        const clicked = this.ent(e.clicked);
        if (p.sneaking) {
          let sneakAbility = false;
          const start = this.chargeStart.get(p.id);
          for (const a of this.abilitiesOf(item, "charge_release")) {
            if (a.ab.trigger.type !== "charge_release" || a.ab.trigger.release !== "right_click") continue;
            sneakAbility = true;
            if (start === undefined) continue;
            const held = this.tick - start;
            if (held < a.minCharge) { this.say(a, "blocked", p.id, { by: "not charged", held }); continue; }
            this.chargeStart.delete(p.id);
            this.aim(a, p, clicked, e.look, this.frac(a, held));
          }
          const sneak = this.abilitiesOf(item, "sneak_right_click");
          for (const a of sneak) this.aim(a, p, clicked, e.look, 0);
          if (sneakAbility || sneak.length) return;
        }
        for (const a of this.abilitiesOf(item, "right_click")) this.aim(a, p, clicked, e.look, 0);
        break;
      }
      case "sneak_start": p.sneaking = true; if (p.mainHand && this.abilitiesOf(p.mainHand, "charge_release").length) this.chargeStart.set(p.id, this.tick); else this.chargeStart.delete(p.id); break;
      case "sneak_stop": {
        p.sneaking = false;
        const start = this.chargeStart.get(p.id); this.chargeStart.delete(p.id);
        if (!p.mainHand || start === undefined || this.active.has(p.id)) break;
        const held = this.tick - start;
        for (const a of this.abilitiesOf(p.mainHand, "charge_release")) if (a.ab.trigger.type === "charge_release" && a.ab.trigger.release === "unsneak" && held >= a.minCharge) this.aim(a, p, null, e.look, this.frac(a, held));
        break;
      }
      case "hit": { const t = this.ent(e.target); if (!t || !t.alive || this.active.has(p.id)) break; for (const a of this.abilitiesOf(p.mainHand, "left_click_hit_entity")) this.fire(this.activation(a, p, t, t.pos, 0)); break; }
      case "kill": {
        const t = this.ent(e.target); if (!t) break;
        t.alive = false; t.health = 0;
        if (!this.active.has(p.id)) for (const a of this.abilitiesOf(p.mainHand, "kill_entity")) this.fire(this.activation(a, p, t, t.pos, 0));
        this.removeTarget(t.id);
        if (t.kind === "player") this.forget(t.id);
        break;
      }
      case "projectile_hit": {
        const i = this.projectiles.findIndex((x) => x.owner === p.id && x.tag === e.tag && x.item === e.item);
        if (i < 0) { this.notes.push(`no ${e.tag} projectile of ${p.id} in flight`); break; }
        this.projectiles.splice(i, 1);
        if (!p.online || this.active.has(p.id)) break;
        const t = this.ent(e.target);
        for (const a of this.abilitiesOf(e.item, "projectile_hit")) if (a.ab.trigger.type === "projectile_hit" && a.ab.trigger.tag === e.tag) this.fire(this.activation(a, p, t && t.alive && t !== p ? t : null, e.point, 0));
        break;
      }
      case "consume": { if (this.active.has(p.id) || !p.mainHand) break; for (const a of this.abilitiesOf(p.mainHand, "item_consume")) this.fire(this.activation(a, p, null, null, 0)); break; }
      case "join": { p.online = true; for (const d of this.designs) if ((p.inventory ?? []).includes(d.id) || p.mainHand === d.id) for (const a of this.abilitiesOf(d.id, "join")) this.fire(this.activation(a, p, null, null, 0)); break; }
      case "death": {
        for (const d of this.designs) if ((p.inventory ?? []).includes(d.id) || p.mainHand === d.id) for (const a of this.abilitiesOf(d.id, "death")) this.fire(this.activation(a, p, null, null, 0));
        p.alive = false; this.removeTarget(p.id); this.forget(p.id);
        break;
      }
      case "quit": p.online = false; this.forget(p.id); break;
    }
  }

  run_(events: SimEvent[]) { for (const e of [...events].sort((a, b) => a.tick - b.tick)) this.event(e); return this.log; }
  /** Effects of one kind (for assertions). */
  of(kind: string) { return this.log.filter((l) => l.kind === kind); }
}

export const SIM_DEFAULTS = DEFAULTS;
export const SIM_CAPS = CAPS;

