/** Ability "Void Pull" of void_reaper: charge_release. Generated by Cyrus from assets/designs/void_reaper.json (do not edit). Parameters: config.yml items.void_reaper.abilities.void_pull. */
public final class VoidReaperVoidPull extends Ability {
    private static final String B = "items.void_reaper.abilities.void_pull.";
    private long p_cooldown_ticks;
    private double p_trigger_target_range;
    private long p_trigger_min_charge_ticks;
    private long p_trigger_max_charge_ticks;
    private double p_a0_radius;
    private int p_a0_max;
    private double p_a0_n0_strength;
    private double p_a0_n0_vertical;
    private int p_a0_n1_count;
    private double p_a0_n1_spread;
    private double p_a0_n1_speed;
    private int p_a1_count;
    private double p_a1_spread;
    private double p_a1_speed;
    private String p_a2_sound;
    private double p_a2_volume;
    private double p_a2_pitch;
    private String p_a3_text;

    public VoidReaperVoidPull(Designer d) {
        super(d, "void_reaper", "void_pull", "Void Pull", Trigger.CHARGE_RELEASE);
        feedback = true;
        releaseOnRightClick = true;
    }

    @Override
    public void load(DesignConfig c) {
        p_cooldown_ticks = c.ticks(B + "cooldown_ticks", 0L, 72000L);
        p_trigger_target_range = c.num(B + "trigger.target_range", 1.0, 32.0);
        p_trigger_min_charge_ticks = c.ticks(B + "trigger.min_charge_ticks", 5L, 200L);
        p_trigger_max_charge_ticks = c.ticks(B + "trigger.max_charge_ticks", 10L, 400L);
        p_a0_radius = c.num(B + "a0.radius", 1.0, 32.0);
        p_a0_max = c.integer(B + "a0.max", 1, 16);
        p_a0_n0_strength = c.num(B + "a0.n0.strength", 0.0, 3.0);
        p_a0_n0_vertical = c.num(B + "a0.n0.vertical", 0.0, 1.5);
        p_a0_n1_count = c.integer(B + "a0.n1.count", 1, 64);
        p_a0_n1_spread = c.num(B + "a0.n1.spread", 0.0, 4.0);
        p_a0_n1_speed = c.num(B + "a0.n1.speed", 0.0, 1.0);
        p_a1_count = c.integer(B + "a1.count", 1, 64);
        p_a1_spread = c.num(B + "a1.spread", 0.0, 4.0);
        p_a1_speed = c.num(B + "a1.speed", 0.0, 1.0);
        p_a2_sound = c.soundKey(B + "a2.sound");
        p_a2_volume = c.num(B + "a2.volume", 0.0, 2.0);
        p_a2_pitch = c.num(B + "a2.pitch", 0.5, 2.0);
        p_a3_text = c.text(B + "a3.text", 120);
        cooldownTicks = p_cooldown_ticks;
        targetRange = p_trigger_target_range;
        minChargeTicks = p_trigger_min_charge_ticks;
        maxChargeTicks = Math.max(p_trigger_min_charge_ticks, p_trigger_max_charge_ticks);
    }

    @Override
    protected boolean check(Activation a) {
        return true;
    }

    @Override
    protected void run(Activation a) {
        // a0: query_marked
        if (!a.budget().action()) return;
        for (LivingEntity t1 : d.marks().marked(a.player().getUniqueId(), "void_reaper.void", a.player().getLocation(), p_a0_radius, p_a0_max, d.now())) {
            Activation a1 = a.withTarget(t1);
            // a0.n0: pull_to
            if (!a1.budget().action()) return;
            d.effects().pullTo(a1, a1.livingTarget(), a1.point(), p_a0_n0_strength * a1.charge(), p_a0_n0_vertical);
            // a0.n1: spawn_particles
            if (!a1.budget().action()) return;
            d.effects().particles(a1, d.effects().target(a1), Particle.PORTAL, p_a0_n1_count, p_a0_n1_spread, p_a0_n1_speed);
        }
        // a1: spawn_particles
        if (!a.budget().action()) return;
        d.effects().particles(a, d.effects().point(a), Particle.SONIC_BOOM, p_a1_count, p_a1_spread, p_a1_speed);
        // a2: play_sound
        if (!a.budget().action()) return;
        d.effects().sound(a, d.effects().point(a), p_a2_sound, (float) p_a2_volume, (float) p_a2_pitch);
        // a3: actionbar
        if (!a.budget().action()) return;
        d.effects().actionbar(a, a.player(), p_a3_text, NamedTextColor.LIGHT_PURPLE);
    }

    @Override
    public void describe(List<String> out) {
        out.add(B + "cooldown_ticks" + "=" + p_cooldown_ticks);
        out.add(B + "trigger.target_range" + "=" + p_trigger_target_range);
        out.add(B + "trigger.min_charge_ticks" + "=" + p_trigger_min_charge_ticks);
        out.add(B + "trigger.max_charge_ticks" + "=" + p_trigger_max_charge_ticks);
        out.add(B + "a0.radius" + "=" + p_a0_radius);
        out.add(B + "a0.max" + "=" + p_a0_max);
        out.add(B + "a0.n0.strength" + "=" + p_a0_n0_strength);
        out.add(B + "a0.n0.vertical" + "=" + p_a0_n0_vertical);
        out.add(B + "a0.n1.count" + "=" + p_a0_n1_count);
        out.add(B + "a0.n1.spread" + "=" + p_a0_n1_spread);
        out.add(B + "a0.n1.speed" + "=" + p_a0_n1_speed);
        out.add(B + "a1.count" + "=" + p_a1_count);
        out.add(B + "a1.spread" + "=" + p_a1_spread);
        out.add(B + "a1.speed" + "=" + p_a1_speed);
        out.add(B + "a2.sound" + "=" + p_a2_sound);
        out.add(B + "a2.volume" + "=" + p_a2_volume);
        out.add(B + "a2.pitch" + "=" + p_a2_pitch);
        out.add(B + "a3.text" + "=" + p_a3_text);
    }
}
