// Cyrus R3 gameplay designers, PORTAL side of a succeeded build: the service's designs are never trusted. Every returned
// design is validated and the whole mod is compiled AGAIN here with the TypeScript compiler for the build's exact
// version; the generated-source hash is compared with the one the service compiled into the jar (serviceAgreed). A design
// that fails is dropped with a reason. The sources are deterministic, so the portal stores only the designs.
import { compileDesigns, type CompileOk } from "./compile";
import { canonicalJson, validateDesign, type ItemDesign } from "./spec";
import { createHash } from "node:crypto";

export const DESIGN_SPEC_MIME = "application/vnd.nxeon.item-design+json";
export type SvcDesign = { name: string; path: string; sha256: string; spec: unknown };
export type SvcDesignCompile = { hash?: string; pluginName?: string; configVersion?: number } | null | undefined;
export type CheckedDesign = { name: string; design: ItemDesign; canonical: string; specSha256: string };
export type CheckedDesigns = { ok: CheckedDesign[]; dropped: { name: string; reason: string }[]; notices: string[]; compiled: CompileOk | null; serviceAgreed: boolean | null };

const sha = (s: string) => createHash("sha256").update(s).digest("hex");

export function checkReturnedDesigns(list: SvcDesign[] | undefined, ctx: { namespace: string; mcVersion: string; pluginName: string | null; compile?: SvcDesignCompile }): CheckedDesigns {
  const out: CheckedDesigns = { ok: [], dropped: [], notices: [], compiled: null, serviceAgreed: null };
  const all = (list ?? []).slice(0, 6);
  const keys = all.map((d) => (d?.spec as { id?: string } | null)?.id).filter((x): x is string => typeof x === "string");
  for (const d of all) {
    const name = typeof d?.name === "string" ? d.name.slice(0, 40) : "?";
    const v = validateDesign(d?.spec, { version: ctx.mcVersion, namespace: ctx.namespace, items: keys });
    if (!v.ok) { out.dropped.push({ name, reason: v.errors[0] ? `${v.errors[0].path}: ${v.errors[0].message}` : "failed the design checks" }); out.notices.push(`Item design "${name}" was left out: it did not pass Nxeon's design checks for Minecraft ${ctx.mcVersion}.`); continue; }
    if (v.design.id !== name || out.ok.some((x) => x.name === name)) { out.dropped.push({ name, reason: "name mismatch or duplicate" }); continue; }
    const canonical = canonicalJson(v.design);
    out.ok.push({ name, design: v.design, canonical, specSha256: sha(canonical) });
  }
  const pluginName = ctx.compile?.pluginName ?? ctx.pluginName;
  if (out.ok.length && pluginName) {
    const r = compileDesigns(out.ok.map((x) => x.design), { version: ctx.mcVersion, namespace: ctx.namespace, pluginName });
    if (r.ok) { out.compiled = r; out.serviceAgreed = ctx.compile?.hash ? ctx.compile.hash === r.hash && (ctx.compile.configVersion ?? 1) === r.configVersion : null; }
    else out.notices.push(`The item designs could not be compiled again on the portal (${r.errors[0]?.message ?? "error"}).`);
  }
  return out;
}
