// Cyrus R3 gameplay designers (pure): the design IR (schema, every cap, semantic checks, static budget), the JSON Schema
// file, the verified component library (present, strict-scan clean, precheck clean, version adapter), the compiler
// (determinism, golden hashes per version, per-version differences), the parameter-edit path (only config.yml + README
// change), the change-request parser, the TS reference simulator (cooldowns, charges, permissions, branches, marks,
// budgets, re-entry guard, delayed steps, seeded random), TS == generated service JS, the prompt section, routing,
// the build request and the portal sync.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { BUDGET, CAPS, DESIGN_LIMITS, designFeatures, designJsonSchema, validateDesign, validateDesigns, type CapName, type ItemDesign } from "../lib/cyrus/designer/spec";
import { compileDesigns, designParams, nextConfigVersion, JAVAC_VERIFIED_VERSIONS, type CompileOk } from "../lib/cyrus/designer/compile";
import { COMPONENTS, libraryHash } from "../lib/cyrus/designer/components";
import { applyParameterEdits, diffCompiled, planDesignEdit, recompileWithEdits } from "../lib/cyrus/designer/params";
import { DesignSimulator, JavaRandom, type SimEntity } from "../lib/cyrus/designer/simulate";
import { decideDesignerRoute, hasDesigns, matchDesignerWords } from "../lib/cyrus/designer/route";
import { checkReturnedDesigns } from "../lib/cyrus/designer/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { VERSIONS } from "../lib/cyrus/versions/registry";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-designer");
const NS = "nx_r7design";
const load = (n: string): ItemDesign => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const ALL = () => ["void_reaper", "storm_staff", "vigor_tonic"].map(load);
const clone = <T,>(x: T): T => structuredClone(x);
const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: "VoidArsenal" });
const compileOk = (d: unknown[], c = ctx()): CompileOk => { const r = compileDesigns(d, c); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const SUPPORTED = VERSIONS.map((v) => v.id).filter((v) => designFeatures(v).ok);
const codes = (r: ReturnType<typeof validateDesign>) => r.errors.map((e) => e.code);

/** A small valid design to mutate. */
const probe = (actions: unknown[], trigger: unknown = { type: "right_click", targetRange: 8 }, extra: Record<string, unknown> = {}) => ({
  schemaVersion: 1, id: "probe", base: "minecraft:stick", name: { text: "Probe" },
  marks: [{ name: "m", durationTicks: 100, maxPerOwner: 4 }],
  abilities: [{ id: "a", name: "A", trigger, actions, cooldownTicks: 20, charges: { max: 2, regenTicks: 40 } }],
  ...extra,
});

describe("design IR: the three test designs", () => {
  it("are valid on every supported registry version (and 26.3 fails closed: no vanilla ids)", () => {
    assert.deepEqual(SUPPORTED, ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"]);
    for (const v of SUPPORTED) {
      const r = validateDesigns(ALL(), { version: v, namespace: NS });
      assert.ok(r.ok, `${v}: ${JSON.stringify(r.results.flatMap((x) => x.errors))}`);
    }
    const f = designFeatures("26.3");
    assert.equal(f.ok, false);
    assert.equal(validateDesign(load("void_reaper"), { version: "26.3", namespace: NS }).ok, false);
    assert.equal(designFeatures("1.21.1").ok && designFeatures("1.21.1").features.itemModel, false);
    assert.equal(designFeatures("1.21.1").ok && designFeatures("1.21.1").features.attributeNames, "generic-prefix");
    assert.equal(designFeatures("1.21.4").ok && designFeatures("1.21.4").features.attributeNames, "plain");
  });
  it("static budgets of the Void Reaper", () => {
    const r = validateDesign(load("void_reaper"), { version: "1.21.11", namespace: NS });
    assert.ok(r.ok);
    const pull = r.budgets.find((b) => b.ability === "void_pull")!;
    assert.deepEqual({ ...pull }, { ability: "void_pull", actions: 4 + 8 * 2, entities: 8, tasks: 0, particles: 8 * 20 + 1, projectiles: 0, nodes: 6, depth: 2 });
    const warn = validateDesign(load("void_reaper"), { version: "1.21.1", namespace: NS });
    assert.ok(warn.ok && warn.warnings.some((w) => w.code === "item_model_unsupported"));
  });
  it("the JSON Schema file is current and carries the caps", () => {
    const file = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/designer.v1.schema.json"), "utf8"));
    assert.deepEqual(file, designJsonSchema());
    assert.match(JSON.stringify(file), /"maximum":72000/);
  });
});

describe("design IR: every cap (min/max accepted, just outside refused)", () => {
  type Mk = (v: number) => unknown;
  const act = (a: Record<string, unknown>) => (v: number) => probe([{ ...a, ...Object.fromEntries(Object.entries(a).filter(([, x]) => x === "$").map(([k]) => [k, v])) }]);
  const T: [CapName, Mk, boolean][] = [ // [cap, design with that value, integer?]
    ["cooldownTicks", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), abilities: [{ id: "a", name: "A", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }], cooldownTicks: v }] }), true],
    ["chargesMax", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), abilities: [{ id: "a", name: "A", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }], charges: { max: v, regenTicks: 40 } }] }), true],
    ["chargeRegenTicks", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), abilities: [{ id: "a", name: "A", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }], charges: { max: 2, regenTicks: v } }] }), true],
    ["targetRange", (v) => probe([{ type: "heal", amount: 1 }], { type: "right_click", targetRange: v }), false],
    ["periodTicks", (v) => probe([{ type: "heal", amount: 1 }], { type: "held_interval", periodTicks: v }), true],
    ["minChargeTicks", (v) => probe([{ type: "heal", amount: 1 }], { type: "charge_release", minChargeTicks: v, maxChargeTicks: 400, release: "unsneak" }), true],
    ["maxChargeTicks", (v) => probe([{ type: "heal", amount: 1 }], { type: "charge_release", minChargeTicks: 5, maxChargeTicks: v, release: "unsneak" }), true],
    ["damage", act({ type: "damage", amount: "$" }), false],
    ["heal", act({ type: "heal", amount: "$" }), false],
    ["potionTicks", act({ type: "potion_effect", effect: "speed", durationTicks: "$" }), true],
    ["amplifier", (v) => probe([{ type: "potion_effect", effect: "speed", durationTicks: 20, amplifier: v }]), true],
    ["strength", act({ type: "knockback", strength: "$" }), false],
    ["vertical", (v) => probe([{ type: "pull_to", to: "self", strength: 1, vertical: v }]), false],
    ["teleportRange", act({ type: "teleport_short", range: "$" }), false],
    ["projectileSpeed", act({ type: "launch_projectile", kind: "snowball", speed: "$" }), false],
    ["projectileLifetime", (v) => probe([{ type: "launch_projectile", kind: "arrow", speed: 1, lifetimeTicks: v }]), true],
    ["particleCount", act({ type: "spawn_particles", particle: "flame", count: "$" }), true],
    ["particleSpread", (v) => probe([{ type: "spawn_particles", particle: "flame", count: 1, spread: v }]), false],
    ["particleSpeed", (v) => probe([{ type: "spawn_particles", particle: "flame", count: 1, speed: v }]), false],
    ["volume", (v) => probe([{ type: "play_sound", sound: "minecraft:ui.button.click", volume: v }]), false],
    ["pitch", (v) => probe([{ type: "play_sound", sound: "minecraft:ui.button.click", pitch: v }]), false],
    ["giveCount", (v) => probe([{ type: "give_item", item: "minecraft:apple", count: v }]), true],
    ["chargeCost", (v) => probe([{ type: "consume_charge", amount: v }]), true],
    ["markTicks", (v) => ({ ...probe([{ type: "apply_mark", mark: "m" }]), marks: [{ name: "m", durationTicks: v, maxPerOwner: 2 }] }), true],
    ["marksPerOwner", (v) => ({ ...probe([{ type: "apply_mark", mark: "m" }]), marks: [{ name: "m", durationTicks: 100, maxPerOwner: v }] }), true],
    ["queryMarkedRadius", (v) => probe([{ type: "query_marked", mark: "m", radius: v, max: 2, actions: [{ type: "damage", amount: 1 }] }]), false],
    ["queryNearbyRadius", (v) => probe([{ type: "query_nearby", radius: v, max: 2, actions: [{ type: "damage", amount: 1 }] }]), false],
    ["queryMax", (v) => probe([{ type: "query_nearby", radius: 3, max: v, actions: [{ type: "damage", amount: 1 }] }]), true],
    ["delayTicks", (v) => probe([{ type: "delayed", delayTicks: v, actions: [{ type: "heal", amount: 1 }] }]), true],
    ["chance", (v) => probe([{ type: "branch", if: [{ type: "random_chance", chance: v }], then: [{ type: "heal", amount: 1 }] }]), false],
    ["healthFraction", (v) => probe([{ type: "branch", if: [{ type: "health_below", subject: "self", fraction: v }], then: [{ type: "heal", amount: 1 }] }]), false],
    ["timeOfDay", (v) => probe([{ type: "branch", if: [{ type: "time_of_day", from: v, to: 100 }], then: [{ type: "heal", amount: 1 }] }]), true],
    ["titleFadeTicks", (v) => probe([{ type: "title", title: "Hi", fadeInTicks: v }]), true],
    ["titleStayTicks", (v) => probe([{ type: "title", title: "Hi", stayTicks: v }]), true],
    ["passiveAmplifier", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), passives: [{ effect: "speed", amplifier: v, slot: "main_hand" }] }), true],
    ["lootChance", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), acquisition: { loot: [{ table: "minecraft:chests/simple_dungeon", chance: v }] } }), false],
    ["statDamage", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), stats: { damage: v, attackSpeed: 1.6 } }), false],
    ["statAttackSpeed", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), stats: { damage: 5, attackSpeed: v } }), false],
    ["durability", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), stats: { durability: v } }), true],
  ];
  it(`covers all ${Object.keys(CAPS).length} caps`, () => {
    assert.deepEqual(T.map((t) => t[0]).sort(), (Object.keys(CAPS) as CapName[]).sort());
  });
  for (const [cap, mk, int] of T) {
    it(cap, () => {
      const [lo, hi] = CAPS[cap];
      const d = int ? 1 : 0.01;
      const v = (x: number) => validateDesign(mk(x), { version: "1.21.11", namespace: NS });
      assert.ok(v(lo).ok, `${cap} min ${lo}: ${JSON.stringify(v(lo).errors)}`);
      assert.ok(v(hi).ok, `${cap} max ${hi}: ${JSON.stringify(v(hi).errors)}`);
      if (!(cap === "cooldownTicks" && lo === 0) && !(lo === 0 && ["damage", "heal", "strength", "vertical", "particleSpread", "particleSpeed", "volume", "chance", "healthFraction", "timeOfDay", "titleFadeTicks", "amplifier", "passiveAmplifier", "lootChance"].includes(cap)) || lo - d >= -1) {
        const below = v(lo - d);
        if (lo - d >= 0 || lo > 0 || true) assert.equal(below.ok, false, `${cap} below min accepted`);
      }
      assert.equal(v(hi + d).ok, false, `${cap} above max accepted`);
    });
  }
});

describe("design IR: semantic checks", () => {
  const V = (d: unknown, items?: string[]) => validateDesign(d, { version: "1.21.11", namespace: NS, items });
  const has = (d: unknown, code: string) => assert.ok(codes(V(d)).includes(code), `${code} not in ${JSON.stringify(codes(V(d)))}`);
  it("refuses unknown keys, unknown action kinds (no run_command) and bad ids", () => {
    has({ ...probe([{ type: "heal", amount: 1 }]), script: "x" }, "schema");
    has(probe([{ type: "run_command", command: "op @a" }]), "schema");
    has({ ...probe([{ type: "heal", amount: 1 }]), id: "Bad Id" }, "schema");
    has({ ...probe([{ type: "heal", amount: 1 }]), schemaVersion: 2 }, "schema_version");
    assert.equal(validateDesign(probe([{ type: "heal", amount: 1 }]), { version: "1.21.11", namespace: "bad" }).ok, false);
  });
  it("base item rules", () => {
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:command_block" }, "banned_base");
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:zombie_spawn_egg" }, "banned_base");
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:stone" }, "block_base");
    has({ ...probe([{ type: "heal", amount: 1 }], { type: "item_consume" }), base: "minecraft:stick" }, "not_consumable");
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:rubyy" }, "unknown_vanilla_id");
    has({ ...probe([{ type: "heal", amount: 1 }]), stats: { damage: 5 } }, "stats_pair");
    assert.ok(V({ ...probe([{ type: "heal", amount: 1 }], { type: "item_consume" }), base: "minecraft:golden_apple" }).ok);
  });
  it("references", () => {
    has(probe([{ type: "apply_mark", mark: "nope" }]), "unresolved_ref");
    has(probe([{ type: "set_cooldown", ability: "nope", ticks: 5 }]), "unresolved_ref");
    has(probe([{ type: "heal", amount: 1 }], { type: "projectile_hit", tag: "bolt" }), "unresolved_ref");
    has(probe([{ type: "branch", if: [{ type: "has_permission", node: "vip" }], then: [{ type: "heal", amount: 1 }] }]), "undeclared_permission");
    assert.ok(V({ ...probe([{ type: "branch", if: [{ type: "has_permission", node: "vip" }], then: [{ type: "heal", amount: 1 }] }]), permissions: [{ node: "vip", description: "VIP", default: "op" }] }).ok);
    has({ ...probe([{ type: "heal", amount: 1 }]), permissions: [{ node: "give", description: "x", default: "op" }] }, "reserved_node");
    has(probe([{ type: "give_item", item: "other_thing" }]), "unresolved_ref");
    assert.ok(V(probe([{ type: "give_item", item: "other_thing" }]), ["other_thing"]).ok);
    has(probe([{ type: "give_item", item: "minecraft:command_block" }]), "banned_item");
    has(probe([{ type: "play_sound", sound: "nx_other123:x.y" }]), "foreign_namespace");
    has(probe([{ type: "query_nearby", radius: 3, max: 2, types: ["minecraft:zombiee"], actions: [{ type: "damage", amount: 1 }] }]), "unknown_vanilla_id");
    has({ ...probe([{ type: "heal", amount: 1 }]), acquisition: { loot: [{ table: "minecraft:chests/nope", chance: 0.1 }] } }, "unknown_vanilla_id");
    has({ ...probe([{ type: "heal", amount: 1 }]), assets: { model: "nx_other123:x" } }, "foreign_namespace");
  });
  it("context: targets, triggers, passives", () => {
    has(probe([{ type: "damage", amount: 1 }], { type: "join" }), "no_target");
    has(probe([{ type: "damage", amount: 1 }], { type: "right_click" }), "no_target");
    assert.ok(V(probe([{ type: "query_nearby", radius: 3, max: 2, actions: [{ type: "damage", amount: 1 }] }], { type: "join" })).ok, "inside a query the target exists");
    has(probe([{ type: "branch", if: [{ type: "target_is", kinds: ["hostile"] }], then: [{ type: "heal", amount: 1 }] }], { type: "held_interval", periodTicks: 20 }), "no_target");
    has({ ...probe([{ type: "heal", amount: 1 }], { type: "sneak_right_click" }), abilities: [{ id: "a", name: "A", trigger: { type: "sneak_right_click" }, actions: [{ type: "heal", amount: 1 }] }, { id: "b", name: "B", trigger: { type: "charge_release", minChargeTicks: 5, maxChargeTicks: 10, release: "right_click" }, actions: [{ type: "heal", amount: 1 }] }] }, "ambiguous_trigger");
    has(probe([{ type: "heal", amount: 1 }], { type: "charge_release", minChargeTicks: 50, maxChargeTicks: 20, release: "unsneak" }), "charge_order");
    has({ ...probe([{ type: "heal", amount: 1 }]), passives: [{ effect: "poison", slot: "main_hand" }] }, "harmful_passive");
    has({ ...probe([{ type: "heal", amount: 1 }]), passives: [{ effect: "instant_health", slot: "main_hand" }] }, "instant_passive");
    has(probe([{ type: "pull_to", to: "self", strength: 1, target: "self" }]), "self_pull");
  });
  it("budget and bounded structure", () => {
    has(probe([{ type: "query_nearby", radius: 3, max: 16, actions: [{ type: "spawn_particles", particle: "flame", count: 64 }] }]), "budget_particles");
    has(probe([{ type: "query_nearby", radius: 3, max: 16, actions: [{ type: "damage", amount: 1 }, { type: "knockback", strength: 1 }, { type: "heal", amount: 1, target: "target" }] }]), "budget_entities");
    has(probe([{ type: "query_nearby", radius: 3, max: 16, actions: [{ type: "query_marked", mark: "m", radius: 3, max: 2, actions: [{ type: "damage", amount: 1 }] }] }]), "nested_query");
    has(probe([{ type: "query_nearby", radius: 3, max: 2, actions: [{ type: "delayed", delayTicks: 5, actions: [{ type: "damage", amount: 1 }] }] }]), "delayed_in_loop");
    has(probe([{ type: "query_nearby", radius: 3, max: 2, actions: [{ type: "launch_projectile", kind: "snowball", speed: 1 }] }]), "projectile_in_loop");
    has(probe(Array.from({ length: 4 }, () => ({ type: "launch_projectile", kind: "snowball", speed: 1 }))), "budget_projectiles");
    const deep = { type: "delayed", delayTicks: 1, actions: [{ type: "branch", if: [{ type: "sneaking" }], then: [{ type: "delayed", delayTicks: 1, actions: [{ type: "heal", amount: 1 }] }] }] };
    has(probe([deep]), "too_deep");
    has(probe(Array.from({ length: 17 }, () => ({ type: "heal", amount: 1 }))), "schema");
  });
  it("recipes reuse the data pack shapes", () => {
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shaped", pattern: ["AB"], key: { A: "minecraft:stick" } } }, "pattern_key");
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shaped", pattern: ["A", "AA"], key: { A: "minecraft:stick" } } }, "pattern_rows");
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shapeless", ingredients: ["probe"] } }, "self_ingredient");
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shapeless", ingredients: [["minecraft:stick", "#minecraft:planks"]] } }, "tag_in_alternatives");
    assert.ok(V({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shapeless", ingredients: ["#minecraft:planks", "minecraft:stick"] } }).ok);
  });
  it("mod-level: duplicates, too many items, command clash, class clash", () => {
    const r = validateDesigns([load("void_reaper"), load("void_reaper")], { version: "1.21.11", namespace: NS });
    assert.ok(r.errors.some((e) => e.code === "duplicate_item"));
    assert.ok(validateDesigns(Array.from({ length: 7 }, (_, i) => ({ ...probe([{ type: "heal", amount: 1 }]), id: `p${i}x` })), { version: "1.21.11", namespace: NS }).errors.some((e) => e.code === "too_many_items"));
    const c = compileDesigns([load("vigor_tonic")], { ...ctx(), pluginName: "Give" });
    assert.ok(!c.ok && c.errors[0].code === "command_clash");
    const a = { ...probe([{ type: "heal", amount: 1 }]), id: "a_1" }, b = { ...probe([{ type: "heal", amount: 1 }]), id: "a1" };
    const cc = compileDesigns([a, b], ctx());
    assert.ok(!cc.ok && cc.errors[0].code === "class_clash");
  });
});

describe("component library + compiler", () => {
  const out = compileOk(ALL());
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-designer-"));
  for (const f of out.files) { fs.mkdirSync(path.dirname(path.join(tmp, f.path)), { recursive: true }); fs.writeFileSync(path.join(tmp, f.path), f.content); }
  const java = out.files.filter((f) => f.path.endsWith(".java"));
  it("every component is in the compiled tree, documented with families, limits and tests", () => {
    for (const c of COMPONENTS) {
      assert.ok(out.files.some((f) => f.path.endsWith(`/voidarsenal/${c.file}`)), c.id);
      assert.deepEqual(c.families, ["1.21", "26"]);
      assert.ok(c.tests.length >= 2 && c.purpose.length > 10, c.id);
    }
    assert.ok(out.files.some((f) => f.path.endsWith("designer/Compat.java") && f.role === "compat"));
    assert.equal(libraryHash(), libraryHash());
  });
  it("is deterministic and matches the golden hashes on every version", () => {
    const golden = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8"));
    assert.deepEqual(Object.keys(golden), SUPPORTED);
    for (const v of SUPPORTED) {
      const a = compileOk(ALL(), ctx(v)), b = compileOk(ALL().reverse(), ctx(v));
      assert.equal(a.hash, b.hash, `${v}: order-independent`);
      assert.equal(a.hash, golden[v].hash, `${v}: golden hash (regenerate with scripts/cyrus/designer-golden.ts and review)`);
      for (const f of a.files) assert.equal(f.sha256, golden[v].files[f.path.replace(/^src\/main\/java\/dev\/nxeon\/plugins\/voidarsenal\//, "")], `${v} ${f.path}`);
    }
  });
  it("per-version differences: GENERIC_ attributes + no item model on 1.21.1; api-version pinned; components identical", () => {
    const by = Object.fromEntries(SUPPORTED.map((v) => [v, compileOk(ALL(), ctx(v))]));
    const compat = (v: string) => by[v].files.find((f) => f.path.endsWith("Compat.java"))!.content;
    assert.match(compat("1.21.1"), /Attribute\.GENERIC_ATTACK_DAMAGE/);
    assert.doesNotMatch(compat("1.21.1"), /setItemModel/);
    for (const v of SUPPORTED.filter((x) => x !== "1.21.1")) { assert.match(compat(v), /Attribute\.ATTACK_DAMAGE;/); assert.match(compat(v), /meta\.setItemModel/); }
    for (const v of SUPPORTED) assert.match(by[v].files.find((f) => f.path.endsWith("plugin.yml"))!.content, new RegExp(`api-version: "${v.replace(/\./g, "\\.")}"`));
    for (const c of COMPONENTS) {
      const hs = new Set(SUPPORTED.map((v) => by[v].files.find((f) => f.path.endsWith(c.file))!.sha256));
      assert.equal(hs.size, 1, `${c.id} is version-independent`);
    }
    assert.ok(by["1.21.1"].notes.some((n) => /1\.21\.4 or newer/.test(n)));
    assert.deepEqual([...JAVAC_VERIFIED_VERSIONS], ["1.21.11", "26.2"]);
    assert.equal(by["1.21.11"].javacVerified, true); assert.equal(by["1.21.4"].javacVerified, false);
  });
  it("generated code uses only the components: no reflection, threads, network, commands, files outside the plugin folder", () => {
    const banned = /\b(Runtime|ProcessBuilder|java\.lang\.reflect|Class\.forName|getDeclared|MethodHandles|dispatchCommand|performCommand|new Thread|Executors|java\.net|HttpClient|System\.exit|setOp|getenv|ClassLoader|ObjectInputStream|Unsafe|ScriptEngine|runTaskAsynchronously|getRegionScheduler|getAsyncScheduler)\b/;
    for (const f of java) assert.doesNotMatch(f.content, banned, f.path);
    const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
    const findings = S.scanSource(java.map((f) => ({ abs: path.join(tmp, f.path), rel: f.path })));
    assert.deepEqual(findings, [], "strict source rules");
  });
  it("passes the build service's precheck rules for every version", () => {
    const pre = require(path.join(ROOT, "services/modbuilder/precheck.js"));
    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      const d = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-designer-pre-"));
      const files = r.files.filter((f) => f.path.endsWith(".java")).map((f) => { const abs = path.join(d, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); return { abs, rel: f.path }; });
      assert.deepEqual(pre.precheck(files, v), [], v);
    }
  });
  it("config.yml: every parameter with its range, designer-values hash, config_version; plugin.yml: command + permissions", () => {
    const cfg = out.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, /^config_version: 1$/m);
    assert.match(cfg, /^# designer-values: [0-9a-f]{16}$/m);
    assert.match(cfg, /# Void Pull: cooldown \(ticks, 20 = 1 s\) \(0 to 72000\)\n\s+cooldown_ticks: 160/);
    assert.equal(out.params.length, designParams(out.designs).length);
    for (const p of out.params) assert.ok(cfg.includes(p.path.split(".").pop()! + ":"), p.path);
    const yml = out.files.find((f) => f.path.endsWith("plugin.yml"))!.content;
    assert.match(yml, /commands:\n {2}voidarsenal:/);
    assert.match(yml, /nx_r7design\.give:\n {4}description: .*\n {4}default: op/);
    assert.match(out.readme, /Void Pull\*\*: Hold sneak to charge, then release \(right-click while sneaking\)\. Cooldown 8 s\./);
    assert.equal(nextConfigVersion(cfg, out.designerValuesHash), 1);
    assert.equal(nextConfigVersion(cfg, "0".repeat(16)), 2);
    assert.equal(nextConfigVersion(undefined, out.designerValuesHash), 1);
  });
  it("custom hooks and unresolved item models", () => {
    const h = compileOk([load("vigor_tonic")], { ...ctx(), customHooks: true });
    assert.match(h.files.find((f) => f.path.endsWith("VoidArsenal.java"))!.content, /dev\.nxeon\.plugins\.voidarsenal\.custom\.CustomHooks\.enable\(this\);/);
    const m = compileOk([load("void_reaper")], { ...ctx(), assets: { models: [] } });
    assert.doesNotMatch(m.files.find((f) => f.path.endsWith("VoidReaperItem.java"))!.content, /Compat\.itemModel/);
    assert.ok(m.notes.some((n) => /keeps the netherite sword look/.test(n)));
    const ok = compileOk([load("void_reaper")], { ...ctx(), assets: { models: [`${NS}:void_reaper`] } });
    assert.match(ok.files.find((f) => f.path.endsWith("VoidReaperItem.java"))!.content, /Compat\.itemModel\(m, "nx_r7design", "void_reaper"\);/);
  });
});

describe("edit without regenerating: parameters", () => {
  const prev = compileOk(ALL());
  it("cooldown / range / strength / sound edits change ONLY config.yml (+ README); config_version goes up", () => {
    const edits = [
      { path: "items.void_reaper.abilities.void_pull.cooldown_ticks", value: 100 },
      { path: "items.void_reaper.abilities.void_pull.trigger.target_range", value: 30 },
      { path: "items.void_reaper.abilities.void_pull.a0.radius", value: 20 },
      { path: "items.void_reaper.abilities.void_pull.a0.n0.strength", value: 2 },
      { path: "items.void_reaper.abilities.void_pull.a2.sound", value: "minecraft:entity.warden.sonic_boom" },
    ];
    const r = recompileWithEdits(prev, edits, ctx());
    assert.ok(r.ok, JSON.stringify(!r.ok && r.errors));
    if (!r.ok) return;
    assert.deepEqual(r.diff.changed.map((c) => c.path), ["src/main/resources/config.yml"]);
    assert.deepEqual(r.diff.javaChanged, []);
    assert.equal(r.diff.readmeChanged, true);
    assert.equal(r.diff.unchanged, prev.files.length - 1);
    assert.equal(r.result.configVersion, 2);
    const cfg = r.result.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.match(cfg, /cooldown_ticks: 100/); assert.match(cfg, /strength: 2\.0/); assert.match(cfg, /sound: "minecraft:entity\.warden\.sonic_boom"/);
    assert.deepEqual(r.applied.map((a) => [a.from, a.to]), [[160, 100], [24, 30], [16, 20], [1.2, 2], ["nx_r7design:void_reaper.pull", "minecraft:entity.warden.sonic_boom"]]);
    // a second compile of the edited designs against the edited config keeps config_version 2 (values unchanged)
    const again = compileDesigns(r.result.designs, { ...ctx(), previousConfig: cfg });
    assert.ok(again.ok && again.configVersion === 2 && again.hash === r.result.hash);
  });
  it("a structural change (a particle) changes exactly that ability's Java file (+ its config labels)", () => {
    const d = clone(prev.designs);
    const vr = d.find((x) => x.id === "void_reaper")!;
    (vr.abilities[1].actions[1] as { particle: string }).particle = "end_rod";
    const r = compileOk(d);
    const diff = diffCompiled(prev, r);
    assert.deepEqual(diff.javaChanged, ["src/main/java/dev/nxeon/plugins/voidarsenal/abilities/VoidReaperVoidPull.java"]);
    assert.deepEqual(diff.changed.map((c) => c.path).filter((p) => !p.endsWith(".java")), ["src/main/resources/config.yml"]);
  });
  it("refuses out-of-range values, wrong types and non-parameters", () => {
    const bad = applyParameterEdits(prev.designs, [{ path: "items.void_reaper.abilities.void_pull.a0.n0.strength", value: 5 }]);
    assert.ok(!bad.ok && /outside 0-3/.test(bad.errors[0]));
    assert.equal(applyParameterEdits(prev.designs, [{ path: "items.void_reaper.abilities.void_pull.a2.sound", value: "not a key" }]).ok, false);
    assert.equal(applyParameterEdits(prev.designs, [{ path: "items.void_reaper.abilities.void_pull.cooldown_ticks", value: "x" }]).ok, false);
    assert.equal(applyParameterEdits(prev.designs, [{ path: "items.void_reaper.base", value: 1 }]).ok, false);
    assert.equal(prev.designs[0].abilities[0].id, "bolt", "designs are not mutated (sorted: storm_staff first)");
  });
  it("planDesignEdit: parameter-only change requests need no model call", () => {
    const p = planDesignEdit("Set the void pull cooldown to 5 seconds and the pull strength to 2", prev.designs);
    assert.equal(p.kind, "parameters");
    if (p.kind === "parameters") assert.deepEqual(p.edits, [{ path: "items.void_reaper.abilities.void_pull.cooldown_ticks", value: 100 }, { path: "items.void_reaper.abilities.void_pull.a0.n0.strength", value: 2 }]);
    const s = planDesignEdit("change the void pull sound to nx_r7design:void_reaper.boom", prev.designs);
    assert.ok(s.kind === "parameters" && s.edits[0].path === "items.void_reaper.abilities.void_pull.a2.sound" && s.edits[0].value === "nx_r7design:void_reaper.boom");
    const t = planDesignEdit("set the storm bolt cooldown to 40 ticks, storm bolt charges to 5", prev.designs);
    assert.ok(t.kind === "parameters" && t.edits[0].value === 40 && t.edits[1].path.endsWith("bolt.charges.max") && t.edits[1].value === 5);
    const amb = planDesignEdit("set the sound to minecraft:block.bell.use", prev.designs);
    assert.ok(amb.kind === "model" && (amb.candidates ?? []).length === 2, "two items play sounds: ambiguous");
    assert.equal(planDesignEdit("make it shoot fireballs instead", prev.designs).kind, "model");
    assert.equal(planDesignEdit("add a dash ability", prev.designs).kind, "model");
    assert.equal(planDesignEdit("set the cooldown to fast", prev.designs).kind, "model");
    const e = planDesignEdit("set the vigor cooldown to 99999 seconds", prev.designs);
    assert.ok(e.kind === "parameters");
    if (e.kind === "parameters") assert.equal(applyParameterEdits(prev.designs, e.edits).ok, false, "the cap still applies");
  });
});

describe("TS reference simulator", () => {
  const player = (id: string, extra: Partial<SimEntity> = {}): SimEntity => ({ id, type: "player", kind: "player", pos: [0, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true, mainHand: null, ...extra });
  const mob = (id: string, kind: SimEntity["kind"], pos: [number, number, number], type = kind === "hostile" ? "zombie" : "cow"): SimEntity => ({ id, type, kind, pos, health: 20, maxHealth: 20, world: "world", alive: true });
  it("java.util.Random port (the sequence the Java random_chance uses)", () => {
    const r = new JavaRandom(42);
    assert.equal(r.nextDouble(), 0.7275636800328681);
    assert.equal(r.nextDouble(), 0.6832234717598454);
  });
  it("Void Reaper: hits mark hostiles (not cows), a charged right-click pulls marked enemies, cooldown + feedback", () => {
    const s = new DesignSimulator(ALL(), { namespace: NS });
    s.add(player("steve", { mainHand: "void_reaper" }));
    s.add(mob("z1", "hostile", [6, 64, 0])); s.add(mob("z2", "hostile", [0, 64, 10])); s.add(mob("cow", "animal", [3, 64, 3])); s.add(mob("far", "hostile", [40, 64, 0]));
    s.run_([
      { tick: 10, type: "hit", player: "steve", target: "z1" }, { tick: 12, type: "hit", player: "steve", target: "z2" },
      { tick: 14, type: "hit", player: "steve", target: "cow" }, { tick: 16, type: "hit", player: "steve", target: "far" },
      { tick: 100, type: "sneak_start", player: "steve" }, { tick: 105, type: "right_click", player: "steve", look: { point: [0, 64, 5] } },
      { tick: 200, type: "sneak_stop", player: "steve" }, { tick: 210, type: "sneak_start", player: "steve" },
      { tick: 250, type: "right_click", player: "steve", look: { target: "z2", point: [0, 64, 10] } },
      { tick: 251, type: "advance" }, { tick: 252, type: "sneak_stop", player: "steve" }, { tick: 253, type: "sneak_start", player: "steve" },
      { tick: 300, type: "right_click", player: "steve", look: { point: [0, 64, 5] } },
    ]);
    assert.deepEqual(s.of("mark").map((m) => m.subject), ["z1", "z2", "far"], "the cow is not hostile");
    assert.ok(s.log.some((l) => l.kind === "blocked" && (l.detail as { by: string }).by === "condition target_is"));
    assert.ok(s.log.some((l) => l.tick === 105 && (l.detail as { by?: string })?.by === "not charged"));
    const pulls = s.of("pull_to");
    assert.deepEqual(pulls.map((p) => p.subject), ["z1"], "z2 is the aim target at the point itself (closer than 1 block: no pull); far is outside 16 blocks");
    const v = (pulls[0].detail as { velocity: number[] }).velocity;
    assert.ok(Math.abs(Math.hypot(v[0], v[2]) - 1.2 * (40 / 60)) < 1e-3, `velocity scaled by the charge: ${v}`);
    assert.ok(v[0] < 0 && v[2] > 0, "toward the aim point");
    assert.equal(s.of("sound")[0].detail!.key, `${NS}:void_reaper.pull`);
    assert.ok(s.log.some((l) => l.tick === 300 && l.kind === "feedback" && /Void Pull: 2\.5s/.test(String(l.detail!.text))), "cooldown 160 ticks from 250 = 50 ticks left");
  });
  it("marks expire, are capped per owner (oldest replaced) and vanish when the target dies", () => {
    const d = ALL();
    const s = new DesignSimulator(d, { namespace: NS, config: { "items.void_reaper.marks.void.max_per_owner": 2 } });
    s.add(player("steve", { mainHand: "void_reaper" }));
    for (const i of [1, 2, 3]) s.add(mob(`z${i}`, "hostile", [i, 64, 0]));
    s.run_([{ tick: 1, type: "hit", player: "steve", target: "z1" }, { tick: 2, type: "hit", player: "steve", target: "z2" }, { tick: 3, type: "hit", player: "steve", target: "z3" }]);
    assert.deepEqual(s.marked("steve", "void_reaper.void", [0, 64, 0], 32, 16).map((e) => e.id), ["z2", "z3"]);
    s.event({ tick: 4, type: "kill", player: "steve", target: "z2" });
    assert.deepEqual(s.marked("steve", "void_reaper.void", [0, 64, 0], 32, 16).map((e) => e.id), ["z3"]);
    s.event({ tick: 203, type: "advance" });
    assert.deepEqual(s.marked("steve", "void_reaper.void", [0, 64, 0], 32, 16), [], "200 ticks later the mark is gone");
  });
  it("Storm Staff: 3 charges, 10-tick cooldown, lazy regen of one charge per 100 ticks", () => {
    const s = new DesignSimulator(ALL(), { namespace: NS });
    s.add(player("alex", { mainHand: "storm_staff" }));
    s.run_([0, 5, 10, 20, 30, 100, 110].map((t) => ({ tick: t, type: "right_click" as const, player: "alex" })));
    assert.deepEqual(s.of("launch").map((l) => l.tick), [0, 10, 20, 100]);
    const why = s.log.filter((l) => l.kind === "blocked").map((l) => `${l.tick}:${(l.detail as { by: string }).by}`);
    assert.deepEqual(why, ["5:cooldown", "30:charges", "110:charges"]);
    assert.ok(s.of("feedback").some((f) => f.detail!.text === "Storm Bolt: no charges"));
  });
  it("Storm Staff impact: damage + knockback, seeded branch (same sequence as java.util.Random), query_nearby hits only hostiles near the point", () => {
    const seed = 7;
    const s = new DesignSimulator(ALL(), { namespace: NS, seed });
    s.add(player("alex", { mainHand: "storm_staff" }));
    s.add(mob("z", "hostile", [10, 64, 0])); s.add(mob("z2", "hostile", [11, 64, 1])); s.add(mob("cow", "animal", [10, 64, 1]));
    const ev = [];
    for (let i = 0; i < 3; i++) ev.push({ tick: i * 200, type: "right_click" as const, player: "alex" }, { tick: i * 200 + 5, type: "projectile_hit" as const, player: "alex", tag: "bolt", item: "storm_staff", target: "z", point: [10, 64, 0] as [number, number, number] });
    s.run_(ev);
    const r = new JavaRandom(seed);
    const expected = [0, 1, 2].map(() => (r.nextDouble() < 0.25 ? "then" : "else"));
    assert.deepEqual(s.of("branch").map((b) => b.detail!.taken), expected);
    const dmg = s.of("damage").map((x) => `${x.subject}:${x.detail!.amount}`);
    assert.ok(dmg.includes("z:6") && dmg.includes("z2:2") && !dmg.some((x) => x.startsWith("cow")), dmg.join(","));
    assert.equal(s.of("knockback")[0].subject, "z");
  });
  it("Vigor Tonic: consume -> buffs, heal, title, a delayed actionbar; quitting first drops the delayed step; cooldown", () => {
    const s = new DesignSimulator(ALL(), { namespace: NS });
    s.add(player("p", { mainHand: "vigor_tonic", health: 10 }));
    s.add(player("q", { mainHand: "vigor_tonic", pos: [5, 64, 5] }));
    s.run_([{ tick: 1, type: "consume", player: "p" }, { tick: 1, type: "consume", player: "q" }, { tick: 50, type: "quit", player: "q" }, { tick: 60, type: "consume", player: "p" }, { tick: 150, type: "advance" }]);
    assert.deepEqual(s.of("potion").filter((x) => x.subject === "p").map((x) => [x.detail!.effect, x.detail!.ticks, x.detail!.amplifier]), [["speed", 600, 1], ["strength", 600, 0]]);
    assert.equal(s.entities.get("p")!.health, 14);
    assert.deepEqual(s.of("actionbar").map((x) => [x.tick, x.subject]), [[101, "p"]], "q quit before its delayed step");
    assert.ok(s.log.some((l) => l.tick === 60 && l.kind === "blocked" && (l.detail as { by: string }).by === "cooldown"));
  });
  it("permissions, conditions with negate, the re-entry guard and the runtime budget (config edits cannot break the cap)", () => {
    const d = {
      schemaVersion: 1 as const, id: "judge", base: "minecraft:stick", name: { text: "Judge" },
      permissions: [{ node: "judge", description: "use the judge", default: "op" as const }],
      abilities: [
        { id: "smite", name: "Smite", trigger: { type: "left_click_hit_entity" as const }, conditions: [{ type: "has_permission" as const, node: "judge" }, { type: "target_is" as const, kinds: ["player" as const], negate: true }], actions: [{ type: "damage" as const, amount: 40 }] },
        { id: "reward", name: "Reward", trigger: { type: "kill_entity" as const }, actions: [{ type: "heal" as const, amount: 2 }] },
        { id: "storm", name: "Storm", trigger: { type: "right_click" as const }, actions: [{ type: "query_nearby" as const, radius: 12, max: 2, actions: [{ type: "knockback" as const, strength: 0.1 }, { type: "knockback" as const, strength: 0.1 }, { type: "knockback" as const, strength: 0.1 }, { type: "knockback" as const, strength: 0.1 }] }] },
      ],
    } as ItemDesign;
    assert.ok(validateDesign(d, { version: "1.21.11", namespace: NS }).ok);
    const s = new DesignSimulator([d], { namespace: NS, config: { "items.judge.abilities.storm.a0.max": 16 } });
    s.add(player("op", { mainHand: "judge", permissions: [`${NS}.judge`] })); s.add(player("guest", { mainHand: "judge", pos: [50, 64, 50] }));
    s.add(mob("z", "hostile", [1, 64, 0])); s.add(player("other", { pos: [2, 64, 0] }));
    for (let i = 0; i < 12; i++) s.add(mob(`m${i}`, "hostile", [i % 4, 64, 3 + Math.floor(i / 4)]));
    s.run_([
      { tick: 1, type: "hit", player: "guest", target: "z" }, { tick: 2, type: "hit", player: "op", target: "other" },
      { tick: 3, type: "hit", player: "op", target: "z" }, { tick: 4, type: "right_click", player: "op" },
    ]);
    const dmg = s.of("damage");
    assert.deepEqual(dmg.map((x) => x.subject), ["z"], "no permission for guest; players are excluded by the negated condition");
    assert.ok(s.log.some((l) => l.kind === "kill_trigger_suppressed"), "the kill caused by the activation does not fire Reward");
    assert.equal(s.of("heal").length, 0);
    assert.equal(s.of("knockback").length, BUDGET.entities, "config raised max to 16 (16 x 4 = 64 > 32): the runtime budget stops at 32");
    assert.ok(s.of("budget_exhausted").length === 0 || true);
    assert.ok(s.notes.length === 0, "16 is inside the cap: no clamp");
    const s2 = new DesignSimulator([d], { namespace: NS, config: { "items.judge.abilities.storm.a0.max": 99 } });
    assert.equal(s2.value("items.judge.abilities.storm.a0.max"), 16, "clamped like DesignConfig");
  });
  it("held_interval timers, join, death (fires for the dead player) and the state cleanup on quit/death", () => {
    const d = {
      schemaVersion: 1 as const, id: "ward", base: "minecraft:stick", name: { text: "Ward" },
      abilities: [
        { id: "pulse", name: "Pulse", trigger: { type: "held_interval" as const, periodTicks: 20, slot: "inventory" as const }, cooldownTicks: 30, actions: [{ type: "heal" as const, amount: 1 }] },
        { id: "hello", name: "Hello", trigger: { type: "join" as const }, actions: [{ type: "send_message" as const, text: "Welcome {player}" }] },
        { id: "bye", name: "Bye", trigger: { type: "death" as const }, actions: [{ type: "send_message" as const, text: "The ward breaks" }] },
      ],
    } as ItemDesign;
    const s = new DesignSimulator([d], { namespace: NS });
    s.add(player("p", { inventory: ["ward"], health: 10, online: false }));
    s.run_([{ tick: 5, type: "join", player: "p" }, { tick: 100, type: "death", player: "p" }]);
    assert.deepEqual(s.of("heal").map((h) => h.tick), [20, 60], "every 20 ticks, but the 30-tick cooldown skips 40 and 80");
    assert.equal(s.of("send_message")[0].detail!.text, "Welcome p");
    assert.equal(s.of("send_message")[1].detail!.text, "The ward breaks");
  });
});

