    assert.equal(P.systemPrompt("1.21.11", { design: false }), plain);
    const withD = P.systemPrompt("1.21.11", { design: true });
    assert.ok(withD.startsWith(plain) && /ITEM DESIGNER \(this build uses it\)/.test(withD));
    assert.equal(P.DESIGN_MAX_FILES, DESIGN_LIMITS.maxItems);
    const ex = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/designer-example.json"), "utf8"));
    assert.ok(validateDesign(ex, { version: "1.21.11", namespace: "nx_abcd1234" }).ok);
