    for (const c of Object.keys(CAPS) as CapName[]) void c;
  });
  it("routing: item-with-abilities requests, flag off decides nothing, unsupported versions explain", () => {
    const base = { text: "a sword that marks enemies on hit and pulls them in on a charged right-click with a cooldown", mcVersion: "1.21.11", on: true };
    assert.deepEqual(decideDesignerRoute({ ...base, on: false }), { route: false, matched: [], notices: [], limits: [] });
    const r = decideDesignerRoute(base);
    assert.equal(r.route, true); assert.deepEqual(r.matched, ["item:sword", "ability:marks"]);
    assert.equal(decideDesignerRoute({ ...base, text: "broadcast a message every hour" }).route, false);
    assert.equal(decideDesignerRoute({ ...base, text: "a staff" }).route, false, "an item without abilities is not routed");
    assert.equal(decideDesignerRoute({ ...base, text: "hello", existing: true }).route, true);
    const old = decideDesignerRoute({ ...base, mcVersion: "26.3" });
    assert.equal(old.route, false); assert.match(old.notices[0], /isn't available for Minecraft 26\.3/);
    assert.match(decideDesignerRoute({ ...base, mcVersion: "1.21.1" }).limits[1], /1\.21\.4 or newer/);
    assert.deepEqual(matchDesignerWords("a healing potion"), ["item:potion", "ability:healing"]);
    assert.ok(hasDesigns({ assets: { designs: [{}] } }) && !hasDesigns({}));
  });
  it("resolveBuildAssets: the designer is not plan-gated (no plan lookup) and byte-identical when off", async () => {
    let tierCalls = 0;
    const deps = { tierOf: async () => { tierCalls++; return "free"; }, projectForRootBuild: async () => ({ id: "cp00000000000000000001", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }) };
    const text = "a staff that shoots bolts on right-click with 3 charges";
    assert.deepEqual(await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => false }), { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, designerOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: NS, design: true });
    assert.equal(tierCalls, 0);
    assert.deepEqual(readCyrusMeta({ assets: on.meta }).assets!.designer, on.meta!.designer);
    const tex = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: `${text} and a custom texture`, mcVersion: "1.21.11" }, { ...deps, designerOn: () => true });
    assert.deepEqual(tex.service, { texture: false, sound: false, namespace: NS, design: true }, "the texture follows the plan gate (free: refused), the designer does not");
    assert.equal(tierCalls, 1);
  });
  it("portal sync: re-validates, re-compiles (serviceAgreed), drops tampered designs, records design assets", async () => {
    const svc = compileOk(ALL());
    const list = ALL().map((d) => ({ name: d.id, path: `assets/designs/${d.id}.json`, sha256: "x", spec: d }));
    const bad = clone(load("storm_staff")); (bad.abilities[1].actions[0] as { amount: number }).amount = 999;
    const r = checkReturnedDesigns([...list.slice(0, 2), { name: "vigor_tonic", path: "", sha256: "", spec: list[2].spec }], { namespace: NS, mcVersion: "1.21.11", pluginName: "VoidArsenal", compile: { hash: svc.hash, configVersion: 1 } });
    assert.equal(r.serviceAgreed, true);
    const t = checkReturnedDesigns([{ ...list[0], spec: bad }, list[1]], { namespace: NS, mcVersion: "1.21.11", pluginName: "VoidArsenal", compile: { hash: svc.hash } });
    assert.deepEqual(t.dropped.map((d) => d.name), ["storm_staff"]);
    assert.equal(t.serviceAgreed, false, "the service compiled something else");
    const revs: { id: string; modBuildId: string; input: unknown }[] = [], assets: unknown[] = [];
    const deps: AssetSyncDeps = {
      selectStore: () => ({ ok: false, reason: "off" }) as never,
      projectForRootBuild: async () => ({ id: "cp1", namespace: NS, userId: "u" }), createProject: async () => { throw new Error("no"); },
      findRevisionForBuild: async (_p, m) => revs.find((x) => x.modBuildId === m) ?? null, headRevisionId: async () => revs.at(-1)?.id ?? null,
      addRevision: async (_p, input) => { const x = { id: `rv${revs.length + 1}`, modBuildId: input.modBuildId!, input }; revs.push(x); return x; },
      recordAsset: async (_p, a) => { if (!assets.some((x) => JSON.stringify(x) === JSON.stringify(a))) assets.push(a); return a; },
    };
    const ar = { namespace: NS, promptVersion: null, qualityVersion: "tq-1", kept: false, textures: [], downgraded: [], warnings: [], designs: list, designCompile: { hash: svc.hash, configVersion: 1, pluginName: "VoidArsenal" }, designPromptVersion: "mb-design-2026-10-10.1" };
    const build = { id: "mb1", userId: "u", rootBuildId: null, mcVersion: "1.21.11", pluginName: "VoidArsenal", jarName: "VoidArsenal-1.0.0.jar", jarSha256: "a".repeat(64) };
    const out = await syncBuildAssets(build, ar, deps);
    const m = (revs[0].input as { manifest: { path: string; role: string }[] }).manifest;
    assert.deepEqual(m.map((x) => `${x.role}:${x.path}`), ["artifact:plugin/VoidArsenal-1.0.0.jar", "asset:assets/designs/void_reaper.json", "asset:assets/designs/storm_staff.json", "asset:assets/designs/vigor_tonic.json"]);
    assert.equal((revs[0].input as { engine: { promptVersion: string } }).engine.promptVersion, "mb-design-2026-10-10.1");
    assert.deepEqual(assets.map((a) => (a as { kind: string }).kind), ["design", "design", "design"]);
    assert.deepEqual(out!.designs!.map((d) => [d.name, d.serviceAgreed, d.configVersion]), [["void_reaper", true, 1], ["storm_staff", true, 1], ["vigor_tonic", true, 1]]);
    await syncBuildAssets(build, ar, deps);
    assert.equal(revs.length, 1, "idempotent"); assert.equal(assets.length, 3);
  });
});

toolu_01Xw1Jtv5M5vnhosZ1CaVNBw.content:
// Cyrus R3 gameplay designers (pure): the design IR (schema, every cap, semantic checks, static budget), the JSON Schema
// file, the verified component library (present, strict-scan clean, precheck clean, version adapter), the compiler
// (determinism, golden hashes per version, per-version differences), the parameter-edit path (only config.yml + README
// change), the change-request parser, the TS reference simulator (cooldowns, charges, permissions, branches, marks,
// budgets, re-entry guard, delayed steps, seeded random), TS == generated service JS, the prompt section, routing,
// the build request and the portal sync.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
