const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-designer");
const NS = "nx_r7design";
const load = (n: string): ItemDesign => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const ALL = () => ["void_reaper", "storm_staff", "vigor_tonic"].map(load);
const clone = <T,>(x: T): T => structuredClone(x);
const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: "VoidArsenal" });
const compileOk = (d: unknown[], c = ctx()): CompileOk => { const r = compileDesigns(d, c); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const SUPPORTED = VERSIONS.map((v) => v.id).filter((v) => designFeatures(v).ok);
const codes = (r: ReturnType<typeof validateDesign>) => r.errors.map((e) => e.code);

/** A small valid design to mutate. */
const probe = (actions: unknown[], trigger: unknown = { type: "right_click", targetRange: 8 }, extra: Record<string, unknown> = {}) => ({
  schemaVersion: 1, id: "probe", base: "minecraft:stick", name: { text: "Probe" },
  marks: [{ name: "m", durationTicks: 100, maxPerOwner: 4 }],
  abilities: [{ id: "a", name: "A", trigger, actions, cooldownTicks: 20, charges: { max: 2, regenTicks: 40 } }],
  ...extra,
});

describe("design IR: the three test designs", () => {
  it("are valid on every supported registry version (and 26.3 fails closed: no vanilla ids)", () => {
    assert.deepEqual(SUPPORTED, ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"]);
    for (const v of SUPPORTED) {
      const r = validateDesigns(ALL(), { version: v, namespace: NS });
      assert.ok(r.ok, `${v}: ${JSON.stringify(r.results.flatMap((x) => x.errors))}`);
    }
    const f = designFeatures("26.3");
    assert.equal(f.ok, false);
    assert.equal(validateDesign(load("void_reaper"), { version: "26.3", namespace: NS }).ok, false);
    assert.equal(designFeatures("1.21.1").ok && designFeatures("1.21.1").features.itemModel, false);
    assert.equal(designFeatures("1.21.1").ok && designFeatures("1.21.1").features.attributeNames, "generic-prefix");
    assert.equal(designFeatures("1.21.4").ok && designFeatures("1.21.4").features.attributeNames, "plain");
  });
  it("static budgets of the Void Reaper", () => {
    const r = validateDesign(load("void_reaper"), { version: "1.21.11", namespace: NS });
    assert.ok(r.ok);
    const pull = r.budgets.find((b) => b.ability === "void_pull")!;
    assert.deepEqual({ ...pull }, { ability: "void_pull", actions: 4 + 8 * 2, entities: 8, tasks: 0, particles: 8 * 20 + 1, projectiles: 0, nodes: 6, depth: 2 });
    const warn = validateDesign(load("void_reaper"), { version: "1.21.1", namespace: NS });
    assert.ok(warn.ok && warn.warnings.some((w) => w.code === "item_model_unsupported"));
  });
  it("the JSON Schema file is current and carries the caps", () => {
    const file = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/designer.v1.schema.json"), "utf8"));
    assert.deepEqual(file, designJsonSchema());
    assert.match(JSON.stringify(file), /"maximum":72000/);
  });
});

