    ["cooldownTicks", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), abilities: [{ id: "a", name: "A", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }], cooldownTicks: v }] }), true],
    ["chargesMax", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), abilities: [{ id: "a", name: "A", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }], charges: { max: v, regenTicks: 40 } }] }), true],
    ["chargeRegenTicks", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), abilities: [{ id: "a", name: "A", trigger: { type: "right_click" }, actions: [{ type: "heal", amount: 1 }], charges: { max: 2, regenTicks: v } }] }), true],
    ["targetRange", (v) => probe([{ type: "heal", amount: 1 }], { type: "right_click", targetRange: v }), false],
    ["periodTicks", (v) => probe([{ type: "heal", amount: 1 }], { type: "held_interval", periodTicks: v }), true],
    ["minChargeTicks", (v) => probe([{ type: "heal", amount: 1 }], { type: "charge_release", minChargeTicks: v, maxChargeTicks: 400, release: "unsneak" }), true],
    ["maxChargeTicks", (v) => probe([{ type: "heal", amount: 1 }], { type: "charge_release", minChargeTicks: 5, maxChargeTicks: v, release: "unsneak" }), true],
    ["damage", act({ type: "damage", amount: "$" }), false],
    ["heal", act({ type: "heal", amount: "$" }), false],
    ["potionTicks", act({ type: "potion_effect", effect: "speed", durationTicks: "$" }), true],
    ["amplifier", (v) => probe([{ type: "potion_effect", effect: "speed", durationTicks: 20, amplifier: v }]), true],
    ["strength", act({ type: "knockback", strength: "$" }), false],
    ["vertical", (v) => probe([{ type: "pull_to", to: "self", strength: 1, vertical: v }]), false],
    ["teleportRange", act({ type: "teleport_short", range: "$" }), false],
    ["projectileSpeed", act({ type: "launch_projectile", kind: "snowball", speed: "$" }), false],
    ["projectileLifetime", (v) => probe([{ type: "launch_projectile", kind: "arrow", speed: 1, lifetimeTicks: v }]), true],
    ["particleCount", act({ type: "spawn_particles", particle: "flame", count: "$" }), true],
    ["particleSpread", (v) => probe([{ type: "spawn_particles", particle: "flame", count: 1, spread: v }]), false],
    ["particleSpeed", (v) => probe([{ type: "spawn_particles", particle: "flame", count: 1, speed: v }]), false],
    ["volume", (v) => probe([{ type: "play_sound", sound: "minecraft:ui.button.click", volume: v }]), false],
    ["pitch", (v) => probe([{ type: "play_sound", sound: "minecraft:ui.button.click", pitch: v }]), false],
    ["giveCount", (v) => probe([{ type: "give_item", item: "minecraft:apple", count: v }]), true],
    ["chargeCost", (v) => probe([{ type: "consume_charge", amount: v }]), true],
    ["markTicks", (v) => ({ ...probe([{ type: "apply_mark", mark: "m" }]), marks: [{ name: "m", durationTicks: v, maxPerOwner: 2 }] }), true],
    ["marksPerOwner", (v) => ({ ...probe([{ type: "apply_mark", mark: "m" }]), marks: [{ name: "m", durationTicks: 100, maxPerOwner: v }] }), true],
    ["queryMarkedRadius", (v) => probe([{ type: "query_marked", mark: "m", radius: v, max: 2, actions: [{ type: "damage", amount: 1 }] }]), false],
    ["queryNearbyRadius", (v) => probe([{ type: "query_nearby", radius: v, max: 2, actions: [{ type: "damage", amount: 1 }] }]), false],
    ["queryMax", (v) => probe([{ type: "query_nearby", radius: 3, max: v, actions: [{ type: "damage", amount: 1 }] }]), true],
    ["delayTicks", (v) => probe([{ type: "delayed", delayTicks: v, actions: [{ type: "heal", amount: 1 }] }]), true],
    ["chance", (v) => probe([{ type: "branch", if: [{ type: "random_chance", chance: v }], then: [{ type: "heal", amount: 1 }] }]), false],
    ["healthFraction", (v) => probe([{ type: "branch", if: [{ type: "health_below", subject: "self", fraction: v }], then: [{ type: "heal", amount: 1 }] }]), false],
    ["timeOfDay", (v) => probe([{ type: "branch", if: [{ type: "time_of_day", from: v, to: 100 }], then: [{ type: "heal", amount: 1 }] }]), true],
    ["titleFadeTicks", (v) => probe([{ type: "title", title: "Hi", fadeInTicks: v }]), true],
    ["titleStayTicks", (v) => probe([{ type: "title", title: "Hi", stayTicks: v }]), true],
    ["passiveAmplifier", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), passives: [{ effect: "speed", amplifier: v, slot: "main_hand" }] }), true],
    ["lootChance", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), acquisition: { loot: [{ table: "minecraft:chests/simple_dungeon", chance: v }] } }), false],
    ["statDamage", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), stats: { damage: v, attackSpeed: 1.6 } }), false],
    ["statAttackSpeed", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), stats: { damage: 5, attackSpeed: v } }), false],
    ["durability", (v) => ({ ...probe([{ type: "heal", amount: 1 }]), stats: { durability: v } }), true],
  ];
  it(`covers all ${Object.keys(CAPS).length} caps`, () => {
    assert.deepEqual(T.map((t) => t[0]).sort(), (Object.keys(CAPS) as CapName[]).sort());
