  for (const [cap, mk, int] of T) {
    it(cap, () => {
      const [lo, hi] = CAPS[cap];
      const d = int ? 1 : 0.01;
      const v = (x: number) => validateDesign(mk(x), { version: "1.21.11", namespace: NS });
      assert.ok(v(lo).ok, `${cap} min ${lo}: ${JSON.stringify(v(lo).errors)}`);
      assert.ok(v(hi).ok, `${cap} max ${hi}: ${JSON.stringify(v(hi).errors)}`);
      if (!(cap === "cooldownTicks" && lo === 0) && !(lo === 0 && ["damage", "heal", "strength", "vertical", "particleSpread", "particleSpeed", "volume", "chance", "healthFraction", "timeOfDay", "titleFadeTicks", "amplifier", "passiveAmplifier", "lootChance"].includes(cap)) || lo - d >= -1) {
        const below = v(lo - d);
        if (lo - d >= 0 || lo > 0 || true) assert.equal(below.ok, false, `${cap} below min accepted`);
      }
      assert.equal(v(hi + d).ok, false, `${cap} above max accepted`);
    });
  }
});

describe("design IR: semantic checks", () => {
  const V = (d: unknown, items?: string[]) => validateDesign(d, { version: "1.21.11", namespace: NS, items });
  const has = (d: unknown, code: string) => assert.ok(codes(V(d)).includes(code), `${code} not in ${JSON.stringify(codes(V(d)))}`);
  it("refuses unknown keys, unknown action kinds (no run_command) and bad ids", () => {
    has({ ...probe([{ type: "heal", amount: 1 }]), script: "x" }, "schema");
    has(probe([{ type: "run_command", command: "op @a" }]), "schema");
    has({ ...probe([{ type: "heal", amount: 1 }]), id: "Bad Id" }, "schema");
    has({ ...probe([{ type: "heal", amount: 1 }]), schemaVersion: 2 }, "schema_version");
    assert.equal(validateDesign(probe([{ type: "heal", amount: 1 }]), { version: "1.21.11", namespace: "bad" }).ok, false);
  });
  it("base item rules", () => {
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:command_block" }, "banned_base");
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:zombie_spawn_egg" }, "banned_base");
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:stone" }, "block_base");
    has({ ...probe([{ type: "heal", amount: 1 }], { type: "item_consume" }), base: "minecraft:stick" }, "not_consumable");
    has({ ...probe([{ type: "heal", amount: 1 }]), base: "minecraft:rubyy" }, "unknown_vanilla_id");
    has({ ...probe([{ type: "heal", amount: 1 }]), stats: { damage: 5 } }, "stats_pair");
    assert.ok(V({ ...probe([{ type: "heal", amount: 1 }], { type: "item_consume" }), base: "minecraft:golden_apple" }).ok);
  });
  it("references", () => {
    has(probe([{ type: "apply_mark", mark: "nope" }]), "unresolved_ref");
    has(probe([{ type: "set_cooldown", ability: "nope", ticks: 5 }]), "unresolved_ref");
    has(probe([{ type: "heal", amount: 1 }], { type: "projectile_hit", tag: "bolt" }), "unresolved_ref");
    has(probe([{ type: "branch", if: [{ type: "has_permission", node: "vip" }], then: [{ type: "heal", amount: 1 }] }]), "undeclared_permission");
    assert.ok(V({ ...probe([{ type: "branch", if: [{ type: "has_permission", node: "vip" }], then: [{ type: "heal", amount: 1 }] }]), permissions: [{ node: "vip", description: "VIP", default: "op" }] }).ok);
    has({ ...probe([{ type: "heal", amount: 1 }]), permissions: [{ node: "give", description: "x", default: "op" }] }, "reserved_node");
    has(probe([{ type: "give_item", item: "other_thing" }]), "unresolved_ref");
    assert.ok(V(probe([{ type: "give_item", item: "other_thing" }]), ["other_thing"]).ok);
    has(probe([{ type: "give_item", item: "minecraft:command_block" }]), "banned_item");
    has(probe([{ type: "play_sound", sound: "nx_other123:x.y" }]), "foreign_namespace");
    has(probe([{ type: "query_nearby", radius: 3, max: 2, types: ["minecraft:zombiee"], actions: [{ type: "damage", amount: 1 }] }]), "unknown_vanilla_id");
    has({ ...probe([{ type: "heal", amount: 1 }]), acquisition: { loot: [{ table: "minecraft:chests/nope", chance: 0.1 }] } }, "unknown_vanilla_id");
    has({ ...probe([{ type: "heal", amount: 1 }]), assets: { model: "nx_other123:x" } }, "foreign_namespace");
  });
  it("context: targets, triggers, passives", () => {
    has(probe([{ type: "damage", amount: 1 }], { type: "join" }), "no_target");
    has(probe([{ type: "damage", amount: 1 }], { type: "right_click" }), "no_target");
    assert.ok(V(probe([{ type: "query_nearby", radius: 3, max: 2, actions: [{ type: "damage", amount: 1 }] }], { type: "join" })).ok, "inside a query the target exists");
    has(probe([{ type: "branch", if: [{ type: "target_is", kinds: ["hostile"] }], then: [{ type: "heal", amount: 1 }] }], { type: "held_interval", periodTicks: 20 }), "no_target");
    has({ ...probe([{ type: "heal", amount: 1 }], { type: "sneak_right_click" }), abilities: [{ id: "a", name: "A", trigger: { type: "sneak_right_click" }, actions: [{ type: "heal", amount: 1 }] }, { id: "b", name: "B", trigger: { type: "charge_release", minChargeTicks: 5, maxChargeTicks: 10, release: "right_click" }, actions: [{ type: "heal", amount: 1 }] }] }, "ambiguous_trigger");
    has(probe([{ type: "heal", amount: 1 }], { type: "charge_release", minChargeTicks: 50, maxChargeTicks: 20, release: "unsneak" }), "charge_order");
    has({ ...probe([{ type: "heal", amount: 1 }]), passives: [{ effect: "poison", slot: "main_hand" }] }, "harmful_passive");
    has({ ...probe([{ type: "heal", amount: 1 }]), passives: [{ effect: "instant_health", slot: "main_hand" }] }, "instant_passive");
    has(probe([{ type: "pull_to", to: "self", strength: 1, target: "self" }]), "self_pull");
  });
  it("budget and bounded structure", () => {
    has(probe([{ type: "query_nearby", radius: 3, max: 16, actions: [{ type: "spawn_particles", particle: "flame", count: 64 }] }]), "budget_particles");
    has(probe([{ type: "query_nearby", radius: 3, max: 16, actions: [{ type: "damage", amount: 1 }, { type: "knockback", strength: 1 }, { type: "heal", amount: 1, target: "target" }] }]), "budget_entities");
    has(probe([{ type: "query_nearby", radius: 3, max: 16, actions: [{ type: "query_marked", mark: "m", radius: 3, max: 2, actions: [{ type: "damage", amount: 1 }] }] }]), "nested_query");
    has(probe([{ type: "query_nearby", radius: 3, max: 2, actions: [{ type: "delayed", delayTicks: 5, actions: [{ type: "damage", amount: 1 }] }] }]), "delayed_in_loop");
    has(probe([{ type: "query_nearby", radius: 3, max: 2, actions: [{ type: "launch_projectile", kind: "snowball", speed: 1 }] }]), "projectile_in_loop");
    has(probe(Array.from({ length: 4 }, () => ({ type: "launch_projectile", kind: "snowball", speed: 1 }))), "budget_projectiles");
    const deep = { type: "delayed", delayTicks: 1, actions: [{ type: "branch", if: [{ type: "sneaking" }], then: [{ type: "delayed", delayTicks: 1, actions: [{ type: "heal", amount: 1 }] }] }] };
    has(probe([deep]), "too_deep");
    has(probe(Array.from({ length: 17 }, () => ({ type: "heal", amount: 1 }))), "schema");
  });
  it("recipes reuse the data pack shapes", () => {
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shaped", pattern: ["AB"], key: { A: "minecraft:stick" } } }, "pattern_key");
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shaped", pattern: ["A", "AA"], key: { A: "minecraft:stick" } } }, "pattern_rows");
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shapeless", ingredients: ["probe"] } }, "self_ingredient");
    has({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shapeless", ingredients: [["minecraft:stick", "#minecraft:planks"]] } }, "tag_in_alternatives");
    assert.ok(V({ ...probe([{ type: "heal", amount: 1 }]), recipe: { kind: "shapeless", ingredients: ["#minecraft:planks", "minecraft:stick"] } }).ok);
  });
  it("mod-level: duplicates, too many items, command clash, class clash", () => {
    const r = validateDesigns([load("void_reaper"), load("void_reaper")], { version: "1.21.11", namespace: NS });
    assert.ok(r.errors.some((e) => e.code === "duplicate_item"));
    assert.ok(validateDesigns(Array.from({ length: 7 }, (_, i) => ({ ...probe([{ type: "heal", amount: 1 }]), id: `p${i}x` })), { version: "1.21.11", namespace: NS }).errors.some((e) => e.code === "too_many_items"));
    const c = compileDesigns([load("vigor_tonic")], { ...ctx(), pluginName: "Give" });
    assert.ok(!c.ok && c.errors[0].code === "command_clash");
    const a = { ...probe([{ type: "heal", amount: 1 }]), id: "a_1" }, b = { ...probe([{ type: "heal", amount: 1 }]), id: "a1" };
    const cc = compileDesigns([a, b], ctx());
    assert.ok(!cc.ok && cc.errors[0].code === "class_clash");
  });
});

describe("component library + compiler", () => {
  const out = compileOk(ALL());
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-designer-"));
  for (const f of out.files) { fs.mkdirSync(path.dirname(path.join(tmp, f.path)), { recursive: true }); fs.writeFileSync(path.join(tmp, f.path), f.content); }
  const java = out.files.filter((f) => f.path.endsWith(".java"));
  it("every component is in the compiled tree, documented with families, limits and tests", () => {
    for (const c of COMPONENTS) {
      assert.ok(out.files.some((f) => f.path.endsWith(`/voidarsenal/${c.file}`)), c.id);
      assert.deepEqual(c.families, ["1.21", "26"]);
      assert.ok(c.tests.length >= 2 && c.purpose.length > 10, c.id);
    }
    assert.ok(out.files.some((f) => f.path.endsWith("designer/Compat.java") && f.role === "compat"));
    assert.equal(libraryHash(), libraryHash());
  });
  it("is deterministic and matches the golden hashes on every version", () => {
    const golden = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8"));
    assert.deepEqual(Object.keys(golden), SUPPORTED);
    for (const v of SUPPORTED) {
      const a = compileOk(ALL(), ctx(v)), b = compileOk(ALL().reverse(), ctx(v));
      assert.equal(a.hash, b.hash, `${v}: order-independent`);
      assert.equal(a.hash, golden[v].hash, `${v}: golden hash (regenerate with scripts/cyrus/designer-golden.ts and review)`);
      for (const f of a.files) assert.equal(f.sha256, golden[v].files[f.path.replace(/^src\/main\/java\/dev\/nxeon\/plugins\/voidarsenal\//, "")], `${v} ${f.path}`);
    }
  });
  it("per-version differences: GENERIC_ attributes + no item model on 1.21.1; api-version pinned; components identical", () => {
    const by = Object.fromEntries(SUPPORTED.map((v) => [v, compileOk(ALL(), ctx(v))]));
    const compat = (v: string) => by[v].files.find((f) => f.path.endsWith("Compat.java"))!.content;
    assert.match(compat("1.21.1"), /Attribute\.GENERIC_ATTACK_DAMAGE/);
    assert.doesNotMatch(compat("1.21.1"), /setItemModel/);
    for (const v of SUPPORTED.filter((x) => x !== "1.21.1")) { assert.match(compat(v), /Attribute\.ATTACK_DAMAGE;/); assert.match(compat(v), /meta\.setItemModel/); }
    for (const v of SUPPORTED) assert.match(by[v].files.find((f) => f.path.endsWith("plugin.yml"))!.content, new RegExp(`api-version: "${v.replace(/\./g, "\\.")}"`));
    for (const c of COMPONENTS) {
      const hs = new Set(SUPPORTED.map((v) => by[v].files.find((f) => f.path.endsWith(c.file))!.sha256));
      assert.equal(hs.size, 1, `${c.id} is version-independent`);
    }
    assert.ok(by["1.21.1"].notes.some((n) => /1\.21\.4 or newer/.test(n)));
    assert.deepEqual([...JAVAC_VERIFIED_VERSIONS], ["1.21.11", "26.2"]);
    assert.equal(by["1.21.11"].javacVerified, true); assert.equal(by["1.21.4"].javacVerified, false);
  });
  it("generated code uses only the components: no reflection, threads, network, commands, files outside the plugin folder", () => {
    const banned = /\b(Runtime|ProcessBuilder|java\.lang\.reflect|Class\.forName|getDeclared|MethodHandles|dispatchCommand|performCommand|new Thread|Executors|java\.net|HttpClient|System\.exit|setOp|getenv|ClassLoader|ObjectInputStream|Unsafe|ScriptEngine|runTaskAsynchronously|getRegionScheduler|getAsyncScheduler)\b/;
    for (const f of java) assert.doesNotMatch(f.content, banned, f.path);
    const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
    const findings = S.scanSource(java.map((f) => ({ abs: path.join(tmp, f.path), rel: f.path })));
    assert.deepEqual(findings, [], "strict source rules");
  });
  it("passes the build service's precheck rules for every version", () => {
    const pre = require(path.join(ROOT, "services/modbuilder/precheck.js"));
    for (const v of SUPPORTED) {
      const r = compileOk(ALL(), ctx(v));
      const d = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-designer-pre-"));
      const files = r.files.filter((f) => f.path.endsWith(".java")).map((f) => { const abs = path.join(d, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); return { abs, rel: f.path }; });
      assert.deepEqual(pre.precheck(files, v), [], v);
    }
  });
  it("config.yml: every parameter with its range, designer-values hash, config_version; plugin.yml: command + permissions", () => {
    const cfg = out.files.find((f) => f.path.endsWith("config.yml"))!.content;
