// REAL gameplay-designer runs ON node-2 (not part of the unit suite: real javac, real strict scan, real Paper boots).
//   scripts/devhost run --lock -- npx tsx test/cyrus-designer-real.ts --out /tank/nxeon-build/tmp/cyrus-r7-designer/results.json
// No real Minecraft client, no bot and no AI model: gameplay (clicks, hits, pulls, projectiles) is NOT exercised here;
// what runs is the compile lane, the safety scan and the server-side behaviour reachable from the console.
// Steps per lane (1.21.11 on JDK 21, 26.2 on JDK 25, each against the resolved Paper classpath):
//   1. compile the three test designs (TS compiler) -> javac --release N -proc:none -Xlint:deprecation,removal (0 warnings expected)
//   2. a catalog file referencing every curated particle / potion effect / projectile / consumable base: proves they exist
//   3. reproducible jar (sorted entries, fixed date) twice -> same sha256; strict scan (bytecode + source) -> no findings
//   4. Test Flight: plugin enabled, `help` + `/voidarsenal` answer, give/list/params, out-of-range config CLAMPED on
//      /voidarsenal reload, an old config_version MIGRATED, config.yml + backup on disk, no ERROR lines
//   5. parameter edit (cooldown, range, strength, sound): recompile -> only config.yml differs (every .class identical);
//      boot the edited jar over the OLD config.yml -> migrated to config_version 2 with the new values
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileDesigns, type CompileOk } from "../lib/cyrus/designer/compile";
import { recompileWithEdits } from "../lib/cyrus/designer/params";
import { CONSUMABLE_BASES, EFFECTS, PARTICLES, PROJECTILES } from "../lib/cyrus/designer/spec";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck } from "../lib/cyrus/testflight/types";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r7-designer/run-${Date.now().toString(36)}`;
const NS = "nx_r7design";
const LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const designs = () => ["void_reaper", "storm_staff", "vigor_tonic"].map((n) => JSON.parse(readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer", `${n}.json`), "utf8")));

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

/** Write the compiled tree, javac it, copy resources, build a reproducible jar. */
function build(r: CompileOk, lane: (typeof LANES)[number], tag: string) {
  const dir = path.join(RUN, `${lane.version}-${tag}`);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  const t0 = Date.now();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 6000)); }
  const javacMs = Date.now() - t0;
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jar = (out: string) => { execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", out, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]); return sha(readFileSync(out)); };
  const jarPath = path.join(dir, `VoidArsenal-${lane.version}-${tag}.jar`);
  const h1 = jar(jarPath), h2 = jar(path.join(dir, "again.jar"));
  return { dir, classes, sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacMs, javacWarnings: (javacOut.match(/warning:/g) ?? []).length, jarPath, jarSha256: h1, reproducible: h1 === h2, jarBytes: readFileSync(jarPath).length };
}

function scan(b: ReturnType<typeof build>, lane: (typeof LANES)[number]) {
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  try {
    const bytecode = S.scanBytecode(b.classes, { profile: "strict" });
    const src = walk(path.join(b.dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(b.dir, "ws"), abs) }));
    const source = S.scanSource(src, { profile: "strict" });
    const all = [...bytecode, ...source];
    return { profile: "strict", blocks: all.filter((f: { severity: string }) => f.severity === "block").length, warnings: all.filter((f: { severity: string }) => f.severity === "warn").length, findings: all.map((f: { severity: string; rule: string; where: string }) => `${f.severity}:${f.rule}@${f.where}`) };
  } finally { process.env.PATH = oldPath; }
}

function catalog(lane: (typeof LANES)[number]) {
  const dir = path.join(RUN, `catalog-${lane.version}`);
  mkdirSync(path.join(dir, "src/dev/nxeon/catalog"), { recursive: true });
  const proj: Record<string, string> = { snowball: "Snowball", arrow: "Arrow", small_fireball: "SmallFireball", wind_charge: "WindCharge" };
  const src = `package dev.nxeon.catalog;

import org.bukkit.Material;
import org.bukkit.Particle;
import org.bukkit.potion.PotionEffectType;

/** Every curated designer catalog entry must exist in this Paper API (compile-time check only, never shipped). */
public final class Catalog {
    static final Particle[] PARTICLES = { ${PARTICLES.map((p) => `Particle.${p.toUpperCase()}`).join(", ")} };
    static final PotionEffectType[] EFFECTS = { ${EFFECTS.map((e) => `PotionEffectType.${e.toUpperCase()}`).join(", ")} };
    static final Material[] CONSUMABLE_BASES = { ${CONSUMABLE_BASES.map((m) => `Material.${m.toUpperCase()}`).join(", ")} };
    static final Class<?>[] PROJECTILES = { ${PROJECTILES.map((p) => `org.bukkit.entity.${proj[p]}.class`).join(", ")} };
}
`;
  writeFileSync(path.join(dir, "src/dev/nxeon/catalog/Catalog.java"), src);
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  try {
    execFileSync(`${lane.jdk}/bin/javac`, ["--release", lane.release, "-proc:none", "-Xlint:deprecation,removal", "-cp", cp, "-d", path.join(dir, "classes"), path.join(dir, "src/dev/nxeon/catalog/Catalog.java")], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
    return { ok: true, particles: PARTICLES.length, effects: EFFECTS.length, consumableBases: CONSUMABLE_BASES.length, projectiles: PROJECTILES.length };
  } catch (e) { const x = e as { stderr?: string }; return { ok: false, error: String(x.stderr ?? e).slice(0, 4000) }; }
}

/** Kept server dir: did the plugin write config.yml (and the backup), and what config_version is on disk. */
function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const pd = path.join(dir, "plugins/VoidArsenal");
  out.configOnDisk = existsSync(path.join(pd, "config.yml"));
  if (out.configOnDisk) { const t = readFileSync(path.join(pd, "config.yml"), "utf8"); out.configVersionOnDisk = Number(/^config_version:\s*(\d+)/m.exec(t)?.[1] ?? NaN); out.designerValuesOnDisk = /^# designer-values: ([0-9a-f]{16})/m.exec(t)?.[1] ?? null; }
  out.backups = existsSync(pd) ? readdirSync(pd).filter((n) => n.startsWith("config.yml.bak")) : [];
  const log = path.join(dir, "logs/latest.log");
  out.pluginLog = existsSync(log) ? readFileSync(log, "utf8").split("\n").filter((l) => /VoidArsenal|voidarsenal|migrated|clamped/i.test(l) && !/Preparing/.test(l)).map((l) => l.slice(0, 300)).slice(0, 30) : [];
  out.errorLines = existsSync(log) ? readFileSync(log, "utf8").split("\n").filter((l) => /\/(ERROR|FATAL)\]|Exception/.test(l)).map((l) => l.slice(0, 300)).slice(0, 20) : [];
  rmSync(dir, { recursive: true, force: true }); // keepDir was only for this check
  return out;
}

