    L.flight = { status: f.report.status, overall: f.summary.overall, success: f.summary.success, line: describeSummary(f.summary), bootMs: f.report.bootMs, peakRssMb: (f.report as { peakRssMb?: number }).peakRssMb ?? null, checks: f.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 16) })), disk: harvest(f.report.runId ?? null) };
    console.log(`flight ${lane.version}: ${describeSummary(f.summary)}`);

    // parameter edit: only config.yml changes; the edited jar migrates an existing server's config
    const e = recompileWithEdits(c, [
      { path: `${P}cooldown_ticks`, value: 100 }, { path: `${P}trigger.target_range`, value: 30 },
      { path: `${P}a0.n0.strength`, value: 2 }, { path: `${P}a2.sound`, value: "minecraft:entity.warden.sonic_boom" },
    ], { version: lane.version, namespace: NS, pluginName: "VoidArsenal" });
    if (!e.ok) { L.edit = { ok: false, errors: e.errors }; continue; }
    const b2 = build(e.result, lane, "edit");
    const za = indexZip(readFileSync(b.jarPath)), zb = indexZip(readFileSync(b2.jarPath));
    const entryHashes = (z: ReturnType<typeof indexZip>) => (z.ok ? Object.fromEntries(z.zip.entries.map((x) => { const r = readEntry(z.zip, x); return [x.name, r.ok ? sha(r.data) : "?"]; })) : {});
    const ha = entryHashes(za), hb = entryHashes(zb);
    const differ = Object.keys({ ...ha, ...hb }).filter((k) => ha[k] !== hb[k]).sort();
    L.edit = { ok: true, applied: e.applied, sourceDiff: e.diff.changed.map((x) => x.path), javaChanged: e.diff.javaChanged, readmeChanged: e.diff.readmeChanged, configVersion: e.result.configVersion, jarEntriesThatDiffer: differ, classFilesIdentical: Object.keys(ha).filter((k) => k.endsWith(".class")).every((k) => ha[k] === hb[k]), jarSha256: b2.jarSha256 };
    const f2 = await fly({
      version: lane.version, plugins: [{ localPath: b2.jarPath, sha256: b2.jarSha256 }], files: [{ path: "plugins/VoidArsenal/config.yml", content: cfg }], keepDir: true,
      rcon: [
        { id: "plugins", command: "plugins", expect: ["VoidArsenal"] },
        { id: "params-after-update", command: "voidarsenal params void_reaper", expect: [`${P}cooldown_ticks=100`, `${P}trigger.target_range=30.0`, `${P}a0.n0.strength=2.0`, `${P}a2.sound=minecraft:entity.warden.sonic_boom`] },
      ],
    }, `edit flight ${lane.version}`);
    (L.edit as Record<string, unknown>).flight = { status: f2.report.status, overall: f2.summary.overall, success: f2.summary.success, line: describeSummary(f2.summary), checks: f2.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 12) })), disk: harvest(f2.report.runId ?? null) };
    console.log(`edit flight ${lane.version}: ${describeSummary(f2.summary)}; jar entries that differ: ${differ.join(", ")}`);
  }
  res.leftovers = { runsDir: readdirSync(path.join(TF, "runs")).length };
  if (oi > 0) writeFileSync(process.argv[oi + 1], JSON.stringify(res, null, 1));
  console.log(JSON.stringify(res, null, 1).slice(0, 4000));
  rmSync(RUN, { recursive: true, force: true });
}

main().catch((e) => { console.error(e); process.exit(1); });

